import { useEffect, useState } from "react";
import { createPortal } from "react-dom";
import { ArrowUpDown, Bell, BellOff, Check, CircleHelp, MonitorUp, PictureInPicture2, Play, Settings, Volume2, X } from "lucide-react";
import { sound } from "../audio/sound";
import { CaptureSession } from "../capture/capture";
import { locationRegion, withItems, type CountdownItem, type CountdownSection, type PanelId, type Region } from "../core/settings";
import { AlertFlash, StatusDot } from "./components";
import { IconPicker } from "./IconPicker";
import { DisclaimerModal, GuideModal, SettingsModal } from "./modals";
import type { PanelCommon } from "./Panel";
import { CountdownPanel } from "./panels/CountdownPanel";
import { HUNT_MODES, HuntStallPanel } from "./panels/HuntStallPanel";
import { RunePanel } from "./panels/RunePanel";
import { PipView, usePip } from "./Pip";
import { RegionPicker } from "./RegionPicker";
import { StoreProvider, useStore } from "./store";

type PickTarget = "huntStall" | "rune" | "buffBar" | "buffFavorites";

const PICK_TEXT: Record<PickTarget, { title: string; hint: string }> = {
  huntStall: { title: "경험치바 영역 선택", hint: "화면 맨 아래 경험치바를 숫자(%)까지 포함해서 드래그해주세요." },
  rune: { title: "미니맵 영역 선택", hint: "미니맵에서 제목줄·버튼을 빼고 지도 부분만 드래그해주세요. 실제 사냥터에서 잡아주세요." },
  buffBar: { title: "버프칸 영역 선택", hint: "화면 오른쪽 위 버프 아이콘 줄 전체를 드래그해주세요. 버프가 늘어나도 들어오도록 왼쪽·아래로 여유 있게 잡아주세요." },
  buffFavorites: {
    title: "버프 즐겨찾기 영역 선택",
    hint: "게임에서 켠 버프 즐겨찾기 창 전체를 드래그해주세요. 아이콘이 늘어나도 들어오게 여유 있게, 퀵슬롯과 겹치지 않게 잡아주세요.",
  },
};

export function App() {
  return (
    <StoreProvider>
      <Shell />
    </StoreProvider>
  );
}

function Shell() {
  const { settings, update, capture, setCapture } = useStore();
  const [modal, setModal] = useState<"guide" | "settings" | null>(null);
  const [picking, setPicking] = useState<PickTarget | null>(null);
  const [iconFor, setIconFor] = useState<{ section: CountdownSection; itemId: string } | null>(null);
  const [quickslotFor, setQuickslotFor] = useState<{ section: CountdownSection; itemId: string } | null>(null);
  const [reorder, setReorder] = useState(false);
  const pip = usePip();

  // 테스트용: ?video=주소 를 붙이면 녹화 영상을 화면 대신 분석한다.
  useEffect(() => {
    const url = new URLSearchParams(window.location.search).get("video");
    if (!url) return;
    let cancelled = false;
    CaptureSession.fromVideoUrl(url)
      .then((session) => {
        if (cancelled) session.stop();
        else setCapture(session);
      })
      .catch((error: unknown) => console.error("테스트 영상을 열지 못했어요", error));
    return () => {
      cancelled = true;
    };
  }, [setCapture]);

  const move = (index: number, delta: number) =>
    update((s) => {
      const order = [...s.panelOrder];
      const target = index + delta;
      const a = order[index];
      const b = order[target];
      if (a === undefined || b === undefined) return s;
      order[index] = b;
      order[target] = a;
      return { ...s, panelOrder: order };
    });

  const saveRegion = (target: PickTarget, region: Region) => {
    update((s) => {
      if (target === "huntStall") return { ...s, huntStall: { ...s.huntStall, region } };
      if (target === "rune") return { ...s, rune: { ...s.rune, region } };
      if (target === "buffFavorites") return { ...s, buffFavorites: { region } };
      return { ...s, buffBar: { region } };
    });
    setPicking(null);
  };

  const iconItem: CountdownItem | undefined = iconFor
    ? settings[iconFor.section].items.find((item) => item.id === iconFor.itemId)
    : undefined;
  const iconRegion = iconItem ? locationRegion(settings, iconItem.location) : null;
  const quickslotItem: CountdownItem | undefined = quickslotFor
    ? settings[quickslotFor.section].items.find((item) => item.id === quickslotFor.itemId)
    : undefined;

  return (
    <div className="app">
      <header className="topbar">
        <h1 className="brand">
          메이플 알리미<small>비공식 · 개인용</small>
        </h1>
        <nav className="nav" aria-label="메뉴">
          <button onClick={() => setModal("guide")}>
            <CircleHelp size={17} />
            사용 가이드
          </button>
          <button onClick={() => (pip.win ? pip.close() : void pip.open(settings.pip.size))}>
            <PictureInPicture2 size={17} />
            {pip.win ? "PIP 닫기" : "PIP 타이머"}
          </button>
          <button onClick={() => setModal("settings")}>
            <Settings size={17} />
            설정
          </button>
        </nav>
        <div className="spacer" />
        <CaptureControl />
      </header>

      {pip.error && <div className="banner warn">{pip.error}</div>}
      {settings.allDisabled && (
        <div className="banner warn">
          전체 알림이 꺼져 있어요. 타이머는 계속 돌지만 소리는 안 나요.
          <button className="btn small" onClick={() => update((s) => ({ ...s, allDisabled: false }))}>
            다시 켜기
          </button>
        </div>
      )}

      <div className="toolbar">
        <h2>알림</h2>
        <div className="spacer" />
        <label className="volume">
          <Volume2 size={17} aria-hidden /> 마스터 볼륨
          <input
            type="range"
            min={0}
            max={100}
            value={Math.round(settings.masterVolume * 100)}
            onChange={(e) => update((s) => ({ ...s, masterVolume: Number(e.target.value) / 100 }))}
            aria-label="마스터 볼륨"
          />
          <b>{Math.round(settings.masterVolume * 100)}%</b>
        </label>
        <button className="btn" onClick={() => void sound.play("test", { force: true })}>
          <Play size={15} />
          소리 테스트
        </button>
        <button
          className={`btn ${settings.allDisabled ? "primary" : "danger"}`}
          onClick={() => update((s) => ({ ...s, allDisabled: !s.allDisabled }))}
        >
          {settings.allDisabled ? <BellOff size={15} /> : <Bell size={15} />}
          {settings.allDisabled ? "전체 다시 켜기" : "전체 비활성화"}
        </button>
        <button className={`btn ${reorder ? "active" : ""}`} onClick={() => setReorder((v) => !v)}>
          {reorder ? <Check size={15} /> : <ArrowUpDown size={15} />}
          {reorder ? "순서 편집 완료" : "순서 편집"}
        </button>
      </div>

      <main className="panels">
        {settings.panelOrder.map((id, index) => {
          const common: PanelCommon = {
            reorder,
            index,
            count: settings.panelOrder.length,
            onMove: (delta) => move(index, delta),
          };
          return (
            <PanelSlot
              key={id}
              id={id}
              common={common}
              onPick={setPicking}
              onRegisterIcon={(section, item) => setIconFor({ section, itemId: item.id })}
              onPickQuickslot={(section, item) => setQuickslotFor({ section, itemId: item.id })}
            />
          );
        })}
      </main>

      <footer className="footer">
        <div>
          메이플 알리미는 비공식 개인용 보조 도구예요. 넥슨과 관계없고, 사용에 따른 책임은 사용자에게 있어요.
          <br />
          MapleStory 및 관련 저작물의 권리는 ㈜넥슨코리아에 있어요.
        </div>
        <div>설정은 이 브라우저에만 저장돼요.</div>
      </footer>

      <AlertFlash />
      {!settings.disclaimerAccepted && <DisclaimerModal onAccept={() => update((s) => ({ ...s, disclaimerAccepted: true }))} />}
      {modal === "guide" && <GuideModal onClose={() => setModal(null)} />}
      {modal === "settings" && <SettingsModal onClose={() => setModal(null)} />}
      {picking && capture && (
        <RegionPicker
          session={capture}
          title={picking === "huntStall" ? HUNT_MODES[settings.huntStall.mode].pick : PICK_TEXT[picking].title}
          hint={picking === "huntStall" ? HUNT_MODES[settings.huntStall.mode].hint : PICK_TEXT[picking].hint}
          initial={settings[picking].region}
          onSave={(region) => saveRegion(picking, region)}
          onClose={() => setPicking(null)}
        />
      )}
      {iconFor && iconItem && capture && iconRegion && (
        <IconPicker
          session={capture}
          region={iconRegion}
          label={iconItem.label}
          onSave={(icons) => {
            update((s) =>
              withItems(
                s,
                iconFor.section,
                // 직접 고른 아이콘이 우선 — 내장 모양 감지는 끄서, 내장 모양이 다른 아이콘을 잡아 고른 것을 덮어쓰지 않게 한다
                s[iconFor.section].items.map((item) => (item.id === iconFor.itemId ? { ...item, ...icons, preset: null } : item)),
              ),
            );
            setIconFor(null);
          }}
          onClose={() => setIconFor(null)}
        />
      )}
      {quickslotFor && quickslotItem && capture && (
        <RegionPicker
          session={capture}
          title={`퀵슬롯 아이콘 영역 — ${quickslotItem.label}`}
          hint="오른쪽 아래 퀵슬롯에서 이 스킬 아이콘 하나만, 쿨타임 숫자가 들어가게 드래그해주세요. 해상도를 바꾸면 다시 골라야 해요."
          initial={quickslotItem.quickslot}
          onSave={(region) => {
            update((s) =>
              withItems(
                s,
                quickslotFor.section,
                s[quickslotFor.section].items.map((item) => (item.id === quickslotFor.itemId ? { ...item, quickslot: region } : item)),
              ),
            );
            setQuickslotFor(null);
          }}
          onClose={() => setQuickslotFor(null)}
        />
      )}
      {pip.win && createPortal(<PipView />, pip.win.document.body)}
    </div>
  );
}

function PanelSlot({
  id,
  common,
  onPick,
  onRegisterIcon,
  onPickQuickslot,
}: {
  id: PanelId;
  common: PanelCommon;
  onPick: (target: PickTarget) => void;
  onRegisterIcon: (section: CountdownSection, item: CountdownItem) => void;
  onPickQuickslot: (section: CountdownSection, item: CountdownItem) => void;
}) {
  switch (id) {
    case "skill":
    case "buffExpiry":
    case "specialCore":
    case "booster":
    case "general":
      return (
        <CountdownPanel
          section={id}
          common={common}
          onPickBuffBar={() => onPick("buffBar")}
          onPickFavorites={() => onPick("buffFavorites")}
          onRegisterIcon={(item) => onRegisterIcon(id, item)}
          onPickQuickslot={(item) => onPickQuickslot(id, item)}
        />
      );
    case "huntStall":
      return <HuntStallPanel common={common} onPick={() => onPick("huntStall")} />;
    case "rune":
      return <RunePanel common={common} onPick={() => onPick("rune")} />;
  }
}

function CaptureControl() {
  const { capture, setCapture } = useStore();
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const start = async (kind: "screen" | "demo") => {
    setBusy(true);
    setError(null);
    try {
      const session = kind === "screen" ? await CaptureSession.fromScreen() : await CaptureSession.fromDemo();
      session.onEnded(() => setCapture(null));
      setCapture(session);
    } catch (e) {
      setError(
        e instanceof DOMException && e.name === "NotAllowedError"
          ? "화면 공유가 취소됐어요."
          : `화면 공유를 시작하지 못했어요: ${e instanceof Error ? e.message : String(e)}`,
      );
    } finally {
      setBusy(false);
    }
  };

  if (capture) {
    return (
      <div className="capture on">
        <StatusDot tone="ok">
          <span data-testid="capture-status">
            {capture.kind === "demo" ? "데모 화면" : capture.kind === "video" ? "테스트 영상" : "화면 공유 중"} · {capture.width}×{capture.height}
          </span>
        </StatusDot>
        <button
          className="btn small"
          onClick={() => {
            capture.stop();
            setCapture(null);
          }}
        >
          <X size={14} />
          중지
        </button>
      </div>
    );
  }

  const supported = CaptureSession.supported();
  return (
    <div className="capture off">
      <StatusDot tone="danger">
        <span data-testid="capture-status">화면 공유 필요</span>
      </StatusDot>
      <button className="btn small primary" disabled={busy || !supported} onClick={() => void start("screen")}>
        <MonitorUp size={14} />
        화면 선택
      </button>
      <button className="btn small" disabled={busy} onClick={() => void start("demo")}>
        데모로 체험
      </button>
      {!supported && <span className="err">화면 공유는 https 주소에서만 돼요</span>}
      {error && <span className="err">{error}</span>}
    </div>
  );
}
