import { useEffect, useRef, useState, type PointerEvent } from "react";
import { scaleRegion, type CaptureSession, type PixelRect } from "../capture/capture";
import type { Region } from "../core/settings";
import { Modal } from "./components";

export function RegionPicker({
  session,
  title,
  hint,
  initial,
  onSave,
  onClose,
}: {
  session: CaptureSession;
  title: string;
  hint: string;
  initial: Region | null;
  onSave: (region: Region) => void;
  onClose: () => void;
}) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [frame, setFrame] = useState(() => session.snapshot());
  const [rect, setRect] = useState<PixelRect | null>(() =>
    initial ? scaleRegion(initial, session.width, session.height) : null,
  );
  const dragStart = useRef<{ x: number; y: number } | null>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    canvas.width = frame.width;
    canvas.height = frame.height;
    canvas.getContext("2d")?.drawImage(frame, 0, 0);
  }, [frame]);

  const toSource = (e: PointerEvent<HTMLDivElement>) => {
    const canvas = canvasRef.current;
    if (!canvas) return { x: 0, y: 0 };
    const box = canvas.getBoundingClientRect();
    const x = ((e.clientX - box.left) * frame.width) / box.width;
    const y = ((e.clientY - box.top) * frame.height) / box.height;
    return { x: Math.max(0, Math.min(frame.width, x)), y: Math.max(0, Math.min(frame.height, y)) };
  };

  const valid = rect !== null && rect.w >= 4 && rect.h >= 4;
  const pct = (value: number, total: number) => `${(value / total) * 100}%`;

  return (
    <Modal
      title={title}
      onClose={onClose}
      wide
      footer={
        <>
          <span className="muted foot-info">
            {rect && valid ? `${Math.round(rect.w)}×${Math.round(rect.h)} 영역` : "드래그해서 영역을 그려주세요"}
          </span>
          <button className="btn" onClick={() => setFrame(session.snapshot())}>
            지금 화면 다시 찍기
          </button>
          <button className="btn" onClick={onClose}>
            취소
          </button>
          <button
            className="btn primary"
            disabled={!valid}
            onClick={() => {
              if (!rect || !valid) return;
              onSave({
                x: Math.round(rect.x),
                y: Math.round(rect.y),
                w: Math.round(rect.w),
                h: Math.round(rect.h),
                srcW: frame.width,
                srcH: frame.height,
              });
            }}
          >
            저장
          </button>
        </>
      }
    >
      <p className="muted">{hint}</p>
      <div
        className="picker"
        onPointerDown={(e) => {
          e.currentTarget.setPointerCapture(e.pointerId);
          const point = toSource(e);
          dragStart.current = point;
          setRect({ x: point.x, y: point.y, w: 0, h: 0 });
        }}
        onPointerMove={(e) => {
          const start = dragStart.current;
          if (!start) return;
          const point = toSource(e);
          setRect({
            x: Math.min(start.x, point.x),
            y: Math.min(start.y, point.y),
            w: Math.abs(point.x - start.x),
            h: Math.abs(point.y - start.y),
          });
        }}
        onPointerUp={() => {
          dragStart.current = null;
        }}
      >
        <canvas ref={canvasRef} />
        {rect && (
          <div
            className="sel"
            style={{
              left: pct(rect.x, frame.width),
              top: pct(rect.y, frame.height),
              width: pct(rect.w, frame.width),
              height: pct(rect.h, frame.height),
            }}
          />
        )}
      </div>
    </Modal>
  );
}
