import type { Box } from "./buffbar";
import { IconTracker, type Candidate, type TrackStatus } from "./tracker";

/**
 * 버프칸 한 아이콘의 주기를 잡는다.
 * - 1분 넘게 남은 동안: 아이콘이 밝고 노란 초가 없다. 밝을 때 등록한 아이콘이 새로 뜨면(타이머가 안 돌 때)
 *   지속시간으로 시작한다. 분이 바뀔 때마다 아이콘이 다시 밝아지므로 타이머가 도는 중에는 다시 시작하지 않는다.
 * - 1분 미만: 아이콘이 어두워지고 노란 초가 뜬다. 숫자로 정확히 맞춘다(IconTracker).
 * - 초가 보이다가 같은 아이콘이 다시 밝아지면 다시 쓴 것으로 보고 새로 시작한다.
 * - 밝은 아이콘은 1분 넘게 남았다는 뜻이다. 타이머가 1분도 안 남았다고 보는데 아이콘이 밝으면 지속시간이 늘어난 것
 *   (솔 야누스 + 루나 게더링)이므로 끝나는 시각을 뒤로 민다. 정확한 시각은 1분 밑으로 내려가 뜨는 초로 맞춘다.
 */
export interface WatchInput {
  /** 노란 숫자 후보 (이 아이콘과의 거리 포함) */
  candidates: readonly Candidate[];
  /** 밝을 때 등록한 아이콘이 이번 사진에서 찾아진 자리 */
  bright: { box: Box; distance: number } | null;
}

export interface WatchContext {
  durationSec: number;
  /** 이 항목 타이머가 지금 도는 중인지 */
  running: boolean;
  endAt: number | null;
  /** 지속시간이 늘어날 수 있는 버프(솔 야누스 — 루나 게더링). 늘어난 주기로 지속시간을 배우지 않는다 */
  extendable?: boolean;
}

export type WatchStatus = TrackStatus | "bright";

export interface WatchResult {
  status: WatchStatus;
  endAt: number | null;
  value: number | null;
  /** 알림을 새로 짜야 하는 새 주기 */
  restarted: boolean;
  /** 이번에 이 아이콘 것으로 읽은 숫자 후보 (candidates 안 번호) */
  matchedIndex: number | null;
  /** 밝을 때 시작한 주기를 숫자로 넘겨받으며 알게 된 실제 지속시간(초) */
  learnedDurationSec: number | null;
  /** 밝은 아이콘이 보여 끝나는 시각을 뒤로 민 것(지속시간이 늘어남) */
  extended: boolean;
}

/** 밝은 아이콘이 이만큼 연달아(0.5초 간격) 보여야 새로 뜬 것으로 본다 */
const BRIGHT_CONFIRM = 2;
const BRIGHT_GAP_MS = 1500;
/** 숫자가 보인 지 이 안에 아이콘이 다시 밝아지면 다시 쓴 것 */
const RECAST_WINDOW_MS = 3000;
/** 밝을 때 시작한 주기와 숫자로 읽은 끝 시각이 이만큼 안이면 같은 주기 */
const SAME_CYCLE_MS = 15_000;
/** 밝은 아이콘은 적어도 이만큼 남았다는 뜻 */
const BRIGHT_MIN_REMAINING_MS = 60_000;
/** 타이머가 이보다 적게 남았다고 보는데 아이콘이 밝으면 늘어난 것 (분이 바뀌는 순간·판독 지연 여유) */
const EXTEND_BELOW_MS = 55_000;
/**
 * 밝은 아이콘을 이 안에 본 칸의 숫자만 이 아이콘 것으로 본다 — 오래전에 본 칸은 버프칸이 밀려 다른 아이콘일 수 있다.
 * 밝은 아이콘은 분이 끝나갈수록 어두워져 마지막 15~20초는 못 찾으므로 그보다 넉넉하게 둔다.
 */
const SLOT_FRESH_MS = 30_000;

function matchedIndex(candidates: readonly Candidate[], value: number): number | null {
  let index: number | null = null;
  candidates.forEach((c, i) => {
    if (c.value !== value || !Number.isFinite(c.distance)) return;
    if (index === null || c.distance < (candidates[index] as Candidate).distance) index = i;
  });
  return index;
}

export class BuffWatcher {
  private readonly tracker = new IconTracker();
  private brightHits = 0;
  private lastBrightAt: number | null = null;
  private brightBox: Box | null = null;
  private lastNumberAt: number | null = null;
  /** 밝은 아이콘으로 시작한 주기의 시작 시각 */
  private cycleStartAt: number | null = null;
  /** 이번 주기에 밝은 아이콘을 보고 끝나는 시각을 뒤로 민 적이 있는지 */
  private extendedCycle = false;
  /** 이번 주기로 지속시간을 배워도 되는지 — 돌던 타이머를 다시 시작한 주기(다시 설치·연장)는 쓰지 않는다 */
  private learnable = false;

  update(now: number, input: WatchInput, ctx: WatchContext): WatchResult {
    if (input.bright) {
      const consecutive = this.lastBrightAt !== null && now - this.lastBrightAt <= BRIGHT_GAP_MS;
      this.brightHits = consecutive ? this.brightHits + 1 : 1;
      this.lastBrightAt = now;
      this.brightBox = input.bright.box;
      const recast = this.lastNumberAt !== null && now - this.lastNumberAt <= RECAST_WINDOW_MS;
      if (this.brightHits === BRIGHT_CONFIRM && (!ctx.running || recast)) {
        this.tracker.reset();
        this.lastNumberAt = null;
        // 두 번째로 본 때다 — 한 장(0.5초) 전쯤 썼다고 본다
        this.cycleStartAt = now - 500;
        this.extendedCycle = false;
        this.learnable = !ctx.running;
        return {
          status: "bright",
          endAt: this.cycleStartAt + ctx.durationSec * 1000,
          value: null,
          restarted: true,
          matchedIndex: null,
          learnedDurationSec: null,
          extended: false,
        };
      }
      // 밝은 아이콘 = 1분 넘게 남음. 타이머가 그보다 적게 남았다고 보면(이미 끝난 것 포함) 지속시간이 늘어난 것이다.
      // 얼마나 늘었는지는 화면에서 알 수 없으니 적어도 1분 남은 것으로 계속 밀고, 1분 밑으로 내려가 뜨는 초로 정확히 맞춘다.
      if (this.brightHits >= BRIGHT_CONFIRM && ctx.endAt !== null && ctx.endAt - now < EXTEND_BELOW_MS) {
        const first = !this.extendedCycle;
        this.extendedCycle = true;
        return {
          status: "bright",
          endAt: now + BRIGHT_MIN_REMAINING_MS,
          value: null,
          // 처음 밀 때는 알림을 새로 짠다 — 이미 일찍 울렸어도 늘어난 끝에 맞춰 다시 울리게
          restarted: first,
          matchedIndex: null,
          learnedDurationSec: null,
          extended: true,
        };
      }
    }

    const tracked = this.tracker.update(now, input.candidates);
    if (tracked.status === "tracking" && tracked.value !== null && tracked.endAt !== null) {
      this.lastNumberAt = now;
      let restarted = tracked.restarted;
      let learnedDurationSec: number | null = null;
      // 늘어난 주기(루나 게더링)는 실제 지속시간이 아니다
      const canLearn = !(ctx.extendable && this.extendedCycle);
      if (tracked.restarted && this.cycleStartAt !== null) {
        const inferred = Math.round((tracked.endAt - this.cycleStartAt) / 1000);
        // 앱을 버프 도중에 켰으면 밝아진 때가 쓴 때보다 늦어 짧게 나온다 → 늘리는 쪽으로만 고친다
        if (canLearn && this.learnable && inferred > ctx.durationSec + 3 && inferred <= 7200) learnedDurationSec = inferred;
        // 같은 주기를 숫자로 넘겨받은 것이면 알림을 다시 짜지 않고 시각만 고친다
        if (ctx.running && ctx.endAt !== null && Math.abs(ctx.endAt - tracked.endAt) <= SAME_CYCLE_MS) restarted = false;
        this.cycleStartAt = null;
      } else if (tracked.restarted && !ctx.extendable && tracked.value > ctx.durationSec + 3 && tracked.value <= 7200) {
        // '분:초' 표시는 처음부터 남은 시간이 보인다 — 설정보다 길면 실제 지속시간은 적어도 그만큼이다
        learnedDurationSec = Math.ceil(tracked.value);
      }
      // 숫자로 새 주기를 잡았으면 지난 주기의 연장 표시는 지운다
      if (restarted) this.extendedCycle = false;
      return {
        status: "tracking",
        endAt: tracked.endAt,
        value: tracked.value,
        restarted,
        matchedIndex: matchedIndex(input.candidates, tracked.value),
        learnedDurationSec,
        extended: false,
      };
    }

    const brightNow = this.lastBrightAt !== null && now - this.lastBrightAt <= BRIGHT_GAP_MS;
    const status: WatchStatus = brightNow || (ctx.running && this.cycleStartAt !== null) ? "bright" : tracked.status;
    return { status, endAt: tracked.endAt, value: null, restarted: false, matchedIndex: null, learnedDurationSec: null, extended: false };
  }

  /** 숫자 아이콘 모양을 아직 모를 때: 밝은 아이콘을 최근에 본 칸에 뜬 숫자를 이 아이콘 것으로 본다 */
  slotDistance(cx: number, cy: number, pitch: number, now: number): number {
    const box = this.brightBox;
    if (!box || this.lastBrightAt === null || now - this.lastBrightAt > SLOT_FRESH_MS) return Number.POSITIVE_INFINITY;
    const inside = Math.abs(cx - (box.x + box.w / 2)) <= pitch * 0.5 && Math.abs(cy - (box.y + box.h / 2)) <= pitch * 0.6;
    return inside ? 0 : Number.POSITIVE_INFINITY;
  }
}
