export type Voice = (typeof VOICES)[number]["id"];

const VOICE_IDS: ReadonlySet<string> = new Set(VOICES.map((voice) => voice.id));

export function isVoice(value: unknown): value is Voice {
  return typeof value === "string" && VOICE_IDS.has(value);
}

export interface RepeatConfig {
  enabled: boolean;
  intervalSec: number;
  count: number;
}

export interface RandomDelay {
  enabled: boolean;
  minSec: number;
  maxSec: number;
}

/** 원본 영상 해상도(srcW×srcH) 기준 픽셀 좌표. 해상도가 바뀌면 비율로 맞춘다. */
export interface Region {
  x: number;
  y: number;
  w: number;
  h: number;
  srcW: number;
  srcH: number;
}

export interface CountdownItem {
  id: string;
  enabled: boolean;
  label: string;
  icon: string;
  durationSec: number;
  /** 종료 몇 초 전에 울릴지. 음수면 종료 후 그만큼 지나서 울린다. */
  leadSec: number;
  repeat: RepeatConfig;
  sound: SoundId;
  /** 노란 초가 떠 있는(1분 미만, 어두운) 아이콘 모양. 밝을 때 등록했으면 처음 초가 뜰 때 자동으로 배운다 */
  autoIcon: IconTemplate | null;
  /** 1분 넘게 남아 밝을 때 등록한 아이콘 — 다시 뜨면 지속시간으로 시작한다 */
  autoBright: IconTemplate | null;
  /** 내장 아이콘(야누스·파운틴)으로 고르지 않아도 알아서 찾기 — 잡으면 실제 모양을 배워 autoBright/autoIcon 으로 넘어간다 */
  preset: PresetId | null;
  /** 퀵슬롯 방식: 스킬 쿨타임(초). 퀵슬롯에 쿨타임 숫자가 뜨면 쓴 시각을 거꾸로 계산한다 */
  cooldownSec: number | null;
  /** 퀵슬롯 방식: 이 스킬의 퀵슬롯 아이콘 영역 */
  quickslot: Region | null;
  /** 끝나면 다시 시작(일반 타이머) */
  autoRestart: boolean;
  /** 자동 재시작 전에 기다릴 초(원본의 '재시작 대기') */
  autoRestartDelaySec: number;
  /** 이 알림 볼륨(0~1). 마스터 볼륨과 곱한다 */
  volume: number;
  /** 자동 감지 위치: 기본 버프칸(오른쪽 위) / 버프 즐겨찾기 창 */
  location: BuffLocation;
  /** 버프 연계(일반 타이머): 버프 종료 알림의 버프가 감지될 때만 진행 */
  requireTrackedBuff: boolean;
  /** 부스터: 화면 맨 위 가운데 '남은시간 NN.NN초' 타이머를 읽어 맞춘다(원본 부스터 종료 알림) */
  screenTimer: boolean;
}

export type BuffLocation = "buffBar" | "favorites";

/** 사냥 중인지 무엇의 변화로 볼지: 경험치바·퀵슬롯 쿨타임·MP */
export type HuntMode = "exp" | "cooldown" | "mana";
/** PIP 창: 사냥용(특수 코어 빼고 전부) / 보스용(특수 코어만) */
export type PipMode = "hunt" | "boss";
export type PipSize = "default" | "large" | "focus";
export type FlashColor = "yellow" | "red" | "cyan" | "purple" | "white";
export type FlashStrength = "soft" | "normal" | "strong";

export type CountdownSection = "skill" | "buffExpiry" | "specialCore" | "booster" | "general";
export const COUNTDOWN_SECTIONS: readonly CountdownSection[] = ["skill", "buffExpiry", "booster", "general"];
/** 버프칸 숫자를 읽어 자동으로 맞출 수 있는 섹션 */
export const AUTO_SECTIONS: readonly CountdownSection[] = ["skill", "buffExpiry", "booster"];

export interface Settings {
  version: 1;
  masterVolume: number;
  allDisabled: boolean;
  voice: Voice;
  /** 알림마다 여러 문구 중 하나를 무작위로(원본의 '랜덤' 음성) */
  randomPhrase: boolean;
  desktopNotify: boolean;
  pip: { mode: PipMode; size: PipSize };
  /** 알림이 울릴 때 화면·PIP 를 반짝이는 효과 */
  alertEffect: { enabled: boolean; color: FlashColor; strength: FlashStrength; blink: boolean };
  disclaimerAccepted: boolean;
  panelOrder: PanelId[];
  collapsed: Partial<Record<PanelId, boolean>>;
  /** 화면 오른쪽 위 버프 아이콘 줄 */
  buffBar: { region: Region | null };
  /** 게임에서 켠 버프 즐겨찾기 창(왼쪽 아래·오른쪽 아래 등) */
  buffFavorites: { region: Region | null };
  skill: { randomDelay: RandomDelay; items: CountdownItem[] };
  rune: { enabled: boolean; region: Region | null; repeat: RepeatConfig; volume: number };
  huntStall: {
    enabled: boolean;
    region: Region | null;
    stallSec: number;
    mode: HuntMode;
    /** 몇 픽셀 이상 바뀌어야 경험치 변화로 볼지 */
    sensitivity: number;
    repeat: RepeatConfig;
    /** 버프 연계: 버프 종료 알림의 버프가 감지될 때만 감시 */
    requireTrackedBuff: boolean;
    volume: number;
  };
  buffExpiry: { items: CountdownItem[] };
  specialCore: { items: CountdownItem[] };
  booster: { items: CountdownItem[] };
  general: { randomDelay: RandomDelay; items: CountdownItem[] };
}

export const SETTINGS_KEY = "maple-alimi.settings.v1";

export function noRepeat(): RepeatConfig {
  return { enabled: false, intervalSec: 10, count: 2 };
}

export function makeCountdown(
  init: Pick<CountdownItem, "label" | "durationSec" | "sound"> & Partial<CountdownItem>,
): CountdownItem {
  return { id: uid(), enabled: true, icon: "⏱️", leadSec: 0, repeat: noRepeat(), autoIcon: null, autoBright: null, preset: null, cooldownSec: null, quickslot: null, autoRestart: false, autoRestartDelaySec: 0, volume: 1, location: "buffBar", requireTrackedBuff: false, screenTimer: false, ...init };
}

