export function clamp(value: number, lo: number, hi: number): number {
  return Math.min(hi, Math.max(lo, value));
}

function isObj(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

/** 버프칸을 고르지 않았을 때 쓰는 자동 범위: 화면 오른쪽 위(가로 45~100%, 세로 0~22%). 0~1 비율 좌표 */
export const AUTO_BUFF_BAR: Region = { x: 0.45, y: 0, w: 0.55, h: 0.22, srcW: 1, srcH: 1 };

/** 항목 감지 위치의 영역. 기본 버프칸은 고르지 않았으면 오른쪽 위를 알아서 본다 */
export function locationRegion(settings: Settings, location: BuffLocation): Region | null {
  return location === "favorites" ? settings.buffFavorites.region : (settings.buffBar.region ?? AUTO_BUFF_BAR);
}

function pickOne<T extends string>(raw: unknown, allowed: readonly T[], fallback: T): T {
  return typeof raw === "string" && (allowed as readonly string[]).includes(raw) ? (raw as T) : fallback;
}

function mergePip(raw: unknown): Settings["pip"] {
  const r = isObj(raw) ? raw : {};
  return { mode: pickOne(r.mode, ["hunt", "boss"] as const, "hunt"), size: pickOne(r.size, ["default", "large", "focus"] as const, "default") };
}

function mergeAlertEffect(raw: unknown): Settings["alertEffect"] {
  const r = isObj(raw) ? raw : {};
  return {
    enabled: r.enabled !== false,
    color: pickOne(r.color, ["yellow", "red", "cyan", "purple", "white"] as const, "yellow"),
    strength: pickOne(r.strength, ["soft", "normal", "strong"] as const, "normal"),
    blink: r.blink !== false,
  };
}

export function normalizeOrder(order: unknown): PanelId[] {
  const seen = new Set<PanelId>();
  const out: PanelId[] = [];
  if (Array.isArray(order)) {
    for (const id of order) {
      if (typeof id === "string" && (PANEL_IDS as readonly string[]).includes(id) && !seen.has(id as PanelId)) {
        seen.add(id as PanelId);
        out.push(id as PanelId);
      }
    }
  }
  for (const id of PANEL_IDS) if (!seen.has(id)) out.push(id);
  return out;
}

function mergeVolume(raw: unknown): number {
  return typeof raw === "number" && Number.isFinite(raw) ? clamp(raw, 0, 1) : 1;
}

function mergeRepeat(raw: unknown): RepeatConfig {
  return { ...noRepeat(), ...(isObj(raw) ? (raw as Partial<RepeatConfig>) : {}) };
}

function mergeRandomDelay(base: RandomDelay, raw: unknown): RandomDelay {
  return { ...base, ...(isObj(raw) ? (raw as Partial<RandomDelay>) : {}) };
}

function mergeRegion(raw: unknown): Region | null {
  if (!isObj(raw)) return null;
  const keys = ["x", "y", "w", "h", "srcW", "srcH"] as const;
  if (!keys.every((k) => typeof raw[k] === "number" && Number.isFinite(raw[k]))) return null;
  return raw as unknown as Region;
}

function mergeIconTemplate(raw: unknown): IconTemplate | null {
  if (!isObj(raw) || !Array.isArray(raw.cells) || typeof raw.size !== "number") return null;
  if (raw.cells.length !== ICON_GRID * ICON_GRID * 3 || !raw.cells.every((v) => typeof v === "number")) return null;
  return { cells: raw.cells as number[], size: raw.size, ...(raw.textBand === true ? { textBand: true } : {}) };
}

function mergeItems(section: CountdownSection, baseItems: CountdownItem[], raw: unknown): CountdownItem[] {
  if (!Array.isArray(raw)) return baseItems;
  return raw.filter(isObj).map((item) => {
    const fallback = makeCountdown({ label: "타이머", durationSec: 60, sound: "timerDone" });
    const merged = { ...fallback, ...(item as Partial<CountdownItem>) };
    return {
      ...merged,
      id: typeof item.id === "string" && item.id ? item.id : fallback.id,
      // 예전 이모지 기본 아이콘은 원본 사이트와 같은 그림으로 바꾼다
      icon: migrateIcon(section, typeof item.icon === "string" ? item.icon : fallback.icon, String(merged.label)),
      repeat: mergeRepeat(item.repeat),
      autoIcon: mergeIconTemplate(item.autoIcon),
      autoBright: mergeIconTemplate(item.autoBright),
      preset: mergePreset(item.preset, merged.sound),
      cooldownSec: typeof item.cooldownSec === "number" && item.cooldownSec > 0 ? item.cooldownSec : null,
      quickslot: mergeRegion(item.quickslot),
      autoRestart: item.autoRestart === true,
      autoRestartDelaySec:
        typeof item.autoRestartDelaySec === "number" && Number.isFinite(item.autoRestartDelaySec)
          ? clamp(Math.round(item.autoRestartDelaySec), 0, 3600)
          : 0,
      volume: mergeVolume(item.volume),
      location: item.location === "favorites" ? "favorites" : "buffBar",
      requireTrackedBuff: item.requireTrackedBuff === true,
      // 예전 설정의 부스터 항목은 타이머 읽기를 켠 것으로 본다
      screenTimer: typeof item.screenTimer === "boolean" ? item.screenTimer : section === "booster",
    };
  });
}

/** 예전 설정(칸 없음)은 알림음으로 야누스·파운틴을 알아본다. null 은 사용자가 끈 것 */
function mergePreset(raw: unknown, sound: SoundId): PresetId | null {
  if (raw === null) return null;
  if (raw === "janus" || raw === "fountain") return raw;
  return sound === "janus" ? "janus" : sound === "fountain" ? "fountain" : null;
}

/** 저장된 값(구버전·손상 포함)을 현재 형태로 맞춘다. 모르는 값은 기본값으로. */
export function mergeSettings(raw: unknown): Settings {
  const base = defaultSettings();
  if (!isObj(raw)) return base;
  const r = raw as Partial<Record<keyof Settings, unknown>>;
  const section = (key: keyof Settings) => (isObj(r[key]) ? (r[key] as Record<string, unknown>) : {});
  const skill = section("skill");
  const rune = section("rune");
  const hunt = section("huntStall");
  const buff = section("buffExpiry");
  const general = section("general");
  const buffBar = section("buffBar");
  const buffFavorites = section("buffFavorites");
  return {
    ...base,
    masterVolume: typeof r.masterVolume === "number" ? clamp(r.masterVolume, 0, 1) : base.masterVolume,
    allDisabled: r.allDisabled === true,
    voice: isVoice(r.voice) ? r.voice : "st-f1",
    randomPhrase: r.randomPhrase === true,
    desktopNotify: r.desktopNotify === true,
    pip: mergePip(r.pip),
    alertEffect: mergeAlertEffect(r.alertEffect),
    disclaimerAccepted: r.disclaimerAccepted === true,
    panelOrder: normalizeOrder(r.panelOrder),
    collapsed: isObj(r.collapsed) ? (r.collapsed as Settings["collapsed"]) : {},
    skill: {
      randomDelay: mergeRandomDelay(base.skill.randomDelay, skill.randomDelay),
      items: mergeItems("skill", base.skill.items, skill.items),
    },
    buffBar: { region: mergeRegion(buffBar.region) },
    buffFavorites: { region: mergeRegion(buffFavorites.region) },
    rune: {
      enabled: typeof rune.enabled === "boolean" ? rune.enabled : base.rune.enabled,
      region: mergeRegion(rune.region),
      repeat: mergeRepeat(rune.repeat),
      volume: mergeVolume(rune.volume),
    },
    huntStall: {
      enabled: hunt.enabled === true,
      region: mergeRegion(hunt.region),
      stallSec: typeof hunt.stallSec === "number" ? clamp(hunt.stallSec, 3, 3600) : base.huntStall.stallSec,
      mode: ((m: unknown): HuntMode => (m === "cooldown" || m === "mana" ? m : "exp"))(hunt.mode),
      sensitivity:
        typeof hunt.sensitivity === "number" ? clamp(hunt.sensitivity, 1, 500) : base.huntStall.sensitivity,
      repeat: mergeRepeat(hunt.repeat),
      requireTrackedBuff: hunt.requireTrackedBuff === true,
      volume: mergeVolume(hunt.volume),
    },
    // 예전 형태({enabled, leadSec})는 항목이 없으므로 빈 목록으로 시작한다.
    buffExpiry: { items: mergeItems("buffExpiry", base.buffExpiry.items, buff.items) },
    specialCore: { items: mergeItems("specialCore", base.specialCore.items, section("specialCore").items) },
    booster: { items: mergeItems("booster", base.booster.items, section("booster").items) },
    general: {
      randomDelay: mergeRandomDelay(base.general.randomDelay, general.randomDelay),
      items: mergeItems("general", base.general.items, general.items),
    },
  };
}

export function loadSettings(storage: Pick<Storage, "getItem"> = localStorage): Settings {
  const raw = storage.getItem(SETTINGS_KEY);
  if (!raw) return defaultSettings();
  try {
    return mergeSettings(JSON.parse(raw));
  } catch (error) {
    console.warn("저장된 설정을 읽지 못해 기본값으로 시작합니다", error);
    return defaultSettings();
  }
}

export function saveSettings(settings: Settings, storage: Pick<Storage, "setItem"> = localStorage): void {
  storage.setItem(SETTINGS_KEY, JSON.stringify(settings));
}

export function itemsOf(settings: Settings, section: CountdownSection): CountdownItem[] {
  return settings[section].items;
}

export function withItems(settings: Settings, section: CountdownSection, items: CountdownItem[]): Settings {
  switch (section) {
    case "skill":
      return { ...settings, skill: { ...settings.skill, items } };
    case "buffExpiry":
      return { ...settings, buffExpiry: { items } };
    case "specialCore":
      return { ...settings, specialCore: { items } };
    case "booster":
      return { ...settings, booster: { items } };
    case "general":
      return { ...settings, general: { ...settings.general, items } };
  }
}

export function randomDelayOf(settings: Settings, section: CountdownSection): RandomDelay | null {
  if (section === "skill") return settings.skill.randomDelay;
  if (section === "general") return settings.general.randomDelay;
  return null;
}

export function withRandomDelay(settings: Settings, section: "skill" | "general", randomDelay: RandomDelay): Settings {
  return section === "skill"
    ? { ...settings, skill: { ...settings.skill, randomDelay } }
    : { ...settings, general: { ...settings.general, randomDelay } };
}
