import type { CountdownState } from "./alarm";
import type { CountdownItem } from "./settings";

/** 버프 종료 알림의 버프가 지금 있는지 — 버프 연계(일반 타이머·사냥 멈춤)가 이걸 보고 진행·감시한다 */
export type BuffPresence = "present" | "absent" | "unknown" | "disabled";

export const PRESENCE_LABELS: Record<BuffPresence, string> = {
  present: "버프 감지됨",
  absent: "버프 감지 대기",
  unknown: "버프 확인 불가",
  disabled: "버프 알림 꺼짐",
};

/** 아이콘을 마지막으로 본 뒤 이만큼은 아직 있는 것으로 본다(분이 바뀌며 아이콘이 어두워지는 순간 등) */
export const PRESENCE_HOLD_MS = 5000;

export function hasDetection(item: CountdownItem): boolean {
  return Boolean(item.autoIcon || item.autoBright || item.preset);
}

/**
 * 켜진 버프 종료 알림 항목 중 하나라도 있으면 present.
 * - 타이머가 도는 중(감지로 맞췄든 ▶ 로 시작했든)이거나, 아이콘을 방금 봤으면 있음
 * - 감지하는 항목을 지금 볼 수 있는데 없으면 absent, 화면 공유·영역이 없어 못 보면 unknown
 * - 켜진 항목이 없으면 disabled
 */
export function buffPresence(input: {
  items: readonly CountdownItem[];
  countdowns: Readonly<Record<string, CountdownState>>;
  /** 항목 id → 아이콘을 마지막으로 본 시각 */
  seenAt: ReadonlyMap<string, number>;
  /** 이 항목 아이콘을 지금 화면에서 볼 수 있는지(화면 공유 + 감지 위치 영역) */
  canSee: (item: CountdownItem) => boolean;
  now: number;
}): BuffPresence {
  const sources = input.items.filter((item) => item.enabled);
  if (sources.length === 0) return "disabled";
  for (const item of sources) {
    if (input.countdowns[item.id]?.status === "running") return "present";
    const seen = input.seenAt.get(item.id);
    if (seen !== undefined && input.now - seen <= PRESENCE_HOLD_MS) return "present";
  }
  const detecting = sources.filter(hasDetection);
  if (detecting.some(input.canSee)) return "absent";
  return detecting.length > 0 ? "unknown" : "absent";
}
