import { createContext, useCallback, useContext, useEffect, useMemo, useRef, useState, type ReactNode } from "react";
import {
  AUTO_SECTIONS,
  COUNTDOWN_SECTIONS,
  loadSettings,
  randomDelayOf,
  locationRegion,
  saveSettings,
  withItems,
  type BuffLocation,
  type CountdownItem,
  type CountdownSection,
  type RandomDelay,
  type Settings,
  type SoundId,
} from "../core/settings";
import {
  holdCountdown,
  parseCountdownState,
  pauseCountdown,
  planFires,
  resumeCountdown,
  startCountdown,
  syncCountdown,
  takeDue,
  tickCountdown,
  type CountdownState,
} from "../core/alarm";
import { buffPresence, type BuffPresence } from "../core/presence";
import {
  alignedDistance,
  brightTemplate,
  findBright,
  iconBox,
  iconDistance,
  iconLayout,
  scanBuffBar,
  slotRingDistance,
  toTemplate,
} from "../detect/buffbar";
import { PRESET_MATCH, PRESETS } from "../detect/presets";
import { BoosterWatcher, readBoosterTimer } from "../detect/booster";
import { detectRune, RuneDebouncer, type RuneHit } from "../detect/rune";
import { DEFAULT_TRACKER } from "../detect/tracker";
import { readNumbers } from "../detect/digits";
import { DIGIT_TEMPLATES } from "../detect/digit-templates";
import { QuickslotWatcher } from "../detect/quickslot";
import { BuffWatcher, type WatchStatus } from "../detect/watch";
import { startTicker } from "../core/ticker";
import { desktopNotify, sound } from "../audio/sound";
import type { CaptureSession } from "../capture/capture";
import { ChangeDetector, toGray } from "../detect/change";

const RUNTIME_KEY = "maple-alimi.runtime.v1";
const TICK_MS = 250;
const HUNT_SAMPLE_MS = 500;
const BUFF_SAMPLE_MS = 500;
const RUNE_SAMPLE_MS = 1000;

export interface AutoStatus {
  status: WatchStatus;
  /** 이번에 읽은 남은 초 */
  value: number | null;
  at: number;
}

export interface RuneRuntime {
  watching: boolean;
  present: boolean;
  lastSeenAt: number | null;
  fires: number[];
  nextFire: number;
  lastAlertAt: number | null;
  /** 이번에 룬으로 본 자리(영역 안 좌표) — 미리보기에 표시 */
  hit: RuneHit | null;
}

function idleRune(): RuneRuntime {
  return { watching: false, present: false, lastSeenAt: null, fires: [], nextFire: 0, lastAlertAt: null, hit: null };
}

export interface HuntRuntime {
  watching: boolean;
  lastChangeAt: number | null;
  changedPixels: number;
  fires: number[];
  nextFire: number;
  planStallSec: number;
  lastAlertAt: number | null;
  stalled: boolean;
  /** 버프 연계로 감시를 쉬는 중(버프 종료 알림의 버프가 안 보임) */
  blocked: boolean;
}

function idleHunt(): HuntRuntime {
  return {
    blocked: false,
    watching: false,
    lastChangeAt: null,
    changedPixels: 0,
    fires: [],
    nextFire: 0,
    planStallSec: 0,
    lastAlertAt: null,
    stalled: false,
  };
}

export interface CountdownControls {
  start: (section: CountdownSection, item: CountdownItem) => void;
  pause: (id: string) => void;
  resume: (section: CountdownSection, item: CountdownItem) => void;
  reset: (id: string) => void;
}

interface StoreValue {
  settings: Settings;
  update: (fn: (settings: Settings) => Settings) => void;
  countdowns: Record<string, CountdownState>;
  now: number;
  capture: CaptureSession | null;
  setCapture: (session: CaptureSession | null) => void;
  hunt: HuntRuntime;
  /** 자동 감지(등록 아이콘) 상태, 항목 id 별 */
  auto: Record<string, AutoStatus>;
  rune: RuneRuntime;
  controls: CountdownControls;
  /** 마지막으로 알림이 울린 시각 — 반짝임 효과용 */
  flashAt: number | null;
  /** 버프 종료 알림의 버프가 지금 있는지 — 버프 연계용 */
  presence: BuffPresence;
}

const StoreContext = createContext<StoreValue | null>(null);

export function useStore(): StoreValue {
  const value = useContext(StoreContext);
  if (!value) throw new Error("StoreProvider 밖에서 useStore 를 호출했어요");
  return value;
}

function loadRuntime(): Record<string, CountdownState> {
  const raw = localStorage.getItem(RUNTIME_KEY);
  if (!raw) return {};
  try {
    const parsed: unknown = JSON.parse(raw);
    if (typeof parsed !== "object" || parsed === null) return {};
    const out: Record<string, CountdownState> = {};
    for (const [id, value] of Object.entries(parsed)) {
      const state = parseCountdownState(value);
      if (state) out[id] = state;
    }
    return out;
  } catch (error) {
    console.warn("저장된 타이머 상태를 읽지 못해 비워서 시작합니다", error);
    return {};
  }
}

function activeRandomDelay(settings: Settings, section: CountdownSection): RandomDelay | null {
  const randomDelay = randomDelayOf(settings, section);
  return randomDelay?.enabled ? randomDelay : null;
}

export function StoreProvider({ children }: { children: ReactNode }) {
  const [settings, setSettings] = useState<Settings>(() => loadSettings());
  const [countdowns, setCountdowns] = useState<Record<string, CountdownState>>(() => loadRuntime());
  const [now, setNow] = useState(() => Date.now());
  const [capture, setCaptureState] = useState<CaptureSession | null>(null);
  const [hunt, setHunt] = useState<HuntRuntime>(idleHunt);
  const [auto, setAuto] = useState<Record<string, AutoStatus>>({});
  const [rune, setRune] = useState<RuneRuntime>(idleRune);
  const [flashAt, setFlashAt] = useState<number | null>(null);
  const [presence, setPresence] = useState<BuffPresence>("disabled");

  const settingsRef = useRef(settings);
  const countdownsRef = useRef(countdowns);
  const captureRef = useRef(capture);
  const huntRef = useRef(hunt);
  const detectorRef = useRef(new ChangeDetector(settings.huntStall.sensitivity));
  const lastHuntSampleRef = useRef(0);
  const lastBuffSampleRef = useRef(0);
  const lastRuneSampleRef = useRef(0);
  const watchersRef = useRef(new Map<string, BuffWatcher>());
  const quickslotWatchersRef = useRef(new Map<string, QuickslotWatcher>());
  const boosterWatchersRef = useRef(new Map<string, BoosterWatcher>());
  const autoRef = useRef<Record<string, AutoStatus>>({});
  const runeRef = useRef<RuneRuntime>(idleRune());
  const runeDebouncerRef = useRef(new RuneDebouncer());
  const presenceRef = useRef<BuffPresence>("disabled");
  /** 항목 id → 아이콘을 마지막으로 본 시각(버프 연계용) */
  const seenAtRef = useRef(new Map<string, number>());

  const update = useCallback((fn: (current: Settings) => Settings) => {
    const next = fn(settingsRef.current);
    settingsRef.current = next;
    setSettings(next);
  }, []);

  const commitCountdowns = useCallback((next: Record<string, CountdownState>) => {
    countdownsRef.current = next;
    setCountdowns(next);
    localStorage.setItem(RUNTIME_KEY, JSON.stringify(next));
  }, []);

  const setCapture = useCallback((session: CaptureSession | null) => {
    captureRef.current = session;
    setCaptureState(session);
  }, []);

  useEffect(() => {
    saveSettings(settings);
    sound.master = settings.masterVolume;
    sound.voice = settings.voice;
    sound.randomPhrase = settings.randomPhrase;
    sound.muted = settings.allDisabled;
  }, [settings]);

  const fire = useCallback((id: SoundId, title: string, volume = 1) => {
    const current = settingsRef.current;
    if (current.allDisabled) return;
    void sound.play(id, { volume });
    setFlashAt(Date.now());
    if (current.desktopNotify) desktopNotify(title);
  }, []);

  useEffect(() => {
    const stepHunt = (t: number) => {
      const config = settingsRef.current.huntStall;
      const session = captureRef.current;
      const previous = huntRef.current;
      const detector = detectorRef.current;
      if (!session || !config.enabled || !config.region) {
        if (previous.watching || previous.blocked) {
          detector.reset();
          huntRef.current = idleHunt();
          setHunt(huntRef.current);
        }
        return;
      }
      // 버프 연계: 버프 종료 알림의 버프가 없으면 감시를 쉬고, 다시 잡히면 그때부터 새로 셈다.
      if (config.requireTrackedBuff && presenceRef.current !== "present") {
        if (previous.watching || !previous.blocked) {
          detector.reset();
          huntRef.current = { ...idleHunt(), blocked: true };
          setHunt(huntRef.current);
        }
        return;
      }
      const image = session.grab(config.region);
      if (!image) return;
      detector.minPixels = config.sensitivity;
      const changed = detector.feed(toGray(image).gray, t);
      let next: HuntRuntime = previous;
      if (changed || !previous.watching || previous.planStallSec !== config.stallSec) {
        const base = detector.lastChangeAt ?? t;
        next = {
          ...previous,
          watching: true,
          blocked: false,
          lastChangeAt: base,
          fires: planFires(base + config.stallSec * 1000, 0, null, config.repeat),
          nextFire: 0,
          planStallSec: config.stallSec,
        };
      }
      const due = takeDue(next.fires, next.nextFire, t);
      next = {
        ...next,
        nextFire: due.nextIndex,
        changedPixels: detector.lastChangedPixels,
        stalled: next.lastChangeAt !== null && t - next.lastChangeAt >= config.stallSec * 1000,
        lastAlertAt: due.fired ? t : next.lastAlertAt,
      };
      if (due.fired) fire("huntStall", "사냥이 멈춘 것 같아요", config.volume);
      huntRef.current = next;
      setHunt(next);
    };

    const stepBuffs = (t: number) => {
      const current = settingsRef.current;
      const session = captureRef.current;
      const targets = AUTO_SECTIONS.flatMap((section) =>
        current[section].items
          .filter((item) => item.enabled && !item.quickslot && !item.screenTimer && (item.autoIcon || item.autoBright || item.preset))
          .map((item) => ({ section, item })),
      );
      if (!session || targets.length === 0) {
        watchersRef.current.clear();
        if (Object.keys(autoRef.current).length) {
          autoRef.current = {};
          setAuto({});
        }
        return;
      }
      // 감지 위치(기본 버프칸·즐겨찾기)마다 한 장씩 찍어 숫자 판독·칸 배치를 같이 쓴다.
      const makeView = (location: BuffLocation) => {
        const region = locationRegion(current, location);
        const image = region ? session.grab(region) : null;
        return image ? { image, sightings: scanBuffBar(image), layout: iconLayout(image) } : null;
      };
      const views = new Map<BuffLocation, ReturnType<typeof makeView>>();
      const viewOf = (location: BuffLocation) => {
        if (!views.has(location)) views.set(location, makeView(location));
        return views.get(location) ?? null;
      };
      const nextAuto: Record<string, AutoStatus> = {};
      let nextCountdowns: Record<string, CountdownState> | null = null;
      const learned: { section: CountdownSection; id: string; patch: Partial<CountdownItem> }[] = [];
      for (const { section, item } of targets) {
        const view = viewOf(item.location);
        if (!view) continue;
        const { image, sightings, layout } = view;
        const template = item.autoIcon;
        let watcher = watchersRef.current.get(item.id);
        if (!watcher) {
          watcher = new BuffWatcher();
          watchersRef.current.set(item.id, watcher);
        }
        // 설정한 지속시간보다 훨씬 큰 값은 숫자를 잘못 읽은 것(예: 23을 83으로)으로 보고 버린다.
        // '분:초'(쌍점 확인)은 잘못 읽을 일이 적고 설정값이 실제보다 짧을 수 있어 2시간까지 받는다.
        const maxValue = Math.max(15, item.durationSec * 1.2 + 5);
        const usable = sightings.filter((sighting) => sighting.number.value <= (sighting.number.colon ? Math.max(maxValue, 7200) : maxValue));
        const pitch = layout?.pitch ?? 45;
        const preset = item.preset ? PRESETS[item.preset] : null;
        const presetMatch = item.preset ? PRESET_MATCH[item.preset] : null;
        // 내장 모양(초 표시): 가장 가까운 숫자 아이콘이 문턱 안이고 2등과 충분히 떨어질 때만 이 아이콘으로 본다.
        let presetPick = -1;
        if (!template && preset && presetMatch && layout) {
          const ranked = usable
            .map((sighting, index) => ({
              index,
              distance: slotRingDistance(image, sighting.number.cx, sighting.number.cy, layout, preset.dim, sighting.number.colon === true),
            }))
            .sort((a, b) => a.distance - b.distance);
          const [best, second] = ranked;
          if (best && best.distance <= presetMatch.dim && (!second || second.distance - best.distance >= presetMatch.dimMargin)) {
            presetPick = best.index;
          }
        }
        const candidates = usable.map((sighting, index) => {
          // '분:초' 글자는 가로로 길게 덮으므로 가운데 줄 전체를 빼고 비교한다
          const wide = sighting.number.colon === true || template?.textBand === true;
          return {
            value: sighting.number.value,
            cx: sighting.number.cx,
            distance: template
              ? // 대충 비교해 확실히 다른 아이콘은 정렬 탐색을 건너뛴다.
                iconDistance(sighting.signature, template.cells, wide) > DEFAULT_TRACKER.follow * 2.2
                ? Number.POSITIVE_INFINITY
                : alignedDistance(image, iconBox(sighting.number, image.width, image.height, template.size), template, 4, wide).distance
              : // 숫자 아이콘 모양을 아직 모르면 밝은 아이콘을 최근에 본 칸의 숫자를 이 아이콘 것으로 본다.
                Math.min(watcher.slotDistance(sighting.number.cx, sighting.number.cy, pitch, t), index === presetPick ? 0 : Number.POSITIVE_INFINITY),
          };
        });
        let bright = item.autoBright ? findBright(image, item.autoBright, layout) : null;
        // 내장 모양(밝을 때): 고르지 않았어도 막 쓴 아이콘을 찾는다. 잡히면 그 화면의 실제 모양을 배운다.
        let brightFromPreset = false;
        if (!item.autoBright && preset?.bright && presetMatch && layout) {
          const hit = findBright(image, { cells: preset.bright as number[], size: layout.side }, layout, presetMatch.bright);
          if (hit && hit.runnerUp - hit.distance >= presetMatch.brightMargin) {
            bright = hit;
            brightFromPreset = true;
          }
        }
        const state: CountdownState | undefined = (nextCountdowns ?? countdownsRef.current)[item.id];
        const result = watcher.update(
          t,
          { candidates, bright },
          {
            durationSec: item.durationSec,
            running: state?.status === "running",
            endAt: state?.endAt ?? null,
            // 솔 야누스는 루나 게더링으로 지속시간이 늘어난다
            extendable: item.preset === "janus" || item.sound === "janus",
          },
        );
        nextAuto[item.id] = { status: result.status, value: result.value, at: t };
        // 버프 연계용: 이번 사진에서 아이콘을 실제로 봤는지(밝은 아이콘이나 이 아이콘의 초)
        if (bright || (result.status === "tracking" && result.value !== null)) seenAtRef.current.set(item.id, t);
        if (result.endAt !== null && (result.restarted || result.value !== null || result.extended)) {
          const synced = syncCountdown(state, item, activeRandomDelay(current, section), result.endAt, t, result.restarted);
          if (synced !== state) nextCountdowns = { ...(nextCountdowns ?? countdownsRef.current), [item.id]: synced };
        }
        // 밝을 때 고른 아이콘: 처음 초가 뜬 아이콘 모양을 배워 두고(칸이 밀려도 찾게), 실제 지속시간도 맞춘다.
        const patch: Partial<CountdownItem> = {};
        const matched = result.matchedIndex === null ? undefined : usable[result.matchedIndex];
        if (!template && matched) patch.autoIcon = toTemplate(matched);
        if (brightFromPreset && bright && result.restarted) patch.autoBright = brightTemplate(image, bright.box);
        if (result.learnedDurationSec !== null) patch.durationSec = result.learnedDurationSec;
        if (Object.keys(patch).length) learned.push({ section, id: item.id, patch });
      }
      for (const id of [...watchersRef.current.keys()]) {
        if (!targets.some((target) => target.item.id === id)) watchersRef.current.delete(id);
      }
      if (nextCountdowns) commitCountdowns(nextCountdowns);
      if (learned.length) {
        update((s) =>
          learned.reduce(
            (acc, { section, id, patch }) =>
              withItems(
                acc,
                section,
                acc[section].items.map((it) => (it.id === id ? { ...it, ...patch } : it)),
              ),
            s,
          ),
        );
      }
      autoRef.current = nextAuto;
      setAuto(nextAuto);
    };

    // 퀵슬롯 방식: 스킬 아이콘 위 쿨타임 숫자가 줄기 시작하면 쓴 시각을 계산해 타이머를 맞춘다.
    const stepQuickslots = (t: number) => {
      const current = settingsRef.current;
      const session = captureRef.current;
      const targets = AUTO_SECTIONS.flatMap((section) =>
        current[section].items.filter((item) => item.enabled && item.quickslot).map((item) => ({ section, item })),
      );
      if (!session || targets.length === 0) {
        quickslotWatchersRef.current.clear();
        return;
      }
      let nextCountdowns: Record<string, CountdownState> | null = null;
      const nextAuto: Record<string, AutoStatus> = { ...autoRef.current };
      for (const { section, item } of targets) {
        if (!item.quickslot) continue;
        const image = session.grab(item.quickslot);
        if (!image) continue;
        let watcher = quickslotWatchersRef.current.get(item.id);
        if (!watcher) {
          watcher = new QuickslotWatcher();
          quickslotWatchersRef.current.set(item.id, watcher);
        }
        const result = watcher.update(t, readNumbers(image, DIGIT_TEMPLATES), item.cooldownSec);
        nextAuto[item.id] = { status: result.tracking ? "tracking" : "idle", value: result.value, at: t };
        if (result.castAt === null) continue;
        const endAt = result.castAt + item.durationSec * 1000;
        if (endAt <= t) continue;
        const state: CountdownState | undefined = (nextCountdowns ?? countdownsRef.current)[item.id];
        const synced = syncCountdown(state, item, activeRandomDelay(current, section), endAt, t, true);
        nextCountdowns = { ...(nextCountdowns ?? countdownsRef.current), [item.id]: synced };
      }
      for (const id of [...quickslotWatchersRef.current.keys()]) {
        if (!targets.some((target) => target.item.id === id)) quickslotWatchersRef.current.delete(id);
      }
      if (nextCountdowns) commitCountdowns(nextCountdowns);
      autoRef.current = nextAuto;
      setAuto(nextAuto);
    };

    // 부스터: 화면 맨 위 가운데 '남은시간 NN.NN초' 타이머를 읽어 끝나는 시각을 맞춘다(원본 부스터 종료 알림).
    const stepBoosters = (t: number) => {
      const current = settingsRef.current;
      const session = captureRef.current;
      const targets = current.booster.items.filter((item) => item.enabled && item.screenTimer);
      if (!session || targets.length === 0) {
        boosterWatchersRef.current.clear();
        return;
      }
      const W = session.width;
      const H = session.height;
      if (!W || !H) return;
      const image = // 게임 창만 공유하면 맨 위, 브라우저·영상 창째 공유하면 조금 아래에 있다 → 가로 25~75%, 세로 0~25%
      session.grab({ x: Math.round(W * 0.25), y: 0, w: Math.round(W * 0.5), h: Math.round(H * 0.25), srcW: W, srcH: H });
      if (!image) return;
      const reading = readBoosterTimer(image, Math.max(8, Math.round(H * 0.014)));
      let nextCountdowns: Record<string, CountdownState> | null = null;
      const nextAuto: Record<string, AutoStatus> = { ...autoRef.current };
      for (const item of targets) {
        let watcher = boosterWatchersRef.current.get(item.id);
        if (!watcher) {
          watcher = new BoosterWatcher();
          boosterWatchersRef.current.set(item.id, watcher);
        }
        const result = watcher.update(t, reading);
        nextAuto[item.id] = {
          status: result.status === "armed" ? "tracking" : result.status === "lost" ? "lost" : "idle",
          value: result.seconds === null ? null : Math.floor(result.seconds),
          at: t,
        };
        if (result.status !== "armed" || result.endAt === null) continue;
        const state: CountdownState | undefined = (nextCountdowns ?? countdownsRef.current)[item.id];
        let synced = syncCountdown(state, item, null, result.endAt, t, result.started);
        // 처음 확인했을 때 이미 알림 시각이 지났으면 이번에는 울리지 않는다(원본과 같게)
        if (result.started && result.endAt - item.leadSec * 1000 <= t) synced = { ...synced, nextFire: synced.fires.length };
        if (synced !== state) nextCountdowns = { ...(nextCountdowns ?? countdownsRef.current), [item.id]: synced };
      }
      for (const id of [...boosterWatchersRef.current.keys()]) {
        if (!targets.some((target) => target.id === id)) boosterWatchersRef.current.delete(id);
      }
      if (nextCountdowns) commitCountdowns(nextCountdowns);
      autoRef.current = nextAuto;
      setAuto(nextAuto);
    };

    const stepRune = (t: number) => {
      const config = settingsRef.current.rune;
      const session = captureRef.current;
      const debouncer = runeDebouncerRef.current;
      if (!session || !config.enabled || !config.region) {
        if (runeRef.current.watching) {
          debouncer.reset();
          runeRef.current = idleRune();
          setRune(runeRef.current);
        }
        return;
      }
      const image = session.grab(config.region);
      if (!image) return;
      const hit = detectRune(image);
      const change = debouncer.update(hit !== null);
      let next: RuneRuntime = {
        ...runeRef.current,
        watching: true,
        present: change.present,
        lastSeenAt: hit ? t : runeRef.current.lastSeenAt,
        hit,
      };
      if (change.appeared) next = { ...next, fires: planFires(t, 0, null, config.repeat), nextFire: 0 };
      if (change.vanished) next = { ...next, fires: [], nextFire: 0 };
      const due = takeDue(next.fires, next.nextFire, t);
      if (due.fired) {
        next = { ...next, nextFire: due.nextIndex, lastAlertAt: t };
        fire("rune", "룬이 나타났어요", config.volume);
      }
      runeRef.current = next;
      setRune(next);
    };

    const computePresence = (t: number): BuffPresence => {
      const current = settingsRef.current;
      const session = captureRef.current;
      return buffPresence({
        items: current.buffExpiry.items,
        countdowns: countdownsRef.current,
        seenAt: seenAtRef.current,
        canSee: (item) => session !== null && locationRegion(current, item.location) !== null,
        now: t,
      });
    };

    // 버프 연계한 일반 타이머: 버프가 없으면 멈춰 두고, 다시 잡히면 이어서 돌린다.
    const applyBuffLink = (t: number) => {
      const current = settingsRef.current;
      const present = presenceRef.current === "present";
      let next: Record<string, CountdownState> | null = null;
      for (const item of current.general.items) {
        const state: CountdownState | undefined = (next ?? countdownsRef.current)[item.id];
        if (!state || !item.enabled) continue;
        if (item.requireTrackedBuff && !present && state.status === "running") {
          next = { ...(next ?? countdownsRef.current), [item.id]: holdCountdown(state, item, t) };
        } else if ((present || !item.requireTrackedBuff) && state.status === "paused" && state.heldByBuff) {
          // 버프가 다시 잡혔거나 연계를 끈 것
          const resumed = resumeCountdown(state, item, activeRandomDelay(current, "general"), t);
          next = { ...(next ?? countdownsRef.current), [item.id]: resumed };
        }
      }
      if (next) commitCountdowns(next);
    };

    const onTick = () => {
      const t = Date.now();
      const current = settingsRef.current;
      let next: Record<string, CountdownState> | null = null;
      for (const section of COUNTDOWN_SECTIONS) {
        for (const item of current[section].items) {
          const state: CountdownState | undefined = (next ?? countdownsRef.current)[item.id];
          if (!state) continue;
          const result = tickCountdown(state, t);
          if (result.state !== state) next = { ...(next ?? countdownsRef.current), [item.id]: result.state };
          if (result.fired && item.enabled) fire(item.sound, `${item.label} 알림`, item.volume);
          // 자동 재시작: 끝나면 [재시작 대기]초 뒤부터 같은 지속시간으로 다시 돈다
          if (item.autoRestart && item.enabled && state.status === "running" && result.state.status === "done") {
            const startAt = t + item.autoRestartDelaySec * 1000;
            const restarted = startCountdown(item, activeRandomDelay(current, section), startAt);
            next = { ...(next ?? countdownsRef.current), [item.id]: startAt > t ? { ...restarted, startAt } : restarted };
          }
        }
      }
      if (next) commitCountdowns(next);
      if (t - lastHuntSampleRef.current >= HUNT_SAMPLE_MS) {
        lastHuntSampleRef.current = t;
        stepHunt(t);
      }
      if (t - lastBuffSampleRef.current >= BUFF_SAMPLE_MS) {
        lastBuffSampleRef.current = t;
        stepBuffs(t);
        stepQuickslots(t);
        stepBoosters(t);
      }
      if (t - lastRuneSampleRef.current >= RUNE_SAMPLE_MS) {
        lastRuneSampleRef.current = t;
        stepRune(t);
      }
      const presenceNow = computePresence(t);
      if (presenceNow !== presenceRef.current) {
        presenceRef.current = presenceNow;
        setPresence(presenceNow);
      }
      applyBuffLink(t);
      setNow(t);
    };

    return startTicker(TICK_MS, onTick);
  }, [commitCountdowns, fire]);

  const controls = useMemo<CountdownControls>(() => {
    // 버프 연계한 일반 타이머는 버프가 없으면 시작·재개 대신 멈춰 두고, 버프가 잡히면 이어서 돈다.
    const blocked = (section: CountdownSection, item: CountdownItem) =>
      section === "general" && item.requireTrackedBuff && presenceRef.current !== "present";
    return {
      start: (section, item) => {
        const t = Date.now();
        const started = startCountdown(item, activeRandomDelay(settingsRef.current, section), t);
        const state = blocked(section, item) ? holdCountdown(started, item, t) : started;
        commitCountdowns({ ...countdownsRef.current, [item.id]: state });
      },
      pause: (id) => {
        const state = countdownsRef.current[id];
        if (!state) return;
        // 직접 멈춘 건 버프가 잡혀도 저절로 이어지지 않는다
        const paused = state.heldByBuff ? { ...state, heldByBuff: false } : pauseCountdown(state, Date.now());
        commitCountdowns({ ...countdownsRef.current, [id]: paused });
      },
      resume: (section, item) => {
        const state = countdownsRef.current[item.id];
        if (!state) return;
        const t = Date.now();
        const resumed = blocked(section, item)
          ? holdCountdown(state, item, t)
          : resumeCountdown(state, item, activeRandomDelay(settingsRef.current, section), t);
        commitCountdowns({ ...countdownsRef.current, [item.id]: resumed });
      },
      reset: (id) => {
        if (!(id in countdownsRef.current)) return;
        const next = { ...countdownsRef.current };
        delete next[id];
        commitCountdowns(next);
      },
    };
  }, [commitCountdowns]);

  const value = useMemo<StoreValue>(
    () => ({ settings, update, countdowns, now, capture, setCapture, hunt, auto, rune, controls, flashAt, presence }),
    [settings, update, countdowns, now, capture, setCapture, hunt, auto, rune, controls, flashAt, presence],
  );

  return <StoreContext.Provider value={value}>{children}</StoreContext.Provider>;
}
