// 메인 스레드 타이머는 탭이 뒤로 가면 크게 늦춰지므로, 박자는 전용 워커에서 받는다.
const WORKER_SOURCE =
  "let id=null;onmessage=(e)=>{if(id!==null)clearInterval(id);id=e.data>0?setInterval(()=>postMessage(0),e.data):null;};";

export function startTicker(intervalMs: number, onTick: () => void): () => void {
  let worker: Worker | null = null;
  let workerUrl: string | null = null;
  let fallback: ReturnType<typeof setInterval> | null = null;
  try {
    workerUrl = URL.createObjectURL(new Blob([WORKER_SOURCE], { type: "text/javascript" }));
    worker = new Worker(workerUrl);
    worker.onmessage = () => onTick();
    worker.postMessage(intervalMs);
  } catch (error) {
    console.warn("워커 타이머를 쓸 수 없어 일반 타이머로 동작합니다", error);
    fallback = setInterval(onTick, intervalMs);
  }
  return () => {
    worker?.terminate();
    if (workerUrl) URL.revokeObjectURL(workerUrl);
    if (fallback !== null) clearInterval(fallback);
  };
}
