import { useState, type ReactNode } from "react";
import { ChevronDown, ChevronUp, CircleHelp } from "lucide-react";
import { PANEL_TITLES, type PanelId } from "../core/settings";
import { useStore } from "./store";

export interface PanelCommon {
  reorder: boolean;
  index: number;
  count: number;
  onMove: (delta: number) => void;
}

export function Panel({
  id,
  common,
  badge,
  help,
  actions,
  active = true,
  children,
}: {
  id: PanelId;
  common: PanelCommon;
  badge?: ReactNode;
  help?: ReactNode;
  actions?: ReactNode;
  active?: boolean;
  children: ReactNode;
}) {
  const { settings, update } = useStore();
  const [showHelp, setShowHelp] = useState(false);
  const collapsed = settings.collapsed[id] === true;
  const toggleCollapsed = () => update((s) => ({ ...s, collapsed: { ...s.collapsed, [id]: !collapsed } }));
  return (
    <section className={`panel ${active ? "" : "inactive"}`} aria-labelledby={`panel-${id}`}>
      <header className="panel-head">
        <h3 id={`panel-${id}`}>
          <i className="dot" />
          {PANEL_TITLES[id]}
        </h3>
        {badge}
        {help && (
          <button className="link" onClick={() => setShowHelp((v) => !v)} aria-expanded={showHelp}>
            <CircleHelp size={15} />
            사용 안내
          </button>
        )}
        <div className="spacer" />
        {!common.reorder && actions}
        {common.reorder ? (
          <>
            <button className="icon-btn" disabled={common.index === 0} onClick={() => common.onMove(-1)} aria-label="위로">
              <ChevronUp size={18} />
            </button>
            <button
              className="icon-btn"
              disabled={common.index === common.count - 1}
              onClick={() => common.onMove(1)}
              aria-label="아래로"
            >
              <ChevronDown size={18} />
            </button>
          </>
        ) : (
          <button className="icon-btn" onClick={toggleCollapsed} aria-label={collapsed ? "펼치기" : "접기"} aria-expanded={!collapsed}>
            {collapsed ? <ChevronDown size={18} /> : <ChevronUp size={18} />}
          </button>
        )}
      </header>
      {showHelp && help && <div className="panel-help">{help}</div>}
      {!collapsed && !common.reorder && <div className="panel-body">{children}</div>}
    </section>
  );
}
