function statusOf(state: CountdownState, enabled: boolean, now: number): { tone: Tone; label: string } {
  if (!enabled) return { tone: "muted", label: "꺼짐" };
  switch (state.status) {
    case "idle":
      return { tone: "muted", label: "대기" };
    case "running":
      return { tone: "ok", label: state.startAt !== undefined && state.startAt > now ? "재시작 대기" : "진행 중" };
    case "paused":
      return { tone: "warn", label: state.heldByBuff ? "버프 대기" : "일시정지" };
    case "done":
      return { tone: "muted", label: "완료" };
  }
}

/** 부스터 타이머 읽기 상태(원본의 타이머 대기·시간 확인 중·알림 대기·타이머 놓침·다음 부스터 대기) */
function boosterLabel(auto: AutoStatus | undefined, hasCapture: boolean, state: CountdownState): { text: string; tone?: "accent" | "danger" } {
  if (!hasCapture) return { text: "화면 공유 필요", tone: "danger" };
  if (auto?.status === "tracking") return { text: auto.value !== null ? `읽는 중 ${auto.value}초` : "알림 대기", tone: "accent" };
  if (auto?.status === "lost") return state.status === "running" ? { text: "타이머 놓침", tone: "accent" } : { text: "타이머 대기" };
  if (auto && auto.value !== null) return { text: "시간 확인 중", tone: "accent" };
  return { text: state.status === "done" ? "다음 부스터 대기" : "타이머 대기" };
}

function autoLabel(
  item: CountdownItem,
  auto: AutoStatus | undefined,
  hasCapture: boolean,
  hasBuffBar: boolean,
  running: boolean,
): { text: string; tone?: "accent" | "danger" } {
  if (item.quickslot) {
    if (!hasCapture) return { text: "화면 공유 필요", tone: "danger" };
    return auto?.status === "tracking" && auto.value !== null ? { text: `쿨타임 ${auto.value}초`, tone: "accent" } : { text: "퀵슬롯 대기" };
  }
  if (!item.autoIcon && !item.autoBright && !item.preset) return { text: "수동" };
  if (!hasCapture) return { text: "화면 공유 필요", tone: "danger" };
  if (!hasBuffBar) return { text: "버프칸 미선택", tone: "danger" };
  if (auto?.status === "bright") return { text: "아이콘 감지됨", tone: "accent" };
  if (!auto || auto.status === "idle") return { text: "찾는 중" };
  // 초 표시 뒤쪽에서 아이콘이 더 어두워져 못 찾아도 타이머는 읽은 시각대로 돈다
  if (auto.status === "lost") return running ? { text: "따라가는 중", tone: "accent" } : { text: "아이콘 안 보임" };
  return auto.value !== null ? { text: `읽는 중 ${auto.value}초`, tone: "accent" } : { text: "따라가는 중", tone: "accent" };
}

export function CountdownPanel({
  section,
  common,
  onPickBuffBar,
  onPickFavorites,
  onRegisterIcon,
  onPickQuickslot,
}: {
  section: CountdownSection;
  common: PanelCommon;
  onPickBuffBar: () => void;
  onPickFavorites: () => void;
  onRegisterIcon: (item: CountdownItem) => void;
  onPickQuickslot: (item: CountdownItem) => void;
}) {
  const { settings, update, countdowns, controls, presence } = useStore();
  const items = settings[section].items;
  const randomDelay = randomDelayOf(settings, section);
  const autoCapable = AUTO_SECTIONS.includes(section);
  const setItems = (fn: (list: CountdownItem[]) => CountdownItem[]) =>
    update((s) => withItems(s, section, fn(s[section].items)));
  const changeItem = (next: CountdownItem) => setItems((list) => list.map((it) => (it.id === next.id ? next : it)));
  const removeItem = (id: string) => {
    setItems((list) => list.filter((it) => it.id !== id));
    controls.reset(id);
  };
  const anyRunning = items.some((it) => countdowns[it.id]?.status === "running");
  const linkedTimers = settings.general.items.filter((it) => it.requireTrackedBuff).length;
  // 버프 종료 알림의 버프를 조건으로 쓰는 곳들
  const linkUsers = [...(settings.huntStall.requireTrackedBuff ? ["사냥 멈춤"] : []), ...(linkedTimers > 0 ? [`일반 타이머 ${linkedTimers}개`] : [])];

  const actions = (
    <>
      {randomDelay && (section === "skill" || section === "general") && (
        <span className="with-icon">
          <Shuffle size={15} aria-hidden />
          <Toggle
            checked={randomDelay.enabled}
            onChange={(enabled) => update((s) => withRandomDelay(s, section, { ...randomDelay, enabled }))}
            label="랜덤 지연"
          />
        </span>
      )}
      {section === "general" && (
        <LinkMenu summary={`버프 연계 · ${linkedTimers > 0 ? `${linkedTimers}개` : "꺼짐"}`} active={linkedTimers > 0} label="일반 타이머 버프 연계 설정">
          <b>버프가 있을 때만 진행</b>
          <p className="muted">
            버프 종료 알림의 버프 중 하나라도 감지될 때만 진행해요. 버프가 사라지면 멈췄다가 다시 잡히면 이어서 돌고, 버프가 없을 때 ▶ 를
            누르면 버프가 잡히는 순간 시작해요.
          </p>
          {items.length === 0 ? (
            <p className="muted">타이머를 추가한 뒤 연계할 수 있어요.</p>
          ) : (
            items.map((it, index) => (
              <Toggle
                key={it.id}
                checked={it.requireTrackedBuff}
                onChange={(requireTrackedBuff) => changeItem({ ...it, requireTrackedBuff })}
                label={`${index + 1}. ${it.label}`}
              />
            ))
          )}
          <span className="link-source">
            버프 종료 알림 <PresenceChip presence={presence} />
          </span>
        </LinkMenu>
      )}
      {section === "general" && (
        <>
          <button
            className="icon-btn"
            aria-label="켜진 타이머 모두 시작"
            onClick={() =>
              items
                .filter((it) => it.enabled)
                .forEach((it) => {
                  const state = countdowns[it.id];
                  if (state?.status === "paused") controls.resume(section, it);
                  else if (state?.status !== "running") controls.start(section, it);
                })
            }
          >
            <Play size={16} />
          </button>
          <button className="icon-btn" aria-label="모두 일시정지" disabled={!anyRunning} onClick={() => items.forEach((it) => controls.pause(it.id))}>
            <Pause size={16} />
          </button>
          <button className="icon-btn" aria-label="모두 초기화" onClick={() => items.forEach((it) => controls.reset(it.id))}>
            <RotateCcw size={16} />
          </button>
        </>
      )}
      <PopMenu
        className="add-menu"
        label="항목 추가"
        summary={
          <>
            <Plus size={15} />
            추가
          </>
        }
      >
        {PRESETS[section].map((preset) => (
          <button
            key={preset.label}
            type="button"
            className="add-item"
            onClick={(e) => {
              setItems((list) => [...list, makeCountdown(preset)]);
              const menu = e.currentTarget.closest("details");
              if (menu) menu.open = false;
            }}
          >
            <ItemIcon icon={preset.icon} size={24} />
            <span className="add-label">{preset.label}</span>
            {!/\)$/.test(preset.label) && <span className="muted">{fmtDuration(preset.durationSec)}</span>}
          </button>
        ))}
      </PopMenu>
    </>
  );

  return (
    <Panel id={section} common={common} help={HELP[section]} actions={actions} active={items.some((it) => it.enabled)}>
      {section === "booster" && items.some((it) => it.screenTimer) && (
        <div className="note">
          부스터 타이머 읽기: 화면 맨 위 가운데 &apos;남은시간&apos; 타이머를 자동으로 읽어요. 영역은 고르지 않아도 돼요(게임 창만 공유).
        </div>
      )}
      {autoCapable && !(section === "booster" && items.length > 0 && items.every((it) => it.screenTimer)) && (
        <div className="note auto-note">
          <span>{AUTO_GUIDE}</span>
          <BuffBarControl onPick={onPickBuffBar} onPickFavorites={onPickFavorites} />
        </div>
      )}
      {section === "buffExpiry" && linkUsers.length > 0 && (
        <div className="note link-note">
          <Link2 size={14} className="inline-icon" /> 버프 연계 중: {linkUsers.join(" · ")} — 켜진 항목 중 하나라도 감지되거나 타이머가 돌면 진행해요. 지금 <PresenceChip presence={presence} />
        </div>
      )}
      {items.length === 0 && <div className="row muted">오른쪽 위 [추가]로 항목을 넣어주세요.</div>}
      {items.map((item) => (
        <CountdownRow
          key={item.id}
          section={section}
          item={item}
          state={countdowns[item.id] ?? idleState()}
          autoCapable={autoCapable}
          onChange={changeItem}
          onRemove={() => removeItem(item.id)}
          onRegisterIcon={() => onRegisterIcon(item)}
          onPickQuickslot={() => onPickQuickslot(item)}
        />
      ))}
    </Panel>
  );
}

function CountdownRow({
  section,
  item,
  state,
  autoCapable,
  onChange,
  onRemove,
  onRegisterIcon,
  onPickQuickslot,
}: {
  section: CountdownSection;
  item: CountdownItem;
  state: CountdownState;
  autoCapable: boolean;
  onChange: (item: CountdownItem) => void;
  onRemove: () => void;
  onRegisterIcon: () => void;
  onPickQuickslot: () => void;
}) {
  const { now, controls, auto, capture, settings, presence } = useStore();
  const [editing, setEditing] = useState(false);
  const next = nextFireAt(state);
  const untilNext = next === null ? null : next - now;
  const status = statusOf(state, item.enabled, now);
  // 자동 재시작 대기 중이면 새 주기가 시작될 때까지 남은 시간
  const restartWait = state.status === "running" && state.startAt !== undefined && state.startAt > now ? state.startAt - now : null;
  const detect = item.screenTimer
    ? boosterLabel(auto[item.id], capture !== null, state)
    : autoLabel(item, auto[item.id], capture !== null, locationRegion(settings, item.location) !== null, state.status === "running");
  return (
    <div className={`row ${item.enabled ? "" : "off"}`} data-testid={`row-${item.id}`}>
      <div className={`row-main ${autoCapable ? "with-auto" : ""}`}>
        <Toggle checked={item.enabled} onChange={(enabled) => onChange({ ...item, enabled })} label={item.enabled ? "켜짐" : "꺼짐"} />
        <button className="item-name" onClick={() => setEditing((v) => !v)} aria-expanded={editing} title="설정 열기">
          <ItemIcon icon={item.icon} size={28} />
          <span className="label">{item.label}</span>
          {section === "general" && item.requireTrackedBuff && (
            <span
              className={`link-chip ${presence === "present" ? "ok" : "blocked"}`}
              title={`버프 연계 · ${PRESENCE_LABELS[presence]}`}
              aria-label={`버프 연계 · ${PRESENCE_LABELS[presence]}`}
            >
              <Link2 size={12} />
            </span>
          )}
          <span className="chev">{editing ? <ChevronUp size={14} /> : <ChevronDown size={14} />}</span>
        </button>
        {autoCapable && <Stat label="감지" value={<span data-testid="auto">{detect.text}</span>} tone={detect.tone} />}
        <Stat label={section === "specialCore" ? "쿨타임" : "지속시간"} value={fmtDuration(item.durationSec)} />
        <Stat label="알림 시점" value={fmtLead(item.leadSec)} />
        <Stat
          label="알림까지"
          value={<span data-testid="until">{untilNext === null ? "--" : fmtClock(untilNext)}</span>}
          tone={untilNext !== null && untilNext <= 10_000 ? "danger" : "accent"}
        />
        <Stat
          label={restartWait !== null ? "재시작까지" : "남은 시간"}
          value={<span data-testid="remaining">{fmtClock(restartWait ?? remainingMs(state, now))}</span>}
        />
        <Stat label="반복" value={repeatSummary(item.repeat)} />
        <StatusDot tone={status.tone}>
          <span data-testid="status">{status.label}</span>
        </StatusDot>
        <div className="row-actions">
          {state.status === "running" ? (
            <button className="icon-btn" onClick={() => controls.pause(item.id)} aria-label="일시정지" title="일시정지">
              <Pause size={16} />
            </button>
          ) : state.status === "paused" ? (
            <button className="icon-btn primary" onClick={() => controls.resume(section, item)} aria-label="이어서" title="재개">
              <Play size={16} />
            </button>
          ) : (
            <button className="icon-btn primary" onClick={() => controls.start(section, item)} aria-label="시작" title="시작">
              <Play size={16} />
            </button>
          )}
          <button className="icon-btn" onClick={() => controls.start(section, item)} aria-label="지금부터 다시 시작" title="지금부터 다시 시작">
            <RefreshCw size={15} />
          </button>
          <button className="icon-btn" disabled={state.status === "idle"} onClick={() => controls.reset(item.id)} aria-label="초기화" title="초기화">
            <RotateCcw size={15} />
          </button>
          <button className="icon-btn danger" onClick={onRemove} aria-label="삭제" title="삭제">
            <Trash2 size={16} />
          </button>
        </div>
      </div>
      {editing && (
        <CountdownEditor
          section={section}
          item={item}
          autoCapable={autoCapable}
          onChange={onChange}
          onRegisterIcon={onRegisterIcon}
          onPickQuickslot={onPickQuickslot}
        />
      )}
    </div>
  );
}

function CountdownEditor({
  section,
  item,
  autoCapable,
  onChange,
  onRegisterIcon,
  onPickQuickslot,
}: {
  section: CountdownSection;
  item: CountdownItem;
  autoCapable: boolean;
  onChange: (item: CountdownItem) => void;
  onRegisterIcon: () => void;
  onPickQuickslot: () => void;
}) {
  const { capture, settings } = useStore();
  const canRegister = capture !== null && locationRegion(settings, item.location) !== null;
  const registered = item.autoBright ?? item.autoIcon;
  return (
    <div className="editor">
      {section === "booster" && (
        <label>
          타이머 읽기
          <Toggle
            checked={item.screenTimer}
            onChange={(screenTimer) => onChange({ ...item, screenTimer })}
            label={item.screenTimer ? "화면 맨 위 가운데 타이머 자동 읽기" : "사용 안 함(아이콘 감지·수동)"}
          />
        </label>
      )}
      {autoCapable && !item.screenTimer && (
        <div className="editor-auto">
          <b>자동 감지</b>
          {registered ? (
            <>
              <TemplatePreview template={registered} />
              <span className="muted">
                {item.autoBright ? "아이콘 감지 중 (뜨는 순간 + 1분 미만 초)" : "아이콘 감지 중 (1분 미만 초)"}
              </span>
              <button className="btn small" disabled={!canRegister} onClick={onRegisterIcon}>
                다시 고르기
              </button>
              <button className="btn small danger" onClick={() => onChange({ ...item, autoIcon: null, autoBright: null, preset: null })}>
                감지 끄기
              </button>
            </>
          ) : item.preset ? (
            <>
              <span className="muted">내장 아이콘으로 자동 감지 중 — 아이콘·영역 고르지 않아도 돼요</span>
              <button className="btn small" disabled={!canRegister} onClick={onRegisterIcon}>
                직접 고르기
              </button>
              <button className="btn small danger" onClick={() => onChange({ ...item, preset: null })}>
                감지 끄기
              </button>
            </>
          ) : (
            <>
              <span className="muted">버프 아이콘을 고르면 화면에서 감지해 남은 시간을 자동으로 맞춰요</span>
              <button className="btn small primary" disabled={!canRegister} onClick={onRegisterIcon}>
                버프 아이콘 감지
              </button>
              {!canRegister && <span className="muted">(화면 공유 후)</span>}
            </>
          )}
        </div>
      )}
      {autoCapable && !item.screenTimer && (
        <label>
          감지 위치
          <select
            className="add-select"
            value={item.location}
            onChange={(e) =>
              onChange({ ...item, location: e.target.value === "favorites" ? "favorites" : "buffBar", autoIcon: null, autoBright: null })
            }
          >
            <option value="buffBar">기본 버프칸</option>
            <option value="favorites">버프 즐겨찾기</option>
          </select>
        </label>
      )}
      {section === "skill" && (
        <div className="editor-auto">
          <b>퀵슬롯 방식</b>
          {item.quickslot ? (
            <>
              <RegionPreview region={item.quickslot} />
              <span className="muted">
                쿨타임 숫자가 뜨면 쓴 시각을 계산해 맞춰요{item.cooldownSec ? ` (쿨타임 ${item.cooldownSec}초)` : " — 아래 쿨타임을 넣으면 더 정확해요"}
              </span>
              <button className="btn small" disabled={!capture} onClick={onPickQuickslot}>
                다시 선택
              </button>
              <button className="btn small danger" onClick={() => onChange({ ...item, quickslot: null })}>
                퀵슬롯 방식 끄기
              </button>
            </>
          ) : (
            <>
              <span className="muted">버프칸에 안 뜨는 직업 설치기는 퀵슬롯 아이콘의 쿨타임 숫자로 알려줘요</span>
              <button className="btn small" disabled={!capture} onClick={onPickQuickslot}>
                퀵슬롯 아이콘 영역 선택
              </button>
              {!capture && <span className="muted">(화면 공유 후)</span>}
            </>
          )}
        </div>
      )}
      <label>
        이름
        <input className="text" value={item.label} onChange={(e) => onChange({ ...item, label: e.target.value })} />
      </label>
      <label>
        아이콘
        <ItemIcon icon={item.icon} size={24} />
        {!isImageIcon(item.icon) && (
          <input className="text" value={item.icon} style={{ width: 56 }} onChange={(e) => onChange({ ...item, icon: e.target.value })} />
        )}
      </label>
      <label>
        {section === "specialCore" ? "쿨타임" : "지속시간"}
        <DurationInput value={item.durationSec} onChange={(durationSec) => onChange({ ...item, durationSec })} />
      </label>
      {section === "general" && (
        <label>
          자동 재시작
          <Toggle checked={item.autoRestart} onChange={(autoRestart) => onChange({ ...item, autoRestart })} label={item.autoRestart ? "끝나면 다시 시작" : "사용 안 함"} />
          {item.autoRestart && (
            <NumberInput
              value={item.autoRestartDelaySec}
              min={0}
              max={3600}
              width={56}
              label="재시작 대기 초"
              suffix="초 뒤 재시작 (재시작 대기)"
              onChange={(autoRestartDelaySec) => onChange({ ...item, autoRestartDelaySec })}
            />
          )}
        </label>
      )}
      {section === "skill" && (
        <label>
          쿨타임
          <DurationInput
            value={item.cooldownSec ?? 0}
            onChange={(cooldownSec) => onChange({ ...item, cooldownSec: cooldownSec > 0 ? cooldownSec : null })}
          />
        </label>
      )}
      <label>
        알림 시점
        <NumberInput value={item.leadSec} min={-3600} max={86_400} suffix="초 전 (음수면 종료 후)" onChange={(leadSec) => onChange({ ...item, leadSec })} />
      </label>
      <label>
        반복
        <RepeatEditor value={item.repeat} onChange={(repeat) => onChange({ ...item, repeat })} />
      </label>
      <label>
        알림음
        <select value={item.sound} onChange={(e) => onChange({ ...item, sound: e.target.value as SoundId })}>
          {SOUND_IDS.filter((id) => id !== "test" && id !== "specialCore").map((id) => (
            <option key={id} value={id}>
              {SOUND_LABELS[id]}
            </option>
          ))}
        </select>
        <button className="btn small" type="button" onClick={() => void sound.play(item.sound, { force: true, volume: item.volume })}>
          <Play size={14} />
          미리듣기
        </button>
      </label>
      <label>
        볼륨
        <VolumeInput value={item.volume} label={`${item.label} 볼륨`} onChange={(volume) => onChange({ ...item, volume })} />
      </label>
    </div>
  );
}
