import { useCallback, useEffect, useRef, useState, type CSSProperties, type ReactNode } from "react";
import { Crosshair, Link2, X } from "lucide-react";
import { isImageIcon } from "../core/icons";
import { PRESENCE_LABELS, type BuffPresence } from "../core/presence";
import type { FlashColor, FlashStrength, Region, RepeatConfig } from "../core/settings";
import { ICON_GRID, type IconTemplate } from "../detect/buffbar";
import { useStore } from "./store";

export type Tone = "ok" | "danger" | "muted" | "warn";

export function Toggle({
  checked,
  onChange,
  label,
  disabled,
}: {
  checked: boolean;
  onChange: (value: boolean) => void;
  label?: string;
  disabled?: boolean;
}) {
  return (
    <label className={`toggle ${checked ? "on" : ""} ${disabled ? "disabled" : ""}`}>
      <input type="checkbox" checked={checked} disabled={disabled} onChange={(e) => onChange(e.target.checked)} />
      <span className="track">
        <span className="thumb" />
      </span>
      {label !== undefined && <span className="toggle-label">{label}</span>}
    </label>
  );
}

export function Modal({
  title,
  onClose,
  children,
  footer,
  wide,
  closable = true,
}: {
  title: string;
  onClose: () => void;
  children: ReactNode;
  footer?: ReactNode;
  wide?: boolean;
  closable?: boolean;
}) {
  useEffect(() => {
    if (!closable) return;
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") onClose();
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [onClose, closable]);
  return (
    <div
      className="modal-backdrop"
      onMouseDown={(e) => {
        if (closable && e.target === e.currentTarget) onClose();
      }}
    >
      <div className={`modal ${wide ? "wide" : ""}`} role="dialog" aria-modal="true" aria-label={title}>
        <div className="modal-head">
          <h2>{title}</h2>
          {closable && (
            <button className="icon-btn" onClick={onClose} aria-label="닫기">
              <X size={18} />
            </button>
          )}
        </div>
        <div className="modal-body">{children}</div>
        {footer && <div className="modal-foot">{footer}</div>}
      </div>
    </div>
  );
}

/** 입력 중간 상태('-', 빈칸)를 허용하는 숫자 입력 */
export function NumberInput({
  value,
  onChange,
  min,
  max,
  suffix,
  width = 64,
  label,
}: {
  value: number;
  onChange: (value: number) => void;
  min?: number;
  max?: number;
  suffix?: string;
  width?: number;
  label?: string;
}) {
  const [text, setText] = useState(String(value));
  useEffect(() => {
    setText((current) => (Number(current) === value && current.trim() !== "" ? current : String(value)));
  }, [value]);
  const commit = (raw: string) => {
    const parsed = Number(raw);
    if (raw.trim() === "" || !Number.isFinite(parsed)) return;
    onChange(Math.min(max ?? Number.POSITIVE_INFINITY, Math.max(min ?? Number.NEGATIVE_INFINITY, parsed)));
  };
  return (
    <span className="num">
      <input
        type="text"
        inputMode="numeric"
        aria-label={label ?? suffix}
        value={text}
        style={{ width }}
        onChange={(e) => {
          setText(e.target.value);
          commit(e.target.value);
        }}
        onBlur={() => setText(String(value))}
      />
      {suffix && <span className="suffix">{suffix}</span>}
    </span>
  );
}

export function DurationInput({ value, onChange }: { value: number; onChange: (seconds: number) => void }) {
  const minutes = Math.floor(value / 60);
  const seconds = value % 60;
  return (
    <span className="num">
      <NumberInput value={minutes} min={0} max={1440} suffix="분" width={56} onChange={(m) => onChange(Math.max(1, m * 60 + seconds))} />
      <NumberInput value={seconds} min={0} max={59} suffix="초" width={48} onChange={(s) => onChange(Math.max(1, minutes * 60 + s))} />
    </span>
  );
}

export function Stat({ label, value, tone }: { label: string; value: ReactNode; tone?: "accent" | "danger" }) {
  return (
    <div className={`stat ${tone ?? ""}`}>
      <span className="stat-label">{label}</span>
      <span className="stat-value">{value}</span>
    </div>
  );
}

export function StatusDot({ tone, children }: { tone: Tone; children: ReactNode }) {
  return (
    <span className={`status ${tone}`}>
      <i />
      {children}
    </span>
  );
}

export function repeatSummary(repeat: RepeatConfig): string {
  return repeat.enabled ? `${repeat.intervalSec}초마다 ${repeat.count}회` : "사용 안 함";
}

export function RepeatEditor({ value, onChange }: { value: RepeatConfig; onChange: (value: RepeatConfig) => void }) {
  return (
    <span className="repeat-editor">
      <Toggle checked={value.enabled} onChange={(enabled) => onChange({ ...value, enabled })} label={value.enabled ? "반복" : "사용 안 함"} />
      {value.enabled && (
        <>
          <NumberInput value={value.intervalSec} min={1} max={600} suffix="초마다" width={52} onChange={(intervalSec) => onChange({ ...value, intervalSec })} />
          <NumberInput value={value.count} min={1} max={20} suffix="회" width={44} onChange={(count) => onChange({ ...value, count })} />
        </>
      )}
    </span>
  );
}

/** 선택한 영역이 실제로 어떻게 보이는지 1초마다 보여준다. marker 가 있으면 그 자리를 빨간 상자로 표시 */
export function RegionPreview({
  region,
  marker = null,
}: {
  region: Region | null;
  marker?: { x: number; y: number; size: number } | null;
}) {
  const { capture } = useStore();
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const markerRef = useRef(marker);
  markerRef.current = marker;
  useEffect(() => {
    if (!capture || !region) return;
    const draw = () => {
      const image = capture.grab(region);
      const canvas = canvasRef.current;
      if (!image || !canvas) return;
      canvas.width = image.width;
      canvas.height = image.height;
      const ctx = canvas.getContext("2d");
      if (!ctx) return;
      ctx.putImageData(image, 0, 0);
      const m = markerRef.current;
      if (m) {
        const side = m.size + 6;
        ctx.strokeStyle = "#ff2d55";
        ctx.lineWidth = Math.max(2, Math.round(image.width / 100));
        ctx.strokeRect(m.x - side / 2, m.y - side / 2, side, side);
      }
    };
    draw();
    const id = setInterval(draw, 1000);
    return () => clearInterval(id);
  }, [capture, region]);
  if (!region) return <span className="muted">영역 미선택</span>;
  if (!capture) return <span className="muted">영역 저장됨 · 화면 공유하면 미리보기</span>;
  return <canvas ref={canvasRef} className="region-preview" aria-label="선택 영역 미리보기" />;
}

/** 등록한 아이콘(16×16 평균색)을 작게 보여준다 */
export function TemplatePreview({ template }: { template: IconTemplate }) {
  const draw = useCallback(
    (canvas: HTMLCanvasElement | null) => {
      if (!canvas) return;
      canvas.width = ICON_GRID;
      canvas.height = ICON_GRID;
      const ctx = canvas.getContext("2d");
      if (!ctx) return;
      const image = ctx.createImageData(ICON_GRID, ICON_GRID);
      for (let i = 0; i < ICON_GRID * ICON_GRID; i++) {
        image.data[i * 4] = template.cells[i * 3] ?? 0;
        image.data[i * 4 + 1] = template.cells[i * 3 + 1] ?? 0;
        image.data[i * 4 + 2] = template.cells[i * 3 + 2] ?? 0;
        image.data[i * 4 + 3] = 255;
      }
      ctx.putImageData(image, 0, 0);
    },
    [template],
  );
  return <canvas ref={draw} className="tpl-preview" aria-label="등록한 아이콘" />;
}

/** 버프칸·버프 즐겨찾기 영역(자동 감지용) 선택 줄 */
export function BuffBarControl({ onPick, onPickFavorites }: { onPick: () => void; onPickFavorites: () => void }) {
  const { settings, capture, update } = useStore();
  const region = settings.buffBar.region;
  const favorites = settings.buffFavorites.region;
  return (
    <>
      <div className="auto-bar">
        <b>버프칸</b>
        {region ? <RegionPreview region={region} /> : <span className="muted">자동 — 화면 오른쪽 위에서 알아서 찾아요</span>}
        <button className="btn small" disabled={!capture} onClick={onPick}>
          <Crosshair size={14} />
          {region ? "버프칸 다시 선택" : "직접 고르기"}
        </button>
        {region && (
          <button className="btn small" onClick={() => update((s) => ({ ...s, buffBar: { region: null } }))}>
            자동으로
          </button>
        )}
      </div>
      <div className="auto-bar">
        <b>즐겨찾기</b>
        <RegionPreview region={favorites} />
        <button className="btn small" disabled={!capture} onClick={onPickFavorites}>
          <Crosshair size={14} />
          {favorites ? "즐겨찾기 다시 선택" : "버프 즐겨찾기 영역 선택"}
        </button>
        <span className="muted">항목의 감지 위치를 ‘버프 즐겨찾기’로 바꾼 항목만 써요</span>
      </div>
    </>
  );
}

// 그림 주소는 본 창 기준으로 만든다 — PIP 창(about:blank)에서도 같은 그림을 불러오게
const ASSET_BASE = typeof document === "undefined" ? "http://localhost/" : document.baseURI;

/** 항목 아이콘: 원본과 같은 스킬·버프 그림, 아니면 이모지·'직접' 글자 */
export function ItemIcon({ icon, size = 24 }: { icon: string; size?: number }) {
  if (isImageIcon(icon)) {
    return <img className="item-icon" src={new URL(icon, ASSET_BASE).href} width={size} height={size} alt="" aria-hidden />;
  }
  const word = /[가-힣]/.test(icon);
  return (
    <span className={`item-icon ${word ? "word" : "emoji"}`} style={{ width: size, height: size, fontSize: word ? 11 : size * 0.78 }} aria-hidden>
      {icon}
    </span>
  );
}

/** 알림 하나의 볼륨(0~100%). 마스터 볼륨과 곱해진다 */
export function VolumeInput({ value, onChange, label }: { value: number; onChange: (value: number) => void; label: string }) {
  const percent = Math.round(value * 100);
  return (
    <span className="volume-input">
      <input type="range" min={0} max={100} step={5} value={percent} aria-label={label} onChange={(e) => onChange(Number(e.target.value) / 100)} />
      <span className="suffix">{percent}%</span>
    </span>
  );
}

/** 패널 머리의 작은 펼침 메뉴(버프 연계·항목 추가). 바깥을 누르면 닫힌다 */
export function PopMenu({
  summary,
  label,
  active = false,
  className = "",
  children,
}: {
  summary: ReactNode;
  label: string;
  active?: boolean;
  className?: string;
  children: ReactNode;
}) {
  const ref = useRef<HTMLDetailsElement>(null);
  useEffect(() => {
    const onDown = (e: MouseEvent) => {
      const el = ref.current;
      if (el?.open && e.target instanceof Node && !el.contains(e.target)) el.open = false;
    };
    document.addEventListener("mousedown", onDown);
    return () => document.removeEventListener("mousedown", onDown);
  }, []);
  return (
    <details ref={ref} className={`link-menu ${active ? "on" : ""} ${className}`}>
      <summary aria-label={label}>{summary}</summary>
      <div className="link-menu-body" role="group" aria-label={label}>
        {children}
      </div>
    </details>
  );
}

/** 버프 연계 설정 메뉴 */
export function LinkMenu({ summary, active, label, children }: { summary: string; active: boolean; label: string; children: ReactNode }) {
  return (
    <PopMenu
      label={label}
      active={active}
      summary={
        <>
          <Link2 size={14} />
          {summary}
        </>
      }
    >
      {children}
    </PopMenu>
  );
}

export function PresenceChip({ presence }: { presence: BuffPresence }) {
  return (
    <span className={`link-chip ${presence === "present" ? "ok" : "blocked"}`} data-testid="presence">
      {PRESENCE_LABELS[presence]}
    </span>
  );
}

/** 버프 연계를 켠 곳에 띄우는 줄: 어떤 버프를 보는지와 지금 상태 */
export function BuffLinkBar() {
  const { settings, presence } = useStore();
  const labels = settings.buffExpiry.items.filter((it) => it.enabled).map((it) => it.label);
  return (
    <div className="link-bar" role="group" aria-label="버프 연계 조건">
      <b className="with-icon">
        <Link2 size={14} />
        버프 연계
      </b>
      <span className="link-targets">{labels.join(" · ") || "켜진 버프 없음"}</span>
      <PresenceChip presence={presence} />
    </div>
  );
}

const FLASH_COLORS: Record<FlashColor, string> = { yellow: "#ffd400", red: "#ff3b30", cyan: "#00c8d7", purple: "#a855f7", white: "#ffffff" };
const FLASH_ALPHA: Record<FlashStrength, string> = { soft: "14%", normal: "28%", strong: "48%" };
const FLASH_MS = 2000;

/** 알림이 울리면 2초 동안 화면 테두리·바탕을 고른 색·세기로 반짝인다(본 화면·PIP 둘 다) */
export function AlertFlash() {
  const { settings, flashAt, now } = useStore();
  const fx = settings.alertEffect;
  if (!fx.enabled || flashAt === null || now - flashAt > FLASH_MS) return null;
  const style = { "--flash": FLASH_COLORS[fx.color], "--flash-alpha": FLASH_ALPHA[fx.strength] } as CSSProperties;
  return <div key={flashAt} className={`alert-flash ${fx.blink ? "blink" : ""}`} style={style} data-testid="alert-flash" aria-hidden />;
}
