import { DIGIT_TEMPLATES } from "./digit-templates";
import { readNumbers, type ReadNumber, type Rgba } from "./digits";

/**
 * 버프칸에서 "숫자가 떠 있는 아이콘"을 찾고, 사용자가 등록한 아이콘과 비교한다.
 * 아이콘 가운데는 숫자가 덮으므로 가장자리 고리 부분 색만 비교한다.
 */
export const ICON_GRID = 16;
/** 숫자 높이 대비 아이콘 한 변 (녹화 영상 측정: 아이콘 45px / 숫자 14px) */
export const ICON_PER_DIGIT_H = 3.2;
/** 평균색 차이를 거리에 얼마나 섞을지 (녹화 영상으로 맞춘 값) */
export const MATCH = { colorWeight: 0.3 };

export interface IconTemplate {
  /** ICON_GRID×ICON_GRID 칸의 평균 RGB (r,g,b 순) */
  cells: number[];
  /** 등록 때 아이콘 한 변(px). 숫자 높이는 프레임마다 1~2px 흔들리므로 자를 크기는 고정한다 */
  size: number;
  /** '분:초' 표시 화면에서 배운 모양 — 글자가 가로로 길게 덮으므로 가운데 줄 전체를 빼고 비교한다 */
  textBand?: boolean;
}

export interface Box {
  x: number;
  y: number;
  w: number;
  h: number;
}

export interface Sighting {
  number: ReadNumber;
  box: Box;
  signature: Float32Array;
}

/** 숫자(테두리 포함)가 덮는 가운데 칸 — 두·세 자리 숫자도 가리도록 넉넉하게 */
function isCenterCell(gx: number, gy: number): boolean {
  return gx >= 3 && gx <= 12 && gy >= 4 && gy <= 11;
}

/** '분:초'(1:59)는 아이콘 가로를 거의 다 덮는다 — 숫자 높이만큼의 가운데 줄 전체를 뺀다 */
function isTextBandCell(_gx: number, gy: number): boolean {
  return gy >= 4 && gy <= 11;
}

export function iconBox(number: ReadNumber, width: number, height: number, size?: number): Box {
  const side = Math.max(8, Math.round(size ?? number.h * ICON_PER_DIGIT_H));
  const x = Math.round(number.cx - side / 2);
  const y = Math.round(number.cy - side / 2);
  const cx = Math.max(0, Math.min(width - side, x));
  const cy = Math.max(0, Math.min(height - side, y));
  return { x: cx, y: cy, w: Math.min(side, width), h: Math.min(side, height) };
}

export function iconSignature(img: Rgba, box: Box): Float32Array {
  const cells = new Float32Array(ICON_GRID * ICON_GRID * 3);
  for (let gy = 0; gy < ICON_GRID; gy++) {
    const y0 = box.y + Math.floor((gy * box.h) / ICON_GRID);
    const y1 = Math.max(y0 + 1, box.y + Math.floor(((gy + 1) * box.h) / ICON_GRID));
    for (let gx = 0; gx < ICON_GRID; gx++) {
      const x0 = box.x + Math.floor((gx * box.w) / ICON_GRID);
      const x1 = Math.max(x0 + 1, box.x + Math.floor(((gx + 1) * box.w) / ICON_GRID));
      let r = 0;
      let g = 0;
      let b = 0;
      let n = 0;
      for (let y = y0; y < y1 && y < img.height; y++) {
        for (let x = x0; x < x1 && x < img.width; x++) {
          const i = (y * img.width + x) * 4;
          r += img.data[i] as number;
          g += img.data[i + 1] as number;
          b += img.data[i + 2] as number;
          n++;
        }
      }
      const c = (gy * ICON_GRID + gx) * 3;
      cells[c] = n ? r / n : 0;
      cells[c + 1] = n ? g / n : 0;
      cells[c + 2] = n ? b / n : 0;
    }
  }
  return cells;
}

function ringMean(cells: ArrayLike<number>, skip: CellFilter): [number, number, number] {
  const sum: [number, number, number] = [0, 0, 0];
  let n = 0;
  for (let gy = 0; gy < ICON_GRID; gy++) {
    for (let gx = 0; gx < ICON_GRID; gx++) {
      if (skip(gx, gy)) continue;
      const c = (gy * ICON_GRID + gx) * 3;
      sum[0] += cells[c] as number;
      sum[1] += cells[c + 1] as number;
      sum[2] += cells[c + 2] as number;
      n++;
    }
  }
  return [sum[0] / n, sum[1] / n, sum[2] / n];
}

/**
 * 가운데(숫자) 칸을 뺀 거리 (낮을수록 같은 아이콘).
 * 무늬 차이(각자 평균색을 뺀 것) + 평균색 차이의 일부 — 밝기가 조금 바뀌어도
 * 무늬로 같은 아이콘을 잡고, 무늬가 비슷해도 색이 다른 아이콘(금색 vs 회색)은 가른다.
 */
export function iconDistance(a: ArrayLike<number>, b: ArrayLike<number>, wide = false): number {
  return maskedDistance(a, b, wide ? isTextBandCell : isCenterCell);
}

type CellFilter = (gx: number, gy: number) => boolean;

function maskedDistance(a: ArrayLike<number>, b: ArrayLike<number>, skip: CellFilter): number {
  const ma = ringMean(a, skip);
  const mb = ringMean(b, skip);
  let sum = 0;
  let n = 0;
  for (let gy = 0; gy < ICON_GRID; gy++) {
    for (let gx = 0; gx < ICON_GRID; gx++) {
      if (skip(gx, gy)) continue;
      const c = (gy * ICON_GRID + gx) * 3;
      for (let ch = 0; ch < 3; ch++) {
        const da = (a[c + ch] as number) - (ma[ch] as number);
        const db = (b[c + ch] as number) - (mb[ch] as number);
        sum += Math.abs(da - db);
      }
      n += 3;
    }
  }
  if (!n) return Number.POSITIVE_INFINITY;
  const colorDiff = (Math.abs(ma[0] - mb[0]) + Math.abs(ma[1] - mb[1]) + Math.abs(ma[2] - mb[2])) / 3;
  return sum / n + MATCH.colorWeight * colorDiff;
}

/** 버프칸 한 장에서 숫자가 떠 있는 아이콘 전부 */
export function scanBuffBar(img: Rgba): Sighting[] {
  return readNumbers(img, DIGIT_TEMPLATES).map((number) => {
    const box = iconBox(number, img.width, img.height);
    return { number, box, signature: iconSignature(img, box) };
  });
}

export function toTemplate(sighting: Sighting): IconTemplate {
  return {
    cells: Array.from(sighting.signature, (v) => Math.round(v)),
    size: sighting.box.w,
    ...(sighting.number.colon ? { textBand: true } : {}),
  };
}

/**
 * 숫자 너비(예: 좁은 1)에 따라 숫자 중심이 몇 픽셀 흔들리므로,
 * 추정 상자 주변 ±radius 픽셀을 훑어 가장 가까운 자리의 거리를 쓴다.
 */
export function alignedDistance(img: Rgba, box: Box, template: IconTemplate, radius = 4, wide = false): { distance: number; box: Box } {
  let best = { distance: Number.POSITIVE_INFINITY, box };
  for (let dy = -radius; dy <= radius; dy++) {
    for (let dx = -radius; dx <= radius; dx++) {
      const x = box.x + dx;
      const y = box.y + dy;
      if (x < 0 || y < 0 || x + box.w > img.width || y + box.h > img.height) continue;
      const shifted = { ...box, x, y };
      const distance = iconDistance(iconSignature(img, shifted), template.cells, wide);
      if (distance < best.distance) best = { distance, box: shifted };
    }
  }
  return best;
}

/** 등록 아이콘과 가장 닮은 것. maxDistance 보다 멀면 없음 */
export function findIcon(
  img: Rgba,
  sightings: readonly Sighting[],
  template: IconTemplate,
  maxDistance = 30,
): (Sighting & { distance: number }) | null {
  let best: (Sighting & { distance: number }) | null = null;
  for (const sighting of sightings) {
    const wide = sighting.number.colon === true || template.textBand === true;
    // 대충 비교해 확실히 다른 아이콘은 건너뛴다 (정렬 탐색은 비싸다)
    if (iconDistance(sighting.signature, template.cells, wide) > maxDistance * 2.2) continue;
    const box = iconBox(sighting.number, img.width, img.height, template.size);
    const aligned = alignedDistance(img, box, template, 4, wide);
    if (aligned.distance <= maxDistance && (!best || aligned.distance < best.distance)) {
      best = { ...sighting, box: aligned.box, distance: aligned.distance };
    }
  }
  return best;
}

// ---- 밝은 아이콘: 1분 넘게 남아 노란 초가 없는 동안 ----
// 1분 미만이 되면 아이콘이 어두워지고 가운데에 노란 초가 뜬다. 그 전에는 아이콘이 밝고
// 왼쪽 아래에 작은 흰 분 숫자만 붙으며, 분 안에서 남은 초만큼 아래부터 어두워진다.
// 그래서 스킬을 쓴 직후(완전히 밝을 때) 모양을 등록해 두고, 다시 뜨는 순간을 숫자 없이 찾는다.

/** 밝은 아이콘 왼쪽 아래 흰 분 숫자 칸 — 비교에서 뺀다 */
function isMinuteCell(gx: number, gy: number): boolean {
  return gx <= 5 && gy >= 10;
}

/** 녹화 영상(1080p)으로 맞춘 값: 막 밝아진 같은 아이콘 13~16, 다른 아이콘 40 이상 */
export const BRIGHT_MATCH = { maxDistance: 22 };
/** 칸 가장자리(테두리·틈)를 빼고 안쪽만 쓰는 비율 */
const SLOT_INSET = 0.12;

export function brightDistance(a: ArrayLike<number>, b: ArrayLike<number>): number {
  return maskedDistance(a, b, isMinuteCell);
}

function luminance(img: Rgba, x: number, y: number): number {
  const i = (y * img.width + x) * 4;
  return 0.299 * (img.data[i] as number) + 0.587 * (img.data[i + 1] as number) + 0.114 * (img.data[i + 2] as number);
}

/** 평균을 뺀 자기상관이 가장 큰 간격. 두 배 간격을 잡았으면 절반으로 */
function strongestPeriod(profile: Float64Array, minLag: number, maxLag: number): number | null {
  const n = profile.length;
  let mean = 0;
  for (const v of profile) mean += v;
  mean /= n;
  const score = new Map<number, number>();
  let best = 0;
  let bestScore = Number.NEGATIVE_INFINITY;
  for (let lag = minLag; lag <= Math.min(maxLag, Math.floor(n / 2)); lag++) {
    let s = 0;
    for (let i = 0; i + lag < n; i++) s += ((profile[i] as number) - mean) * ((profile[i + lag] as number) - mean);
    const v = s / (n - lag);
    score.set(lag, v);
    if (v > bestScore) {
      bestScore = v;
      best = lag;
    }
  }
  if (!best) return null;
  const half = Math.round(best / 2);
  if (half >= minLag && (score.get(half) ?? Number.NEGATIVE_INFINITY) >= 0.8 * bestScore) return half;
  return best;
}

export interface IconLayout {
  /** 아이콘 가로 간격(px) */
  pitch: number;
  /** 칸 왼쪽 경계 위치(0 ≤ x0 < pitch) */
  x0: number;
  /** 칸 안쪽 상자 한 변(px) */
  side: number;
}

/** 버프칸 사진의 아이콘 칸 배치: 세로 경계선이 반복되는 간격과, 테두리·틈이 가장 어두운 위치 */
export function iconLayout(img: Rgba): IconLayout | null {
  const { width: w, height: h } = img;
  if (w < 48 || h < 16) return null;
  const edge = new Float64Array(w);
  const column = new Float64Array(w);
  for (let x = 0; x < w; x++) {
    let e = 0;
    let s = 0;
    for (let y = 0; y < h; y++) {
      const v = luminance(img, x, y);
      s += v;
      if (x > 0) e += Math.abs(v - luminance(img, x - 1, y));
    }
    edge[x] = e / h;
    column[x] = s / h;
  }
  const pitch = strongestPeriod(edge, 24, 110);
  if (!pitch) return null;
  let x0 = 0;
  let darkest = Number.POSITIVE_INFINITY;
  for (let phase = 0; phase < pitch; phase++) {
    let s = 0;
    let n = 0;
    for (let x = phase; x < w; x += pitch) {
      s += column[x] as number;
      n++;
    }
    if (n && s / n < darkest) {
      darkest = s / n;
      x0 = phase;
    }
  }
  return { pitch, x0, side: pitch - Math.round(pitch * SLOT_INSET) * 2 };
}

/** (x..x+w) 구간의 가로 경계 세기 — row 위아래 한 줄씩 중 가장 센 곳 */
function horizontalEdge(img: Rgba, x: number, w: number, row: number): number {
  let best = 0;
  for (let r = row - 1; r <= row + 1; r++) {
    if (r < 1 || r >= img.height) continue;
    let s = 0;
    for (let i = x; i < x + w; i++) s += Math.abs(luminance(img, i, r) - luminance(img, i, r - 1));
    best = Math.max(best, s);
  }
  return best;
}

/** 누른 점이 든 아이콘의 안쪽 상자. 가로는 칸 배치로, 세로는 위·아래 테두리가 가장 뚜렷한 자리로 맞춘다 */
export function iconBoxAt(img: Rgba, x: number, y: number, layout: IconLayout | null = iconLayout(img)): Box | null {
  if (!layout) return null;
  const { pitch, x0, side } = layout;
  if (side > img.width || side > img.height) return null;
  const inset = (pitch - side) / 2;
  const left = x0 + Math.floor((x - x0) / pitch) * pitch;
  const bx = Math.max(0, Math.min(img.width - side, Math.round(left + inset)));
  let by = Math.max(0, Math.min(img.height - side, Math.round(y - side / 2)));
  let bestScore = -1;
  for (let top = Math.max(0, Math.round(y - side)); top <= Math.min(img.height - side, Math.round(y)); top++) {
    const score = horizontalEdge(img, bx, side, Math.round(top - inset)) + horizontalEdge(img, bx, side, Math.round(top + side + inset));
    if (score > bestScore) {
      bestScore = score;
      by = top;
    }
  }
  return { x: bx, y: by, w: side, h: side };
}

interface Integral {
  stride: number;
  sums: [Float64Array, Float64Array, Float64Array];
}

function integral(img: Rgba): Integral {
  const stride = img.width + 1;
  const size = stride * (img.height + 1);
  const r = new Float64Array(size);
  const g = new Float64Array(size);
  const b = new Float64Array(size);
  for (let y = 0; y < img.height; y++) {
    let sr = 0;
    let sg = 0;
    let sb = 0;
    for (let x = 0; x < img.width; x++) {
      const i = (y * img.width + x) * 4;
      const o = (y + 1) * stride + x + 1;
      sr += img.data[i] as number;
      sg += img.data[i + 1] as number;
      sb += img.data[i + 2] as number;
      r[o] = (r[o - stride] as number) + sr;
      g[o] = (g[o - stride] as number) + sg;
      b[o] = (b[o - stride] as number) + sb;
    }
  }
  return { stride, sums: [r, g, b] };
}

/** iconSignature 와 같은 칸 나누기로, 누적합에서 칸 평균을 바로 구한다 */
function integralCells(t: Integral, box: Box, out: Float32Array): Float32Array {
  for (let gy = 0; gy < ICON_GRID; gy++) {
    const y0 = box.y + Math.floor((gy * box.h) / ICON_GRID);
    const y1 = Math.max(y0 + 1, box.y + Math.floor(((gy + 1) * box.h) / ICON_GRID));
    for (let gx = 0; gx < ICON_GRID; gx++) {
      const x0 = box.x + Math.floor((gx * box.w) / ICON_GRID);
      const x1 = Math.max(x0 + 1, box.x + Math.floor(((gx + 1) * box.w) / ICON_GRID));
      const n = (x1 - x0) * (y1 - y0);
      const c = (gy * ICON_GRID + gx) * 3;
      for (let ch = 0; ch < 3; ch++) {
        const s = t.sums[ch] as Float64Array;
        out[c + ch] =
          ((s[y1 * t.stride + x1] as number) - (s[y0 * t.stride + x1] as number) - (s[y1 * t.stride + x0] as number) + (s[y0 * t.stride + x0] as number)) / n;
      }
    }
  }
  return out;
}

/** 밝을 때 등록할 아이콘 모양 */
export function brightTemplate(img: Rgba, box: Box): IconTemplate {
  return { cells: Array.from(iconSignature(img, box), (v) => Math.round(v)), size: box.w };
}

/**
 * 밝을 때 등록한 아이콘을 버프칸에서 찾는다(숫자 없이). 칸 열마다 위아래로 훑고, 가까운 몇 곳을 ±2px 로 다듬는다.
 * 분 안에서 시간이 지나면 아래부터 어두워져 거리가 커지므로, 막 밝아진 때(스킬을 쓴 직후)에 잘 맞는다.
 */
export function findBright(
  img: Rgba,
  template: IconTemplate,
  layout: IconLayout | null = iconLayout(img),
  maxDistance = BRIGHT_MATCH.maxDistance,
): { box: Box; distance: number; runnerUp: number } | null {
  if (!layout) return null;
  const side = template.size;
  if (side > img.width || side > img.height) return null;
  const t = integral(img);
  const cells = new Float32Array(ICON_GRID * ICON_GRID * 3);
  const at = (x: number, y: number) => brightDistance(integralCells(t, { x, y, w: side, h: side }, cells), template.cells);
  const inset = (layout.pitch - side) / 2;
  const coarse: { x: number; y: number; distance: number }[] = [];
  for (let left = layout.x0 - layout.pitch; left < img.width; left += layout.pitch) {
    const x = Math.round(left + inset);
    if (x < 0 || x + side > img.width) continue;
    let best: { x: number; y: number; distance: number } | null = null;
    for (let y = 0; y + side <= img.height; y += 2) {
      const distance = at(x, y);
      if (!best || distance < best.distance) best = { x, y, distance };
    }
    if (best) coarse.push(best);
  }
  coarse.sort((a, b) => a.distance - b.distance);
  let found: { box: Box; distance: number } | null = null;
  for (const c of coarse.slice(0, 3)) {
    for (let dy = -2; dy <= 2; dy++) {
      for (let dx = -2; dx <= 2; dx++) {
        const x = c.x + dx;
        const y = c.y + dy;
        if (x < 0 || y < 0 || x + side > img.width || y + side > img.height) continue;
        const distance = at(x, y);
        if (!found || distance < found.distance) found = { box: { x, y, w: side, h: side }, distance };
      }
    }
  }
  if (!found || found.distance > maxDistance) return null;
  const winner = found;
  // 다른 칸 중 가장 가까운 거리 — 비슷한 아이콘이 여럿이면 차이가 작다
  const runnerUp = coarse.find((c) => Math.abs(c.x - winner.box.x) > layout.pitch / 2)?.distance ?? Number.POSITIVE_INFINITY;
  return { ...winner, runnerUp };
}

/** 노란 숫자가 떠 있는 칸(안쪽 상자)을 주어진 모양과 가운데(숫자)를 빼고 비교한 거리. ±2px 안에서 가장 가까운 자리 */
export function slotRingDistance(img: Rgba, cx: number, cy: number, layout: IconLayout, cells: ArrayLike<number>, wide = false): number {
  const box = iconBoxAt(img, cx, cy, layout);
  if (!box) return Number.POSITIVE_INFINITY;
  let best = Number.POSITIVE_INFINITY;
  for (let dy = -2; dy <= 2; dy++) {
    for (let dx = -2; dx <= 2; dx++) {
      const x = box.x + dx;
      const y = box.y + dy;
      if (x < 0 || y < 0 || x + box.w > img.width || y + box.h > img.height) continue;
      best = Math.min(best, iconDistance(iconSignature(img, { ...box, x, y }), cells, wide));
    }
  }
  return best;
}
