import type { CountdownItem, RandomDelay, RepeatConfig } from "./settings";

/**
 * 종료 시각(endAt) 기준으로 알림 시각 목록을 만든다.
 * - 첫 알림: endAt - leadSec (leadSec 이 음수면 종료 후)
 * - 랜덤 지연: 첫 알림을 [min, max]초 사이에서 무작위로 늦춘다
 * - 반복: 첫 알림 뒤 intervalSec 간격으로 count 번 더
 */
export function planFires(
  endAt: number,
  leadSec: number,
  randomDelay: RandomDelay | null,
  repeat: RepeatConfig,
  rand: () => number = Math.random,
): number[] {
  let first = endAt - leadSec * 1000;
  if (randomDelay?.enabled) {
    const lo = Math.max(0, Math.min(randomDelay.minSec, randomDelay.maxSec));
    const hi = Math.max(lo, Math.max(randomDelay.minSec, randomDelay.maxSec));
    first += (lo + rand() * (hi - lo)) * 1000;
  }
  const fires = [first];
  if (repeat.enabled) {
    const interval = Math.max(1, repeat.intervalSec) * 1000;
    const count = Math.max(0, Math.floor(repeat.count));
    for (let k = 1; k <= count; k++) fires.push(first + k * interval);
  }
  return fires;
}

/** now 까지 지난 알림을 소비한다. 밀린 알림이 여러 개여도 소리는 한 번만 낸다. */
export function takeDue(fires: readonly number[], nextIndex: number, now: number): { fired: boolean; nextIndex: number } {
  let index = nextIndex;
  while (index < fires.length && (fires[index] as number) <= now) index++;
  return { fired: index > nextIndex, nextIndex: index };
}

export type CountdownStatus = "idle" | "running" | "paused" | "done";

export interface CountdownState {
  status: CountdownStatus;
  endAt: number | null;
  remainingMs: number | null;
  fires: number[];
  nextFire: number;
  lastAlertAt: number | null;
  /** 버프 연계로 멈춰 둔 것 — 버프가 다시 잡히면 이어서 돈다 */
  heldByBuff?: boolean;
  /** 자동 재시작 대기: 이 시각부터 새 주기가 시작된다(그 전까지는 '재시작까지' 표시) */
  startAt?: number;
}

export function idleState(): CountdownState {
  return { status: "idle", endAt: null, remainingMs: null, fires: [], nextFire: 0, lastAlertAt: null };
}

function planFrom(
  endAt: number,
  item: CountdownItem,
  randomDelay: RandomDelay | null,
  now: number,
  rand: () => number,
): number[] {
  const fires = planFires(endAt, item.leadSec, randomDelay, item.repeat, rand);
  // 알림 시점이 지속시간보다 길면 첫 알림이 이미 지난 시각이 된다 → 바로 한 번 울린다.
  const first = fires[0] as number;
  if (first < now) {
    const shift = now - first;
    return fires.map((at) => at + shift);
  }
  return fires;
}

export function startCountdown(
  item: CountdownItem,
  randomDelay: RandomDelay | null,
  now: number,
  rand: () => number = Math.random,
): CountdownState {
  const endAt = now + item.durationSec * 1000;
  return {
    status: "running",
    endAt,
    remainingMs: null,
    fires: planFrom(endAt, item, randomDelay, now, rand),
    nextFire: 0,
    lastAlertAt: null,
  };
}

/**
 * 화면에서 읽은 종료 시각에 맞춘다.
 * - 새 주기(다시 설치)거나 돌고 있지 않았으면 알림을 새로 짠다.
 * - 같은 주기에서 1.5초 넘게 어긋났을 때만 시각을 고치고, 이미 울린 알림은 다시 울리지 않는다.
 */
export function syncCountdown(
  state: CountdownState | undefined,
  item: CountdownItem,
  randomDelay: RandomDelay | null,
  endAt: number,
  now: number,
  restarted: boolean,
  rand: () => number = Math.random,
): CountdownState {
  if (!state || restarted || state.status !== "running" || state.endAt === null) {
    return {
      status: "running",
      endAt,
      remainingMs: null,
      fires: planFrom(endAt, item, randomDelay, now, rand),
      nextFire: 0,
      lastAlertAt: state?.lastAlertAt ?? null,
    };
  }
  if (Math.abs(state.endAt - endAt) <= 1500) return state;
  const fires = planFires(endAt, item.leadSec, randomDelay, item.repeat, rand);
  return { ...state, endAt, fires, nextFire: Math.min(state.nextFire, fires.length) };
}

export function pauseCountdown(state: CountdownState, now: number): CountdownState {
  if (state.status !== "running" || state.endAt === null) return state;
  return { ...state, status: "paused", remainingMs: Math.max(0, state.endAt - now), endAt: null };
}

/**
 * 버프 연계: 버프가 없으면 멈춰 둔다. 돌던 건 남은 시간 그대로, 아직 안 돌았거나 끝난 건 지속시간 전체로
 * 멈춰 두고 표시해, 버프가 다시 잡히면 resumeCountdown 으로 이어간다.
 */
export function holdCountdown(state: CountdownState | undefined, item: CountdownItem, now: number): CountdownState {
  if (state?.status === "running") return { ...pauseCountdown(state, now), heldByBuff: true };
  if (state?.status === "paused") return { ...state, heldByBuff: true };
  return { ...idleState(), status: "paused", remainingMs: item.durationSec * 1000, heldByBuff: true };
}

export function resumeCountdown(
  state: CountdownState,
  item: CountdownItem,
  randomDelay: RandomDelay | null,
  now: number,
  rand: () => number = Math.random,
): CountdownState {
  if (state.status !== "paused" || state.remainingMs === null) return state;
  const endAt = now + state.remainingMs;
  const fires = planFires(endAt, item.leadSec, randomDelay, item.repeat, rand);
  // 일시정지 전에 이미 울린 알림은 다시 울리지 않는다.
  const nextFire = Math.min(state.nextFire, fires.length);
  return { status: "running", endAt, remainingMs: null, fires, nextFire, lastAlertAt: state.lastAlertAt };
}

export function tickCountdown(state: CountdownState, now: number): { state: CountdownState; fired: boolean } {
  if (state.status !== "running" || state.endAt === null) return { state, fired: false };
  const due = takeDue(state.fires, state.nextFire, now);
  const finished = due.nextIndex >= state.fires.length && now >= state.endAt;
  if (!due.fired && !finished) return { state, fired: false };
  return {
    fired: due.fired,
    state: {
      ...state,
      nextFire: due.nextIndex,
      lastAlertAt: due.fired ? now : state.lastAlertAt,
      status: finished ? "done" : "running",
    },
  };
}

export function nextFireAt(state: CountdownState): number | null {
  if (state.status !== "running") return null;
  return state.fires[state.nextFire] ?? null;
}

export function remainingMs(state: CountdownState, now: number): number | null {
  if (state.status === "running" && state.endAt !== null) return state.endAt - now;
  if (state.status === "paused") return state.remainingMs;
  if (state.status === "done") return 0;
  return null;
}

const STATUSES: readonly CountdownStatus[] = ["idle", "running", "paused", "done"];

/** localStorage 에서 읽은 값 검증 */
export function parseCountdownState(raw: unknown): CountdownState | null {
  if (typeof raw !== "object" || raw === null) return null;
  const r = raw as Record<string, unknown>;
  const numOrNull = (v: unknown) => (v === null || (typeof v === "number" && Number.isFinite(v)) ? (v as number | null) : undefined);
  const endAt = numOrNull(r.endAt);
  const remaining = numOrNull(r.remainingMs);
  const lastAlertAt = numOrNull(r.lastAlertAt);
  if (
    typeof r.status !== "string" ||
    !(STATUSES as readonly string[]).includes(r.status) ||
    endAt === undefined ||
    remaining === undefined ||
    lastAlertAt === undefined ||
    !Array.isArray(r.fires) ||
    !r.fires.every((f) => typeof f === "number" && Number.isFinite(f)) ||
    typeof r.nextFire !== "number"
  ) {
    return null;
  }
  return {
    status: r.status as CountdownStatus,
    endAt,
    remainingMs: remaining,
    fires: r.fires as number[],
    nextFire: r.nextFire,
    lastAlertAt,
    ...(r.heldByBuff === true ? { heldByBuff: true } : {}),
    ...(typeof r.startAt === "number" && Number.isFinite(r.startAt) ? { startAt: r.startAt } : {}),
  };
}
