import type { Region } from "../core/settings";
import { startDemoCanvas } from "./demo";

export type SourceKind = "screen" | "video" | "demo";

export interface PixelRect {
  x: number;
  y: number;
  w: number;
  h: number;
}

export function scaleRegion(region: Region, width: number, height: number): PixelRect {
  const sx = width / region.srcW;
  const sy = height / region.srcH;
  const x = Math.max(0, Math.min(width - 1, Math.round(region.x * sx)));
  const y = Math.max(0, Math.min(height - 1, Math.round(region.y * sy)));
  return {
    x,
    y,
    w: Math.max(1, Math.min(width - x, Math.round(region.w * sx))),
    h: Math.max(1, Math.min(height - y, Math.round(region.h * sy))),
  };
}

async function attach(video: HTMLVideoElement): Promise<void> {
  video.muted = true;
  video.playsInline = true;
  await video.play();
  if (video.videoWidth > 0) return;
  await new Promise<void>((resolve, reject) => {
    const timer = setTimeout(() => reject(new Error("영상 크기를 알 수 없어요")), 5000);
    video.addEventListener(
      "loadedmetadata",
      () => {
        clearTimeout(timer);
        resolve();
      },
      { once: true },
    );
  });
}

export class CaptureSession {
  readonly kind: SourceKind;
  readonly video: HTMLVideoElement;
  private readonly stream: MediaStream | null;
  private readonly cleanup: () => void;
  private readonly canvas = document.createElement("canvas");
  private readonly ctx: CanvasRenderingContext2D;

  private constructor(kind: SourceKind, video: HTMLVideoElement, stream: MediaStream | null, cleanup: () => void) {
    this.kind = kind;
    this.video = video;
    this.stream = stream;
    this.cleanup = cleanup;
    const ctx = this.canvas.getContext("2d", { willReadFrequently: true });
    if (!ctx) throw new Error("캔버스를 만들 수 없어요");
    this.ctx = ctx;
  }

  static supported(): boolean {
    return typeof navigator !== "undefined" && !!navigator.mediaDevices?.getDisplayMedia && window.isSecureContext;
  }

  static async fromScreen(): Promise<CaptureSession> {
    const stream = await navigator.mediaDevices.getDisplayMedia({
      video: { frameRate: { ideal: 15, max: 30 } },
      audio: false,
    });
    return CaptureSession.fromStream("screen", stream, () => stream.getTracks().forEach((t) => t.stop()));
  }

  static async fromDemo(): Promise<CaptureSession> {
    const demo = startDemoCanvas();
    return CaptureSession.fromStream("demo", demo.stream, demo.stop);
  }

  /** 테스트용: 녹화 영상 파일을 화면 대신 쓴다 (?video=주소) */
  static async fromVideoUrl(url: string): Promise<CaptureSession> {
    const video = document.createElement("video");
    video.src = url;
    video.loop = true;
    await attach(video);
    return new CaptureSession("video", video, null, () => {
      video.pause();
      video.removeAttribute("src");
      video.load();
    });
  }

  private static async fromStream(kind: SourceKind, stream: MediaStream, stop: () => void): Promise<CaptureSession> {
    const video = document.createElement("video");
    video.srcObject = stream;
    try {
      await attach(video);
    } catch (error) {
      stop();
      throw error;
    }
    return new CaptureSession(kind, video, stream, stop);
  }

  get width(): number {
    return this.video.videoWidth;
  }

  get height(): number {
    return this.video.videoHeight;
  }

  onEnded(callback: () => void): void {
    this.stream?.getVideoTracks()[0]?.addEventListener("ended", callback, { once: true });
  }

  /** 영역(없으면 전체)의 현재 픽셀 */
  grab(region: Region | null): ImageData | null {
    const width = this.width;
    const height = this.height;
    if (!width || !height) return null;
    const rect = region ? scaleRegion(region, width, height) : { x: 0, y: 0, w: width, h: height };
    if (this.canvas.width !== rect.w || this.canvas.height !== rect.h) {
      this.canvas.width = rect.w;
      this.canvas.height = rect.h;
    }
    this.ctx.drawImage(this.video, rect.x, rect.y, rect.w, rect.h, 0, 0, rect.w, rect.h);
    return this.ctx.getImageData(0, 0, rect.w, rect.h);
  }

  /** 영역 선택 창에 보여줄 전체 화면 한 장 */
  snapshot(): HTMLCanvasElement {
    const canvas = document.createElement("canvas");
    canvas.width = this.width;
    canvas.height = this.height;
    canvas.getContext("2d")?.drawImage(this.video, 0, 0);
    return canvas;
  }

  stop(): void {
    this.cleanup();
  }
}
