import { useCallback, useState } from "react";
import { Activity, BellRing, RefreshCw } from "lucide-react";
import { idleState, nextFireAt, remainingMs, type CountdownState } from "../core/alarm";
import { fmtAgo, fmtClock } from "../core/format";
import { COUNTDOWN_SECTIONS, type CountdownItem, type CountdownSection, type PipSize } from "../core/settings";
import { AlertFlash, ItemIcon } from "./components";
import { useStore } from "./store";

const PIP_WINDOW: Record<PipSize, { width: number; height: number }> = {
  default: { width: 340, height: 300 },
  large: { width: 460, height: 400 },
  focus: { width: 640, height: 520 },
};

export function usePip() {
  const [win, setWin] = useState<Window | null>(null);
  const [error, setError] = useState<string | null>(null);

  const open = useCallback(async (size: PipSize = "default") => {
    const api = window.documentPictureInPicture;
    if (!api) {
      setError("이 브라우저는 PIP 창을 지원하지 않아요. 크롬이나 엣지에서 열어주세요.");
      return;
    }
    setError(null);
    const pipWindow = await api.requestWindow(PIP_WINDOW[size]);
    for (const sheet of Array.from(document.styleSheets)) {
      try {
        const style = pipWindow.document.createElement("style");
        style.textContent = Array.from(sheet.cssRules)
          .map((rule) => rule.cssText)
          .join("\n");
        pipWindow.document.head.appendChild(style);
      } catch {
        // 다른 출처 스타일시트는 규칙을 읽을 수 없으니 링크로 붙인다.
        if (sheet.href) {
          const link = pipWindow.document.createElement("link");
          link.rel = "stylesheet";
          link.href = sheet.href;
          pipWindow.document.head.appendChild(link);
        }
      }
    }
    pipWindow.document.title = "메이플 알리미";
    pipWindow.document.body.className = "pip-body";
    pipWindow.addEventListener("pagehide", () => setWin(null), { once: true });
    setWin(pipWindow);
  }, []);

  const close = useCallback(() => {
    win?.close();
    setWin(null);
  }, [win]);

  return { win, open, close, error };
}

export function PipView() {
  const { settings, countdowns, now, hunt, rune, controls } = useStore();
  // 켜진 타이머·룬·사냥 멈춤 (특수 코어는 빠짐)
  const sections = COUNTDOWN_SECTIONS;
  const rows: { section: CountdownSection; item: CountdownItem; state: CountdownState }[] = [];
  for (const section of sections) {
    for (const item of settings[section].items) {
      if (item.enabled) rows.push({ section, item, state: countdowns[item.id] ?? idleState() });
    }
  }
  return (
    <div className={`pip size-${settings.pip.size}`}>
      <AlertFlash />
      {rows.length === 0 && <div className="pip-empty">켜진 타이머가 없어요</div>}
      {rows.map(({ section, item, state }) => {
        const next = nextFireAt(state);
        const shown = next !== null ? next - now : remainingMs(state, now);
        return (
          <div className="pip-row" key={item.id}>
            <ItemIcon icon={item.icon} size={22} />
            <span className="pip-label">{item.label}</span>
            <span className={`t ${next !== null && next - now <= 10_000 ? "soon" : ""}`}>
              {state.status === "idle" ? "--" : fmtClock(shown)}
            </span>
            <button onClick={() => controls.start(section, item)} title="지금부터 다시 시작" aria-label={`${item.label} 다시 시작`}>
              <RefreshCw size={15} />
            </button>
          </div>
        );
      })}
      {settings.rune.enabled && (
        <div className="pip-row">
          <BellRing size={20} aria-hidden />
          <span className="pip-label">룬</span>
          <span className={`t ${rune.present ? "soon" : ""}`}>{rune.present ? "룬 있음!" : rune.watching ? "없음" : "--"}</span>
          <span />
        </div>
      )}
      {settings.huntStall.enabled && (
        <div className="pip-row">
          <Activity size={20} aria-hidden />
          <span className="pip-label">사냥 멈춤</span>
          <span className={`t ${hunt.stalled ? "soon" : ""}`}>
            {hunt.stalled ? "멈춤!" : hunt.watching && hunt.lastChangeAt !== null ? fmtAgo(now - hunt.lastChangeAt) : "--"}
          </span>
          <span />
        </div>
      )}
    </div>
  );
}
