export interface GrayFrame {
  gray: Uint8Array;
  width: number;
  height: number;
}

/**
 * RGBA → 회색조. 너비가 maxWidth 보다 크면 최근접 샘플링으로 줄인다
 * (평균을 내면 숫자 획 같은 얇은 변화가 묻히므로 일부러 최근접).
 */
export function toGray(
  image: { data: Uint8ClampedArray; width: number; height: number },
  maxWidth = 480,
): GrayFrame {
  const scale = image.width > maxWidth ? maxWidth / image.width : 1;
  const width = Math.max(1, Math.round(image.width * scale));
  const height = Math.max(1, Math.round(image.height * scale));
  const gray = new Uint8Array(width * height);
  for (let y = 0; y < height; y++) {
    const sy = Math.min(image.height - 1, Math.floor(y / scale));
    for (let x = 0; x < width; x++) {
      const sx = Math.min(image.width - 1, Math.floor(x / scale));
      const i = (sy * image.width + sx) * 4;
      gray[y * width + x] = Math.round(
        0.299 * (image.data[i] as number) + 0.587 * (image.data[i + 1] as number) + 0.114 * (image.data[i + 2] as number),
      );
    }
  }
  return { gray, width, height };
}

/** 밝기가 delta 넘게 달라진 픽셀 수 */
export function countChanged(a: Uint8Array, b: Uint8Array, delta: number): number {
  if (a.length !== b.length) return Number.POSITIVE_INFINITY;
  let changed = 0;
  for (let i = 0; i < a.length; i++) {
    if (Math.abs((a[i] as number) - (b[i] as number)) > delta) changed++;
  }
  return changed;
}

/**
 * 마지막으로 "바뀌었다"고 본 프레임과 비교한다. 직전 프레임과 비교하면
 * 경험치바처럼 아주 천천히 차오르는 변화를 놓칠 수 있어서다.
 */
export class ChangeDetector {
  private reference: Uint8Array | null = null;
  lastChangeAt: number | null = null;
  lastChangedPixels = 0;

  constructor(
    public minPixels: number,
    public delta = 24,
  ) {}

  reset(): void {
    this.reference = null;
    this.lastChangeAt = null;
    this.lastChangedPixels = 0;
  }

  /** 변화로 판정되면 true */
  feed(gray: Uint8Array, now: number): boolean {
    if (!this.reference || this.reference.length !== gray.length) {
      this.reference = gray;
      this.lastChangeAt = now;
      this.lastChangedPixels = 0;
      return true;
    }
    const changed = countChanged(this.reference, gray, this.delta);
    this.lastChangedPixels = changed;
    if (changed >= this.minPixels) {
      this.reference = gray;
      this.lastChangeAt = now;
      return true;
    }
    return false;
  }
}
