import { components, type PixelBlob, type Rgba } from "./digits";

/**
 * 미니맵의 룬 표시: 분홍·보라 마름모(가장자리는 밝은 회색).
 * 녹화 영상 측정: 속 픽셀은 (220,120,240) 근처 — 빨강·파랑 높고 초록 낮음.
 */
export function isRunePixel(r: number, g: number, b: number): boolean {
  return r > 150 && b > 160 && g < r - 50 && g < b - 60;
}

export interface RuneHit {
  x: number;
  y: number;
  size: number;
  pixels: number;
}

/**
 * 마름모다움: 줄별 폭이 가운데에서 가장 넓고 위·아래로 고르게 줄어드는 정도(상관, 1이면 완전한 마름모).
 * 실제 룬 표시 0.96~0.98, 꽃·효과 같은 불규칙한 덩어리는 낮다.
 */
function diamondScore(blob: PixelBlob, width: number): number {
  const h = blob.y1 - blob.y0 + 1;
  const widths = new Array<number>(h).fill(0);
  for (const p of blob.pixels) {
    const k = Math.floor(p / width) - blob.y0;
    widths[k] = (widths[k] ?? 0) + 1;
  }
  const cy = (h - 1) / 2;
  const ideal = widths.map((_, k) => 1 - Math.abs(k - cy) / (cy + 1));
  const mw = widths.reduce((a, v) => a + v, 0) / h;
  const mi = ideal.reduce((a, v) => a + v, 0) / h;
  let num = 0;
  let dw = 0;
  let di = 0;
  widths.forEach((v, k) => {
    const a = v - mw;
    const b = (ideal[k] as number) - mi;
    num += a * b;
    dw += a * a;
    di += b * b;
  });
  return dw && di ? num / Math.sqrt(dw * di) : 0;
}

/** 크기·모양이 룬 표시다운 덩어리만 고른다 (미니맵 안 다른 보라색 효과·꽃·둥근 표시 배제) */
export function detectRune(img: Rgba): RuneHit | null {
  const mask = new Uint8Array(img.width * img.height);
  for (let p = 0, i = 0; p < mask.length; p++, i += 4) {
    if (isRunePixel(img.data[i] as number, img.data[i + 1] as number, img.data[i + 2] as number)) mask[p] = 1;
  }
  // 미니맵을 넉넉하게 크게 잡아도 작은 룬이 빠지지 않게
  const minSide = Math.max(4, Math.round(img.height * 0.015));
  const maxSide = Math.max(minSide + 2, Math.round(img.height * 0.25));
  let best: (PixelBlob & { fill: number }) | null = null;
  for (const blob of components(mask, img.width, img.height)) {
    const w = blob.x1 - blob.x0 + 1;
    const h = blob.y1 - blob.y0 + 1;
    if (w < minSide || h < minSide || w > maxSide || h > maxSide) continue;
    const aspect = w / h;
    if (aspect < 0.5 || aspect > 2) continue;
    const fill = blob.pixels.length / (w * h);
    // 마름모는 상자의 절반쯤 찬다(실측 0.55~0.57). 둥근 점(약 0.78)·네모(1)는 룬이 아니다.
    // 캐릭터 점이 조금 가려 모양이 덜 고르게 돼도 마름모는 남긴다(둥근 점은 채움 비율로 빠진다)
    if (fill < 0.35 || fill > 0.7 || blob.pixels.length < 10) continue;
    if (diamondScore(blob, img.width) < 0.75) continue;
    if (!best || blob.pixels.length > best.pixels.length) best = { ...blob, fill };
  }
  if (!best) return null;
  return {
    x: (best.x0 + best.x1) / 2,
    y: (best.y0 + best.y1) / 2,
    size: Math.max(best.x1 - best.x0 + 1, best.y1 - best.y0 + 1),
    pixels: best.pixels.length,
  };
}

/** 깜빡임·잠깐 가림에 흔들리지 않게: 최근 3번 중 2번 보이면 있음, 3번 연속 안 보이면 없음 */
export class RuneDebouncer {
  private history: boolean[] = [];
  present = false;

  update(found: boolean): { present: boolean; appeared: boolean; vanished: boolean } {
    this.history = [...this.history.slice(-2), found];
    const hits = this.history.filter(Boolean).length;
    const before = this.present;
    if (!this.present && hits >= 2) this.present = true;
    else if (this.present && this.history.length >= 3 && hits === 0) this.present = false;
    return { present: this.present, appeared: !before && this.present, vanished: before && !this.present };
  }

  reset(): void {
    this.history = [];
    this.present = false;
  }
}
