import { useCallback, useMemo, useState, type MouseEvent } from "react";
import type { CaptureSession } from "../capture/capture";
import type { Region } from "../core/settings";
import { brightTemplate, iconBoxAt, iconLayout, scanBuffBar, toTemplate, type Box, type IconTemplate } from "../detect/buffbar";
import { Modal } from "./components";

export interface PickedIcons {
  /** 노란 초가 떠 있는 아이콘을 골랐을 때 */
  autoIcon: IconTemplate | null;
  /** 초가 없는(1분 넘게 남은) 밝은 아이콘을 골랐을 때 */
  autoBright: IconTemplate | null;
}

/** 버프칸 사진에서 이 항목의 아이콘을 고른다. 초가 떠 있지 않은 아이콘도 고를 수 있다. */
export function IconPicker({
  session,
  region,
  label,
  onSave,
  onClose,
}: {
  session: CaptureSession;
  region: Region;
  label: string;
  onSave: (icons: PickedIcons) => void;
  onClose: () => void;
}) {
  const [frame, setFrame] = useState(() => session.grab(region));
  const [picked, setPicked] = useState<Box | null>(null);
  const sightings = useMemo(() => (frame ? scanBuffBar(frame) : []), [frame]);
  const layout = useMemo(() => (frame ? iconLayout(frame) : null), [frame]);
  const drawFrame = useCallback(
    (canvas: HTMLCanvasElement | null) => {
      if (!canvas || !frame) return;
      canvas.width = frame.width;
      canvas.height = frame.height;
      canvas.getContext("2d")?.putImageData(frame, 0, 0);
    },
    [frame],
  );
  const pct = (value: number, total: number) => `${(value / total) * 100}%`;
  // 고른 칸에 노란 초가 떠 있으면 그 숫자 아이콘(어두운 모양)으로, 없으면 밝은 아이콘 모양으로 감지한다.
  // 초는 아이콘 한가운데에 뜬다 — 칸 가장자리에 걸린 옆 아이콘의 초를 고른 아이콘 것으로 보지 않는다.
  const numbered = picked
    ? sightings.find(
        (s) =>
          Math.abs(s.number.cx - (picked.x + picked.w / 2)) <= picked.w * 0.3 &&
          Math.abs(s.number.cy - (picked.y + picked.h / 2)) <= picked.h * 0.3,
      )
    : undefined;

  const pick = (event: MouseEvent<HTMLDivElement>) => {
    if (!frame) return;
    const rect = event.currentTarget.getBoundingClientRect();
    const x = ((event.clientX - rect.left) / rect.width) * frame.width;
    const y = ((event.clientY - rect.top) / rect.height) * frame.height;
    setPicked(iconBoxAt(frame, x, y, layout));
  };

  const save = () => {
    if (!frame || !picked) return;
    onSave(numbered ? { autoIcon: toTemplate(numbered), autoBright: null } : { autoIcon: null, autoBright: brightTemplate(frame, picked) });
  };

  return (
    <Modal
      title={`버프 아이콘 감지 — ${label}`}
      onClose={onClose}
      wide
      footer={
        <>
          <span className="muted foot-info">
            {!picked
              ? "버프칸에서 이 항목의 아이콘을 눌러 고르세요"
              : numbered
                ? "노란 초가 떠 있는 아이콘 — 1분 미만 초를 읽어 맞춰요"
                : "밝은 아이콘 — 다시 뜨는 순간 타이머를 시작하고, 1분 밑으로 내려가면 초로 맞춰요"}
          </span>
          <button
            className="btn"
            onClick={() => {
              setFrame(session.grab(region));
              setPicked(null);
            }}
          >
            지금 화면 다시 찍기
          </button>
          <button className="btn" onClick={onClose}>
            취소
          </button>
          <button className="btn primary" disabled={!picked} onClick={save}>
            감지 시작
          </button>
        </>
      }
    >
      <p className="muted">
        스킬을 쓴 직후 [지금 화면 다시 찍기]를 누르고, 버프칸에서 이 항목의 아이콘을 눌러주세요. 1분 넘게 남아 초가 안 떠 있어도 돼요 —
        아이콘이 밝을 때 고르면 다음에 쓸 때 뜨는 순간 바로 잡아요.
      </p>
      {frame ? (
        <div className="icon-picker selectable" onClick={pick}>
          <canvas ref={drawFrame} />
          {picked && (
            <div
              className="icon-hit on"
              style={{
                left: pct(picked.x, frame.width),
                top: pct(picked.y, frame.height),
                width: pct(picked.w, frame.width),
                height: pct(picked.h, frame.height),
              }}
            />
          )}
        </div>
      ) : (
        <p className="err">화면을 읽지 못했어요. 화면 공유가 켜져 있는지 확인해주세요.</p>
      )}
    </Modal>
  );
}
