/** 직접 입력 항목: 원본처럼 그림 대신 '직접' 글자 */
export const CUSTOM_ICON = "직접";

export function isImageIcon(icon: string): boolean {
  return /\.(png|svg|webp)$/i.test(icon);
}

/**
 * 예전 버전(이모지 아이콘)으로 저장된 기본 항목을 원본 그림으로 바꾼다.
 * 사용자가 직접 넣은 다른 이모지는 그대로 둔다.
 */
export function migrateIcon(section: CountdownSection, icon: string, label: string): string {
  switch (section) {
    case "skill": {
      const map: Record<string, string> = {
        "🌅": ICONS.solJanus,
        "⛲": ICONS.erdaFountain,
        "🚪": ICONS.gateOfLight,
        "🔮": ICONS.liberationOrb,
        "🗡️": ICONS.swordOfBurningSoul,
        "❄️": ICONS.frozenGround,
        "🌀": ICONS.heupseongWaryu,
        "🧱": ICONS.hologramGraffiti,
        "🌸": ICONS.maehwaYein,
        "🪨": ICONS.petrified,
        "🧩": ICONS.classInstall,
      };
      return map[icon] ?? icon;
    }
    case "buffExpiry": {
      const map: Record<string, string> = {
        "🎟️": ICONS.expCoupon,
        "💰": ICONS.smallWealthPotion,
        "📗": ICONS.smallExpPotion,
        "🏦": ICONS.unionWealth,
        "🍀": ICONS.unionLuck,
        "✨": CUSTOM_ICON,
      };
      return map[icon] ?? icon;
    }
    case "general": {
      const ten = /10분/.test(label);
      const map: Record<string, string> = {
        "💰": ICONS.timer30Wealth,
        "📗": ICONS.timer30Exp,
        "🏦": ten ? ICONS.timer10UnionWealth : ICONS.timer20UnionWealth,
        "🍀": ten ? ICONS.timer10UnionLuck : ICONS.timer20UnionLuck,
        "💎": ICONS.timer2hWealth,
        "📘": ICONS.timer2hExp,
        "⏱️": CUSTOM_ICON,
      };
      return map[icon] ?? icon;
    }
    case "booster":
      return icon === "🚀" ? ICONS.vipBooster : icon;
    default:
      return icon;
  }
}
