import type { SoundId, Voice } from "../core/settings";

/** 문구 개수(scripts/make-sounds.sh 와 같게). 무작위 문구를 켜면 이 중에서 고른다(1번이 기본) */
export const PHRASE_COUNT: Record<SoundId, number> = {
  janus: 4,
  fountain: 4,
  skill: 3,
  rune: 3,
  huntStall: 3,
  buffExpiry: 2,
  booster: 2,
  specialCore: 2,
  timerDone: 2,
  collect: 2,
  test: 1,
};

/** 무작위면 1~문구개수 중 하나, 아니면 기본 문구 파일 이름 */
export function phraseFile(id: SoundId, random: boolean, rand: () => number = Math.random): string {
  const count = random ? PHRASE_COUNT[id] : 1;
  const pick = 1 + Math.floor(rand() * count);
  return pick === 1 ? id : `${id}-${pick}`;
}

class SoundPlayer {
  private ctx: AudioContext | null = null;
  private cache = new Map<string, Promise<AudioBuffer | null>>();
  master = 1;
  voice: Voice = "st-f1";
  muted = false;
  randomPhrase = false;

  /** 브라우저 자동재생 정책 때문에 사용자 입력 시점에 오디오를 연다. */
  unlock(): AudioContext {
    if (!this.ctx) this.ctx = new AudioContext();
    if (this.ctx.state === "suspended") void this.ctx.resume();
    return this.ctx;
  }

  private load(ctx: AudioContext, voice: Voice, id: string): Promise<AudioBuffer | null> {
    const key = `${voice}/${id}`;
    let pending = this.cache.get(key);
    if (!pending) {
      pending = fetch(`./sounds/${key}.wav`)
        .then((res) => {
          if (!res.ok) throw new Error(`HTTP ${res.status}`);
          return res.arrayBuffer();
        })
        .then((bytes) => ctx.decodeAudioData(bytes))
        .catch((error: unknown) => {
          console.warn(`음성 파일(${key})을 불러오지 못해 이번엔 삐 소리로 대신합니다`, error);
          // 실패를 기억하지 않는다 — 사이트가 잠깐 막혔어도 다음 알림 때 다시 불러온다
          this.cache.delete(key);
          return null;
        });
      this.cache.set(key, pending);
    }
    return pending;
  }

  async play(id: SoundId, options: { force?: boolean; volume?: number } = {}): Promise<void> {
    if (this.muted && !options.force) return;
    const ctx = this.unlock();
    const gain = ctx.createGain();
    gain.gain.value = Math.max(0, Math.min(1, this.master * (options.volume ?? 1)));
    gain.connect(ctx.destination);
    const buffer = await this.load(ctx, this.voice, phraseFile(id, this.randomPhrase));
    if (buffer) {
      const source = ctx.createBufferSource();
      source.buffer = buffer;
      source.connect(gain);
      source.start();
      return;
    }
    const osc = ctx.createOscillator();
    osc.frequency.value = 880;
    osc.connect(gain);
    osc.start();
    osc.stop(ctx.currentTime + 0.25);
  }
}

export const sound = new SoundPlayer();

export function desktopNotify(title: string, body?: string): void {
  if (typeof Notification === "undefined" || Notification.permission !== "granted") return;
  new Notification(title, { body, silent: true, tag: title });
}
