import { Crosshair } from "lucide-react";
import { fmtAgo } from "../../core/format";
import type { HuntMode, Settings } from "../../core/settings";
import { BuffLinkBar, LinkMenu, NumberInput, RegionPreview, RepeatEditor, Stat, StatusDot, Toggle, VolumeInput, type Tone } from "../components";
import { Panel, type PanelCommon } from "../Panel";
import { useStore } from "../store";

/** 감시 방식별 안내 — 감지는 모두 '영역 픽셀이 [멈춤 기준]초 동안 안 바뀌면 멈춤'으로 같다 */
export const HUNT_MODES: Record<HuntMode, { label: string; pick: string; hint: string; stat: string; help: string }> = {
  exp: {
    label: "경험치 인식",
    pick: "경험치바 영역 선택",
    hint: "화면 맨 아래 경험치바를 숫자(%)까지 포함해서 드래그해주세요. 실제 사냥터에서 잡아주세요.",
    stat: "마지막 경험치 변화",
    help: "화면 아래 경험치바(숫자 포함)를 영역으로 잡으면, 경험치가 [멈춤 기준]초 동안 안 바뀔 때 알려줘요.",
  },
  cooldown: {
    label: "쿨타임 인식",
    pick: "퀵슬롯 영역 선택",
    hint: "오른쪽 아래 퀵슬롯에서 사냥할 때 쓰는 스킬 아이콘들을 쿨타임 숫자까지 포함해서 드래그해주세요.",
    stat: "마지막 쿨타임 변화",
    help: "사냥 스킬 퀵슬롯을 영역으로 잡으면, 쿨타임 숫자가 [멈춤 기준]초 동안 안 바뀔 때(스킬을 안 쓸 때) 알려줘요.",
  },
  mana: {
    label: "마나 인식",
    pick: "MP 영역 선택",
    hint: "HP는 제외하고 MP 숫자와 마나 바만 드래그해주세요. 솔 헤카테처럼 마나를 저절로 채우는 효과는 꺼주세요.",
    stat: "마지막 마나 변화",
    help: "MP 숫자와 마나 바를 영역으로 잡으면, 마나가 [멈춤 기준]초 동안 안 바뀔 때(스킬을 안 쓸 때) 알려줘요.",
  },
};

export function HuntStallPanel({ common, onPick }: { common: PanelCommon; onPick: () => void }) {
  const { settings, update, capture, hunt, now, presence } = useStore();
  const config = settings.huntStall;
  const set = (patch: Partial<Settings["huntStall"]>) => update((s) => ({ ...s, huntStall: { ...s.huntStall, ...patch } }));
  const status: { tone: Tone; label: string } = !capture
    ? { tone: "danger", label: "화면 공유 필요" }
    : !config.region
      ? { tone: "warn", label: "영역 선택 필요" }
      : !config.enabled
        ? { tone: "muted", label: "꺼짐" }
        : hunt.blocked
          ? { tone: "warn", label: "버프 대기" }
          : hunt.stalled
          ? { tone: "danger", label: "멈춤!" }
          : { tone: "ok", label: "감시 중" };
  return (
    <Panel
      id="huntStall"
      common={common}
      active={config.enabled}
      actions={
        <LinkMenu
          summary={`버프 연계 · ${config.requireTrackedBuff ? (presence === "disabled" ? "설정 필요" : "사용 중") : "꺼짐"}`}
          active={config.requireTrackedBuff}
          label="사냥 멈춤 버프 연계 설정"
        >
          <Toggle
            checked={config.requireTrackedBuff}
            onChange={(requireTrackedBuff) => set({ requireTrackedBuff })}
            label="버프가 있을 때만 감시"
          />
          <p className="muted">버프 종료 알림의 버프 중 하나라도 감지될 때만 사냥 멈춤을 감시해요.</p>
          {config.requireTrackedBuff && presence === "disabled" && (
            <p className="link-warning">버프 종료 알림에 켜진 버프가 없어요. 버프 종료 알림에서 ＋ 추가로 버프를 넣고 아이콘을 등록해 주세요.</p>
          )}
        </LinkMenu>
      }
      help={
        <ul>
          <li>감시 방식: 경험치 인식(경험치바) · 쿨타임 인식(사냥 스킬 퀵슬롯) · 마나 인식(MP). 바꾸면 영역을 다시 골라주세요.</li>
          <li>{HUNT_MODES[config.mode].help}</li>
          <li>감도는 몇 픽셀 이상 바뀌어야 경험치가 오른 것으로 볼지예요. 오탐이 나면 올리고, 놓치면 내려주세요.</li>
          <li>다시 사냥을 시작해 경험치가 바뀌면 자동으로 감시를 이어가요.</li>
        </ul>
      }
    >
      {config.requireTrackedBuff && <BuffLinkBar />}
      <div className="row">
        <div className="row-main hunt">
          <Toggle checked={config.enabled} onChange={(enabled) => set({ enabled })} label={config.enabled ? "켜짐" : "꺼짐"} />
          <div className="region-cell">
            <select
              className="add-select"
              value={config.mode}
              aria-label="감시 방식"
              onChange={(e) => set({ mode: e.target.value as HuntMode, region: null })}
            >
              {(Object.keys(HUNT_MODES) as HuntMode[]).map((mode) => (
                <option key={mode} value={mode}>
                  {HUNT_MODES[mode].label}
                </option>
              ))}
            </select>
            <RegionPreview region={config.region} />
            <button className="btn" disabled={!capture} onClick={onPick}>
              <Crosshair size={15} />
              {config.region ? "영역 다시 선택" : HUNT_MODES[config.mode].pick}
            </button>
          </div>
          <Stat
            label={HUNT_MODES[config.mode].stat}
            value={<span data-testid="hunt-last-change">{hunt.watching && hunt.lastChangeAt !== null ? fmtAgo(now - hunt.lastChangeAt) : "--"}</span>}
          />
          <Stat
            label="멈춤 기준"
            value={<NumberInput value={config.stallSec} min={3} max={3600} suffix="초 무변동" width={52} onChange={(stallSec) => set({ stallSec })} />}
          />
          <Stat label="반복" value={<RepeatEditor value={config.repeat} onChange={(repeat) => set({ repeat })} />} />
          <Stat label="마지막 알림" value={<span data-testid="hunt-last-alert">{hunt.lastAlertAt !== null ? fmtAgo(now - hunt.lastAlertAt) : "--"}</span>} />
          <StatusDot tone={status.tone}>
            <span data-testid="hunt-status">{status.label}</span>
          </StatusDot>
        </div>
        <div className="sub-row">
          감도
          <NumberInput value={config.sensitivity} min={1} max={500} suffix="픽셀 이상 바뀌면 변화로 봐요" width={52} onChange={(sensitivity) => set({ sensitivity })} />
          {hunt.watching && <span className="muted">지금 바뀐 픽셀 {hunt.changedPixels}</span>}
          <span className="sub-sep">볼륨</span>
          <VolumeInput value={config.volume} label="사냥 멈춤 알림 볼륨" onChange={(volume) => set({ volume })} />
        </div>
      </div>
    </Panel>
  );
}
