import { components, type PixelBlob, type Rgba } from "./digits";

/**
 * 화면 맨 위 가운데 부스터 타이머('남은시간 99.28 초')를 읽는다.
 * 숫자가 7세그먼트 글꼴(노랑~주황, 어두운 상자 위)이라 버프칸 숫자 견본 대신 세그먼트 7개가 켜졌는지로 읽는다.
 */

export interface BoosterReading {
  /** 남은 시간(초, 소수 둘째 자리까지) */
  seconds: number;
  text: string;
  cx: number;
  cy: number;
  h: number;
}

/** 숫자 획: 위쪽은 흰색, 아래로 갈수록 노랑·주황(어두운 상자 위라 밝기로 가른다, 푸른 빛은 뺀다) */
function isWarm(r: number, g: number, b: number): boolean {
  return 0.299 * r + 0.587 * g + 0.114 * b >= 135 && r >= 120 && b <= r + 5;
}

export function warmMask(img: Rgba): Uint8Array {
  const mask = new Uint8Array(img.width * img.height);
  const d = img.data;
  for (let i = 0; i < mask.length; i++) {
    if (isWarm(d[i * 4] as number, d[i * 4 + 1] as number, d[i * 4 + 2] as number)) mask[i] = 1;
  }
  return mask;
}

interface Cell {
  x0: number;
  y0: number;
  x1: number;
  y1: number;
}

/**
 * 같은 숫자의 세그먼트 조각을 가로로 겹치는 것끼리 묶어 숫자 칸을 만든다.
 * 가늘고 긴 조각(세그먼트)이나 숫자만큼 큰 덩어리만 묶는다 — '남은시간'·'초' 글자처럼 둥글듯한 덩어리는 옆 숫자에 붙지 않게.
 */
function mergeCells(blobs: PixelBlob[], minDigitH: number): Cell[] {
  const mergeable = (b: Cell) => {
    const w = b.x1 - b.x0 + 1;
    const h = b.y1 - b.y0 + 1;
    // 한 픽셀 두께의 선(상자 테두리 조각)은 세그먼트가 아니다
    if (Math.min(w, h) < 2) return false;
    return h >= minDigitH * 0.8 || Math.max(w, h) / Math.min(w, h) >= 1.8;
  };
  // 한 숫자의 세그먼트 사이 틈은 두어 픽셀 — 위·아래 다른 UI 와는 붙이지 않는다
  const maxGapY = Math.max(2, Math.round(minDigitH * 0.2));
  // 세로 획이 가로 획 끝에서 한 픽셀 비저나오는 것(6의 오른쪽 아래 등)도 같은 숫자로 본다
  const slackX = 1;
  const cells: Cell[] = blobs.map((b) => ({ x0: b.x0, y0: b.y0, x1: b.x1, y1: b.y1 })).filter(mergeable);
  let merged = true;
  while (merged) {
    merged = false;
    outer: for (let i = 0; i < cells.length; i++) {
      for (let j = i + 1; j < cells.length; j++) {
        const a = cells[i] as Cell;
        const b = cells[j] as Cell;
        const overlapX = Math.min(a.x1, b.x1) - Math.max(a.x0, b.x0) + 1 + slackX;
        const narrow = Math.min(a.x1 - a.x0 + 1, b.x1 - b.x0 + 1);
        const gapY = Math.max(a.y0, b.y0) - Math.min(a.y1, b.y1);
        if (overlapX >= narrow * 0.5 && gapY <= maxGapY) {
          cells[i] = { x0: Math.min(a.x0, b.x0), y0: Math.min(a.y0, b.y0), x1: Math.max(a.x1, b.x1), y1: Math.max(a.y1, b.y1) };
          cells.splice(j, 1);
          merged = true;
          break outer;
        }
      }
    }
  }
  return cells;
}

// 세그먼트: a 위, b 오른쪽 위, c 오른쪽 아래, d 아래, e 왼쪽 아래, f 왼쪽 위, g 가운데
const SEGMENTS: Record<string, number> = {
  abcdef: 0,
  bc: 1,
  abdeg: 2,
  abcdg: 3,
  bcfg: 4,
  acdfg: 5,
  acdefg: 6,
  abc: 7,
  abcf: 7,
  abcdefg: 8,
  abcdfg: 9,
  abcfg: 9,
};

function coverage(mask: Uint8Array, width: number, x0: number, y0: number, x1: number, y1: number): number {
  let on = 0;
  let total = 0;
  for (let y = Math.round(y0); y <= Math.round(y1); y++) {
    for (let x = Math.round(x0); x <= Math.round(x1); x++) {
      total++;
      if (mask[y * width + x]) on++;
    }
  }
  return total ? on / total : 0;
}

/** 숫자 칸 하나를 세그먼트로 읽는다. 모르는 모양이면 null */
export function decodeCell(mask: Uint8Array, width: number, cell: Cell): number | null {
  const w = cell.x1 - cell.x0 + 1;
  const h = cell.y1 - cell.y0 + 1;
  // 1 은 오른쪽 세로 획만 있어 칸이 좁다
  if (w < h * 0.4) return 1;
  const X = (f: number) => cell.x0 + f * (w - 1);
  const Y = (f: number) => cell.y0 + f * (h - 1);
  const on = (x0: number, y0: number, x1: number, y1: number) => coverage(mask, width, X(x0), Y(y0), X(x1), Y(y1)) >= 0.3;
  const segs = [
    on(0.3, 0, 0.7, 0.12) ? "a" : "",
    on(0.75, 0.2, 1, 0.4) ? "b" : "",
    on(0.75, 0.6, 1, 0.8) ? "c" : "",
    on(0.3, 0.88, 0.7, 1) ? "d" : "",
    on(0, 0.6, 0.25, 0.8) ? "e" : "",
    on(0, 0.2, 0.25, 0.4) ? "f" : "",
    on(0.3, 0.44, 0.7, 0.56) ? "g" : "",
  ].join("");
  return SEGMENTS[segs] ?? null;
}

/**
 * 부스터 타이머를 읽는다. minDigitH 보다 작은 숫자(버프칸 초 등)는 무시하고,
 * 가운데에 가장 가까운 'N(N)(N).NN' 줄을 고른다. 소수 둘째 자리까지 있어야 타이머로 본다.
 */
export function readBoosterTimer(img: Rgba, minDigitH: number): BoosterReading | null {
  const mask = warmMask(img);
  // 상자 테두리처럼 넓게 퍼진 얇은 선은 뺀다(세그먼트는 작고 채움이 높다)
  const blobs = components(mask, img.width, img.height).filter((b) => {
    const w = b.x1 - b.x0 + 1;
    const h = b.y1 - b.y0 + 1;
    return b.pixels.length >= 3 && h <= minDigitH * 3.2 && w <= minDigitH * 2 && b.pixels.length / (w * h) >= 0.15;
  });
  const cells = mergeCells(blobs, minDigitH).filter((c) => {
    const h = c.y1 - c.y0 + 1;
    const w = c.x1 - c.x0 + 1;
    return h >= minDigitH && h <= minDigitH * 3.2 && w <= h * 0.95;
  });
  // 높이·세로 위치가 비슷한 칸끼리 한 줄로
  const rows: Cell[][] = [];
  for (const cell of [...cells].sort((a, b) => a.x0 - b.x0)) {
    const h = cell.y1 - cell.y0 + 1;
    const cy = (cell.y0 + cell.y1) / 2;
    const row = rows.find((r) => {
      const last = r[r.length - 1] as Cell;
      const lh = last.y1 - last.y0 + 1;
      return Math.abs((last.y0 + last.y1) / 2 - cy) <= lh * 0.3 && h / lh > 0.75 && h / lh < 1.33 && cell.x0 - last.x1 <= lh * 1.2;
    });
    if (row) row.push(cell);
    else rows.push([cell]);
  }
  const centerX = img.width / 2;
  let best: BoosterReading | null = null;
  for (const row of rows) {
    if (row.length < 3 || row.length > 6) continue;
    const digits = row.map((cell) => decodeCell(mask, img.width, cell));
    if (digits.some((d) => d === null)) continue;
    const intPart = digits.slice(0, -2).join("");
    const fracPart = digits.slice(-2).join("");
    // 정수 끝과 소수 첫 칸 사이에는 점이 있어 다른 칸 사이보다 넓다
    const gaps = row.slice(1).map((cell, i) => cell.x0 - (row[i] as Cell).x1);
    const dotGap = gaps[gaps.length - 2] as number;
    const others = gaps.filter((_, i) => i !== gaps.length - 2);
    if (others.length && dotGap <= Math.max(...others)) continue;
    const x0 = (row[0] as Cell).x0;
    const x1 = (row[row.length - 1] as Cell).x1;
    const y0 = Math.min(...row.map((c) => c.y0));
    const y1 = Math.max(...row.map((c) => c.y1));
    // 타이머는 어두운 상자 안에 있다 — 게임 화면 위에 뜬 데미지 숫자 등은 걸러낸다
    if (darkAround(img, x0, y0, x1, y1) < 0.5) continue;
    const reading: BoosterReading = {
      seconds: Number(`${intPart}.${fracPart}`),
      text: `${intPart}.${fracPart}`,
      cx: (x0 + x1) / 2,
      cy: (y0 + y1) / 2,
      h: y1 - y0 + 1,
    };
    if (!best || Math.abs(reading.cx - centerX) < Math.abs(best.cx - centerX)) best = reading;
  }
  return best;
}

/** 줄 둘레(숫자 높이의 1/4 두께)에서 어두운 픽셀 비율 */
function darkAround(img: Rgba, x0: number, y0: number, x1: number, y1: number): number {
  const m = Math.max(2, Math.round((y1 - y0 + 1) * 0.25));
  const xa = Math.max(0, x0 - m);
  const xb = Math.min(img.width - 1, x1 + m);
  const ya = Math.max(0, y0 - m);
  const yb = Math.min(img.height - 1, y1 + m);
  let dark = 0;
  let total = 0;
  const d = img.data;
  for (let y = ya; y <= yb; y++) {
    for (let x = xa; x <= xb; x++) {
      if (x >= x0 && x <= x1 && y >= y0 && y <= y1) continue;
      const i = (y * img.width + x) * 4;
      total++;
      if (0.299 * (d[i] as number) + 0.587 * (d[i + 1] as number) + 0.114 * (d[i + 2] as number) < 80) dark++;
    }
  }
  return total ? dark / total : 0;
}

export type BoosterStatus = "waiting" | "confirming" | "armed" | "lost";

export interface BoosterUpdate {
  status: BoosterStatus;
  /** 타이머가 0 이 되는 시각(ms) */
  endAt: number | null;
  /** 이번에 읽은 남은 초 */
  seconds: number | null;
  /** 이번에 새 부스터(새 주기)를 확정했다 */
  started: boolean;
}

/** 읽은 값이 나타내는 끝나는 시각이 이만큼 안이면 같은 흐름 */
const AGREE_MS = 700;
/** 같은 흐름이 이만큼 이어지고 이만큼 여러 번 읽혀야 확정한다(원본은 5초) */
const CONFIRM_MS = 2500;
const CONFIRM_SAMPLES = 4;
/** 이만큼 못 읽으면 놓친 것 */
const LOST_MS = 3000;

/**
 * 부스터 타이머 흐름을 잡는다. 화면 숫자는 실제 시간과 같이 줄어드니 '지금 + 남은 초'(끝나는 시각)가 일정해야 한다.
 * 그 값이 몇 초 동안 일정하게 나올 때만 확정해 엉뚱한 숫자(데미지 등)로 울리지 않게 한다.
 */
export class BoosterWatcher {
  private samples: { at: number; endAt: number }[] = [];
  private endAt: number | null = null;
  private lastSeenAt: number | null = null;

  update(now: number, reading: BoosterReading | null): BoosterUpdate {
    this.samples = this.samples.filter((s) => now - s.at <= CONFIRM_MS * 2.5);
    if (this.endAt !== null && now > this.endAt + 1000) {
      this.endAt = null;
      this.lastSeenAt = null;
    }
    if (reading) {
      const implied = now + reading.seconds * 1000;
      if (this.endAt !== null && Math.abs(implied - this.endAt) <= AGREE_MS * 2) {
        this.endAt = this.endAt * 0.8 + implied * 0.2;
        this.lastSeenAt = now;
        return { status: "armed", endAt: this.endAt, seconds: reading.seconds, started: false };
      }
      this.samples.push({ at: now, endAt: implied });
      const agree = this.samples.filter((s) => Math.abs(s.endAt - implied) <= AGREE_MS);
      const span = now - Math.min(...agree.map((s) => s.at));
      if (agree.length >= CONFIRM_SAMPLES && span >= CONFIRM_MS) {
        const sorted = agree.map((s) => s.endAt).sort((a, b) => a - b);
        this.endAt = sorted[Math.floor(sorted.length / 2)] as number;
        this.lastSeenAt = now;
        this.samples = [];
        return { status: "armed", endAt: this.endAt, seconds: reading.seconds, started: true };
      }
      return { status: "confirming", endAt: this.endAt, seconds: reading.seconds, started: false };
    }
    if (this.endAt !== null) {
      const lost = this.lastSeenAt === null || now - this.lastSeenAt > LOST_MS;
      return { status: lost ? "lost" : "armed", endAt: this.endAt, seconds: null, started: false };
    }
    // 확인 중에 한두 번 못 읽어도 확인 중으로 본다(마지막으로 읽은 흐름 기준 남은 초)
    const last = this.samples[this.samples.length - 1];
    if (last && now - last.at <= 1500) {
      return { status: "confirming", endAt: null, seconds: Math.max(0, (last.endAt - now) / 1000), started: false };
    }
    return { status: "waiting", endAt: null, seconds: null, started: false };
  }
}
