import type { ReadNumber } from "./digits";
import { IconTracker } from "./tracker";

/**
 * 퀵슬롯 방식: 스킬 아이콘 위 노란 쿨타임 숫자가 1초에 1씩 줄기 시작하면 방금 그 스킬을 쓴 것이다.
 * 쿨타임(초)을 알면 지금 숫자로 쓴 시각을 거꾸로 계산하고, 모르면 숫자를 잡은 때(약 2초 뒤)를 기준으로 본다.
 * 버프칸에 아이콘이 안 뜨는 직업 설치기(원본 사이트의 '퀵슬롯 방식')용.
 */
export interface QuickslotResult {
  /** 이번에 새로 잡은 스킬 사용 시각(ms). 같은 쿨타임을 따라가는 중이면 null */
  castAt: number | null;
  /** 읽은 쿨타임 숫자 */
  value: number | null;
  tracking: boolean;
}

/** 숫자를 잡는 데 걸리는 시간(1초 간격 두 번 감소 확인) */
const CONFIRM_MS = 2000;
/** 쿨타임을 모를 때 다시 쓴 것으로 보는 최소 간격 */
const MIN_RECAST_MS = 10_000;
/** 이만큼 숫자가 안 보이다가 나타나야 '새로 쓴 것'(쿨타임을 모를 때) */
const FRESH_GAP_MS = 3000;

export class QuickslotWatcher {
  // 영역이 아이콘 하나라 위치 허용폭은 따지지 않는다
  private readonly tracker = new IconTracker({ reach: Number.POSITIVE_INFINITY });
  private lastCastAt: number | null = null;
  private lastNumberAt: number | null = null;
  private appearedAt: number | null = null;

  update(now: number, numbers: readonly ReadNumber[], cooldownSec: number | null): QuickslotResult {
    // 영역 안에서 가장 큰 숫자(아이콘 가운데 쿨타임). 쿨타임보다 큰 값은 잘못 읽은 것으로 본다.
    const main = [...numbers].sort((a, b) => b.h - a.h)[0];
    const plausible = main && (cooldownSec === null || main.value <= cooldownSec + 2) ? main : undefined;
    if (plausible) {
      if (this.lastNumberAt === null || now - this.lastNumberAt > FRESH_GAP_MS) this.appearedAt = now;
      this.lastNumberAt = now;
    }
    const r = this.tracker.update(now, plausible ? [{ value: plausible.value, cx: plausible.cx, distance: 0 }] : []);
    const tracking = r.status === "tracking";
    const none = { castAt: null, value: r.value, tracking };
    if (!tracking || !r.restarted || r.endAt === null) return none;

    const castAt = cooldownSec !== null ? r.endAt - cooldownSec * 1000 : now - CONFIRM_MS;
    // 스킬은 쿨타임이 끝나기 전에 다시 쓸 수 없다 — 그 전에 잡힌 '새 주기'는 숫자를 잘못 읽었거나
    // 놓쳤던 같은 쿨타임을 다시 잡은 것이다(두 자리가 한 자리씩 읽혀 9·5·4… 로 줄어드는 경우 등).
    const minGap = cooldownSec !== null ? cooldownSec * 1000 - 2000 : MIN_RECAST_MS;
    if (this.lastCastAt !== null && castAt < this.lastCastAt + minGap) return none;
    // 쿨타임을 모르면 계산할 수 없으니, 숫자가 막 나타난 때만 새로 쓴 것으로 본다.
    if (cooldownSec === null && (this.appearedAt === null || now - this.appearedAt > CONFIRM_MS + 2000)) return none;
    this.lastCastAt = castAt;
    return { castAt, value: r.value, tracking };
  }
}
