import { useRef, useState } from "react";
import { Play } from "lucide-react";
import { sound } from "../audio/sound";
import {
  defaultSettings,
  mergeSettings,
  VOICES,
  withRandomDelay,
  type FlashColor,
  type FlashStrength,
  type PipSize,
  type RandomDelay,
  type Voice,
} from "../core/settings";
import { Modal, NumberInput, Toggle } from "./components";
import { useStore } from "./store";

