/**
 * 버프칸에서 한 아이콘의 남은 시간을 프레임마다 읽어 "끝나는 시각"을 안정적으로 추정한다.
 * - 처음 잡을 때: 닮은 아이콘의 숫자가 1.5초 이상 "1초에 1씩" 줄어드는 게 확인돼야 잡는다
 *   (분 단위로 표시되는 버프를 초로 잘못 읽어 엉뚱하게 울리는 것을 막는다).
 * - 잡은 뒤: 예상 값(끝나는 시각 − 지금) 근처이고 위치가 가까우면 덜 닮아도 따라간다.
 * - 다시 설치(새 주기)도 처음 잡을 때와 같은 확인을 거친다 — 한 번 잘못 읽은 숫자로 주기가 틀어지지 않게.
 * - 3초 넘게 안 보이면 놓친 것으로 본다.
 */
export interface Candidate {
  /** 판독한 남은 시간(초) */
  value: number;
  /** 버프칸 안 x 위치(px) */
  cx: number;
  /** 등록 아이콘과의 거리 (낮을수록 닮음) */
  distance: number;
}

export type TrackStatus = "idle" | "tracking" | "lost";

export interface TrackResult {
  status: TrackStatus;
  /** 추정 종료 시각(ms) */
  endAt: number | null;
  /** 이번 프레임에 읽은 값 */
  value: number | null;
  /** 이번 프레임에 새 주기가 시작됐는지 */
  restarted: boolean;
}

export interface TrackerOptions {
  /** 처음 잡을 때 허용 거리 */
  loose: number;
  /** 잡은 뒤 따라갈 때 허용 거리 */
  follow: number;
  /** 위치 허용폭(px). 아이콘 한 칸 반쯤 */
  reach: number;
  lostAfterMs: number;
}

// 녹화 영상(아이콘 3종, 2분39초)으로 맞춘 값: 추적률은 높고 다른 아이콘을 잡는 일은 없었다.
export const DEFAULT_TRACKER: TrackerOptions = { loose: 36, follow: 48, reach: 70, lostAfterMs: 3000 };

interface Pending {
  firstAt: number;
  firstValue: number;
  cx: number;
  lastAt: number;
  /** 지금 보이는 값과 그 값으로 바뀐(처음 본) 시각 */
  value: number;
  changedAt: number;
  /** 1초 간격으로 1씩 줄어든 횟수 */
  ticks: number;
}

/** 초 단위 숫자는 1초마다 바뀐다 — 같은 값이 이보다 오래 그대로면 초가 아니다(분 표시·개수 등) */
const TICK_MAX_MS = 1600;
/** 이만큼 연달아 1씩 줄어야 초 카운트로 본다 */
const TICKS_TO_ACQUIRE = 2;

export class IconTracker {
  private endAt: number | null = null;
  private cx: number | null = null;
  private lastSeenAt: number | null = null;
  private pending: Pending | null = null;
  /** 추적 중 마지막으로 본 숫자와 그 숫자로 바뀐 시각 — 초라면 1초마다 바뀐다 */
  private trackValue: number | null = null;
  private trackValueAt = 0;
  private readonly options: TrackerOptions;

  constructor(options: Partial<TrackerOptions> = {}) {
    this.options = { ...DEFAULT_TRACKER, ...options };
  }

  reset(): void {
    this.endAt = null;
    this.cx = null;
    this.lastSeenAt = null;
    this.pending = null;
    this.trackValue = null;
    this.trackValueAt = 0;
  }

  update(now: number, candidates: readonly Candidate[]): TrackResult {
    const o = this.options;
    // 화면 숫자는 남은 초를 올림해서 보여주므로 가운데(−0.5초)로 본다.
    const endOf = (c: Candidate) => now + (c.value - 0.5) * 1000;

    if (this.endAt !== null && this.cx !== null && this.lastSeenAt !== null && now - this.lastSeenAt <= o.lostAfterMs) {
      const cx = this.cx;
      const expected = (this.endAt - now) / 1000 + 0.5;
      const near = candidates
        .filter((c) => c.distance < o.follow && Math.abs(c.cx - cx) <= o.reach)
        .sort((a, b) => a.distance - b.distance);
      let same = near.find((c) => Math.abs(c.value - expected) <= 2.5);
      // 같은 숫자가 1초 넘게 그대로면 초가 아니라 밝은 아이콘의 분 숫자다('2분'을 2초로 계속 붙잡던 문제)
      if (same && same.value === this.trackValue && now - this.trackValueAt > TICK_MAX_MS) same = undefined;
      if (same) {
        if (same.value !== this.trackValue) {
          this.trackValue = same.value;
          this.trackValueAt = now;
        }
        this.endAt = this.endAt * 0.7 + endOf(same) * 0.3;
        this.cx = same.cx;
        this.lastSeenAt = now;
        return { status: "tracking", endAt: this.endAt, value: same.value, restarted: false };
      }
    }

    // 새로 잡기(또는 새 주기): 닮은 후보의 숫자가 초 단위로 줄어드는지 확인한 뒤에만
    const best = candidates
      .filter((c) => c.distance < o.loose && (this.endAt === null || Math.abs(c.value - ((this.endAt - now) / 1000 + 0.5)) > 2.5))
      .sort((a, b) => a.distance - b.distance)[0];
    if (best) {
      const p = this.pending;
      const fresh = (): Pending => ({ firstAt: now, firstValue: best.value, cx: best.cx, lastAt: now, value: best.value, changedAt: now, ticks: 0 });
      if (!p || now - p.lastAt > 1500 || Math.abs(p.cx - best.cx) > o.reach) {
        this.pending = fresh();
      } else if (best.value === p.value) {
        // 같은 숫자가 너무 오래 그대로면(분 표시 '3' 등) 처음부터 다시 센다
        this.pending = now - p.changedAt > TICK_MAX_MS ? fresh() : { ...p, cx: best.cx, lastAt: now };
      } else if (best.value === p.value - 1 && now - p.changedAt <= TICK_MAX_MS) {
        const next: Pending = { ...p, cx: best.cx, lastAt: now, value: best.value, changedAt: now, ticks: p.ticks + 1 };
        const elapsed = (now - p.firstAt) / 1000;
        const dropped = p.firstValue - best.value;
        // 1초 간격으로 두 번 연달아 줄었고, 줄어든 만큼이 흘러간 초와 비슷해야 초 단위 표시로 본다.
        // 분 표시가 '3'→'2' 로 한 번 바뀐 것을 남은 2초로 잡아 재설치 알림이 반복되던 문제 방지.
        if (next.ticks >= TICKS_TO_ACQUIRE && Math.abs(dropped - elapsed) <= 1.5) return this.acquire(now, best, endOf(best));
        this.pending = next;
      } else {
        this.pending = fresh();
      }
    }

    if (this.lastSeenAt !== null && now - this.lastSeenAt > o.lostAfterMs) {
      return { status: "lost", endAt: this.endAt, value: null, restarted: false };
    }
    return { status: this.endAt === null ? "idle" : "tracking", endAt: this.endAt, value: null, restarted: false };
  }

  private acquire(now: number, candidate: Candidate, endAt: number): TrackResult {
    const restarted = this.endAt === null || Math.abs(this.endAt - endAt) > 2500;
    this.endAt = restarted || this.endAt === null ? endAt : this.endAt * 0.7 + endAt * 0.3;
    this.cx = candidate.cx;
    this.lastSeenAt = now;
    this.pending = null;
    this.trackValue = candidate.value;
    this.trackValueAt = now;
    return { status: "tracking", endAt: this.endAt, value: candidate.value, restarted };
  }
}
