/**
 * 게임 없이 체험·점검할 수 있는 가짜 게임 화면.
 * 50초 주기로 0~20초는 경험치가 오르고(사냥 중), 20~50초는 멈춘다.
 * 경험치바 위치: (0, 692) ~ (1280, 718) — 데모 영역 선택 기준.
 */
export const DEMO_SIZE = { width: 1280, height: 720 } as const;
export const DEMO_EXP_REGION = { x: 0, y: 692, w: 1280, h: 26, srcW: 1280, srcH: 720 } as const;
const CYCLE_MS = 50_000;
const HUNT_MS = 20_000;

export function startDemoCanvas(): { stream: MediaStream; stop: () => void } {
  const canvas = document.createElement("canvas");
  canvas.width = DEMO_SIZE.width;
  canvas.height = DEMO_SIZE.height;
  const ctx = canvas.getContext("2d");
  if (!ctx) throw new Error("캔버스를 만들 수 없어요");
  const startedAt = performance.now();
  let exp = 41.237;
  let lastGain = 0;

  const draw = () => {
    const t = performance.now() - startedAt;
    const phase = t % CYCLE_MS;
    const hunting = phase < HUNT_MS;
    if (hunting && t - lastGain > 1200) {
      exp = Math.min(99.999, exp + 0.013 + Math.random() * 0.04);
      lastGain = t;
    }
    const g = ctx.createLinearGradient(0, 0, 0, DEMO_SIZE.height);
    g.addColorStop(0, "#3c5a7d");
    g.addColorStop(1, "#24364d");
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, DEMO_SIZE.width, DEMO_SIZE.height);

    // 지형
    ctx.fillStyle = "#5b7b3a";
    ctx.fillRect(0, 560, DEMO_SIZE.width, 120);
    ctx.fillStyle = "#7c9b4f";
    ctx.fillRect(160, 420, 360, 18);
    ctx.fillRect(760, 360, 360, 18);

    // 움직이는 캐릭터 (경험치바 밖의 변화)
    const cx = 640 + Math.sin(t / 700) * 380;
    ctx.fillStyle = "#ffd36b";
    ctx.beginPath();
    ctx.arc(cx, 540, 18, 0, Math.PI * 2);
    ctx.fill();

    // 미니맵
    ctx.fillStyle = "rgba(10,20,35,.82)";
    ctx.fillRect(12, 12, 230, 120);
    ctx.strokeStyle = "#9fb3c8";
    ctx.strokeRect(12, 12, 230, 120);
    ctx.fillStyle = "#ffd36b";
    ctx.fillRect(127 + Math.sin(t / 700) * 90, 100, 5, 5);

    // 버프칸
    for (let i = 0; i < 6; i++) {
      ctx.fillStyle = ["#7e57c2", "#26a69a", "#ef6c00", "#5c6bc0", "#8d6e63", "#43a047"][i] as string;
      ctx.fillRect(1030 + i * 40, 12, 34, 34);
    }

    // 안내 문구
    ctx.fillStyle = "rgba(0,0,0,.55)";
    ctx.fillRect(420, 150, 440, 64);
    ctx.fillStyle = "#fff";
    ctx.font = "bold 22px sans-serif";
    ctx.textAlign = "center";
    ctx.fillText(hunting ? "데모: 사냥 중 (경험치 오르는 중)" : "데모: 사냥 멈춤 (경험치 그대로)", 640, 178);
    ctx.font = "14px sans-serif";
    ctx.fillText(`다음 전환까지 ${Math.ceil(((hunting ? HUNT_MS : CYCLE_MS) - phase) / 1000)}초`, 640, 202);

    // 경험치바
    ctx.fillStyle = "#111";
    ctx.fillRect(0, 692, DEMO_SIZE.width, 28);
    ctx.fillStyle = "#3a3a3a";
    ctx.fillRect(0, 706, DEMO_SIZE.width, 10);
    ctx.fillStyle = "#c9e45a";
    ctx.fillRect(0, 706, (DEMO_SIZE.width * exp) / 100, 10);
    ctx.fillStyle = "#fff";
    ctx.font = "bold 12px monospace";
    ctx.textAlign = "center";
    ctx.fillText(`EXP ${Math.round(exp * 123456).toLocaleString()} [${exp.toFixed(3)}%]`, 640, 703);
  };

  draw();
  const timer = setInterval(draw, 66);
  const stream = canvas.captureStream(15);
  return {
    stream,
    stop: () => {
      clearInterval(timer);
      stream.getTracks().forEach((track) => track.stop());
    },
  };
}
