import { Crosshair } from "lucide-react";
import { fmtAgo } from "../../core/format";
import type { Settings } from "../../core/settings";
import { RegionPreview, RepeatEditor, Stat, StatusDot, Toggle, VolumeInput, type Tone } from "../components";
import { Panel, type PanelCommon } from "../Panel";
import { useStore } from "../store";

export function RunePanel({ common, onPick }: { common: PanelCommon; onPick: () => void }) {
  const { settings, update, capture, rune, now } = useStore();
  const config = settings.rune;
  const set = (patch: Partial<Settings["rune"]>) => update((s) => ({ ...s, rune: { ...s.rune, ...patch } }));
  const status: { tone: Tone; label: string } = !capture
    ? { tone: "danger", label: "화면 공유 필요" }
    : !config.region
      ? { tone: "warn", label: "영역 선택 필요" }
      : !config.enabled
        ? { tone: "muted", label: "꺼짐" }
        : rune.present
          ? { tone: "danger", label: "룬 있음!" }
          : { tone: "ok", label: "감시 중" };
  return (
    <Panel
      id="rune"
      common={common}
      active={config.enabled}
      help={
        <ul>
          <li>미니맵의 지도 부분(제목줄·버튼 제외)을 영역으로 잡으면, 분홍·보라색 룬 표시가 나타날 때 알려줘요.</li>
          <li>맵마다 미니맵 크기가 달라서 실제 사냥터에서 영역을 잡아주세요.</li>
          <li>캐릭터와 룬이 겹치거나 보라색 배경이 많은 맵에서는 흔들릴 수 있어요. 반복을 켜면 룬이 남아 있는 동안 다시 알려줘요.</li>
        </ul>
      }
    >
      <div className="row">
        <div className="row-main hunt">
          <Toggle checked={config.enabled} onChange={(enabled) => set({ enabled })} label={config.enabled ? "켜짐" : "꺼짐"} />
          <div className="region-cell">
            <RegionPreview region={config.region} marker={rune.hit} />
            <button className="btn" disabled={!capture} onClick={onPick}>
              <Crosshair size={15} />
              {config.region ? "영역 다시 선택" : "미니맵 영역 선택"}
            </button>
          </div>
          <Stat
            label="룬"
            value={<span data-testid="rune-state">{rune.present ? "있음" : rune.watching ? "없음" : "--"}</span>}
            tone={rune.present ? "danger" : undefined}
          />
          <Stat label="마지막으로 본 때" value={rune.lastSeenAt !== null ? fmtAgo(now - rune.lastSeenAt) : "--"} />
          <Stat label="반복" value={<RepeatEditor value={config.repeat} onChange={(repeat) => set({ repeat })} />} />
          <Stat label="마지막 알림" value={<span data-testid="rune-last-alert">{rune.lastAlertAt !== null ? fmtAgo(now - rune.lastAlertAt) : "--"}</span>} />
          <StatusDot tone={status.tone}>
            <span data-testid="rune-status">{status.label}</span>
          </StatusDot>
        </div>
        <div className="sub-row">
          볼륨
          <VolumeInput value={config.volume} label="룬 알림 볼륨" onChange={(volume) => set({ volume })} />
        </div>
      </div>
    </Panel>
  );
}
