/**
 * 버프칸·퀵슬롯 가운데에 크게 뜨는 남은 시간 숫자 판독.
 * 게임 숫자는 노란 글자 + 두꺼운 검은 테두리라서
 *  1) 노란 픽셀을 뽑고 2) 붙은 덩어리로 나눈 뒤 3) 검은 테두리로 둘러싸인 숫자 크기 덩어리만 남기고
 *  4) 8×12 격자로 정규화해 숫자 견본과 비교한다.
 */
export interface Rgba {
  data: Uint8ClampedArray | Uint8Array;
  width: number;
  height: number;
}

export interface PixelBlob {
  x0: number;
  y0: number;
  x1: number;
  y1: number;
  /** 덩어리에 속한 픽셀 위치 (y * width + x) */
  pixels: number[];
}

export interface DigitBlob extends PixelBlob {
  w: number;
  h: number;
  cx: number;
  cy: number;
  feature: Float32Array;
  aspect: number;
}

export interface DigitTemplate {
  digit: number;
  aspect: number;
  grid: number[];
}

export interface ReadNumber {
  value: number;
  digits: number[];
  x: number;
  y: number;
  w: number;
  h: number;
  cx: number;
  cy: number;
  /** 가장 낮은 숫자 점수 (0~1, 높을수록 확실) */
  score: number;
  /** '분:초' 표시(예: 1:59)를 읽었으면 true — value 는 초로 바꾼 값 */
  colon?: boolean;
}

export const GRID_W = 8;
export const GRID_H = 12;

/** 숫자 안쪽 노랑: 빨강·초록이 높고 파랑이 확실히 낮다 (압축으로 획 가장자리는 어두워질 수 있음) */
export function isDigitFill(r: number, g: number, b: number): boolean {
  return r > 110 && g > 110 && (r + g) / 2 - b > 55 && Math.abs(r - g) < 60;
}

function luma(data: Rgba["data"], i: number): number {
  return 0.299 * (data[i] as number) + 0.587 * (data[i + 1] as number) + 0.114 * (data[i + 2] as number);
}

export function yellowMask(img: Rgba): Uint8Array {
  const mask = new Uint8Array(img.width * img.height);
  for (let p = 0, i = 0; p < mask.length; p++, i += 4) {
    if (isDigitFill(img.data[i] as number, img.data[i + 1] as number, img.data[i + 2] as number)) mask[p] = 1;
  }
  return mask;
}

/** 8방향 연결 덩어리 */
export function components(mask: Uint8Array, width: number, height: number): PixelBlob[] {
  const seen = new Uint8Array(mask.length);
  const blobs: PixelBlob[] = [];
  const stack: number[] = [];
  for (let start = 0; start < mask.length; start++) {
    if (!mask[start] || seen[start]) continue;
    seen[start] = 1;
    stack.push(start);
    const pixels: number[] = [];
    let x0 = width;
    let y0 = height;
    let x1 = -1;
    let y1 = -1;
    while (stack.length) {
      const p = stack.pop() as number;
      pixels.push(p);
      const x = p % width;
      const y = (p - x) / width;
      if (x < x0) x0 = x;
      if (x > x1) x1 = x;
      if (y < y0) y0 = y;
      if (y > y1) y1 = y;
      for (let dy = -1; dy <= 1; dy++) {
        const ny = y + dy;
        if (ny < 0 || ny >= height) continue;
        for (let dx = -1; dx <= 1; dx++) {
          const nx = x + dx;
          if ((dx === 0 && dy === 0) || nx < 0 || nx >= width) continue;
          const q = ny * width + nx;
          if (mask[q] && !seen[q]) {
            seen[q] = 1;
            stack.push(q);
          }
        }
      }
    }
    blobs.push({ x0, y0, x1, y1, pixels });
  }
  return blobs;
}

/** 덩어리 바로 바깥 띠가 얼마나 어두운지 (숫자는 검은 테두리로 둘러싸여 있다) */
export function darkRingRatio(img: Rgba, blob: PixelBlob, pad = 2): number {
  let dark = 0;
  let total = 0;
  const xa = Math.max(0, blob.x0 - pad);
  const xb = Math.min(img.width - 1, blob.x1 + pad);
  const ya = Math.max(0, blob.y0 - pad);
  const yb = Math.min(img.height - 1, blob.y1 + pad);
  for (let y = ya; y <= yb; y++) {
    for (let x = xa; x <= xb; x++) {
      const inside = x >= blob.x0 && x <= blob.x1 && y >= blob.y0 && y <= blob.y1;
      if (inside) continue;
      total++;
      if (luma(img.data, (y * img.width + x) * 4) < 95) dark++;
    }
  }
  return total ? dark / total : 0;
}

/** 덩어리를 GRID_W×GRID_H 격자의 채움 비율로 바꾼다 */
export function normalizeBlob(blob: PixelBlob, width: number): Float32Array {
  const w = blob.x1 - blob.x0 + 1;
  const h = blob.y1 - blob.y0 + 1;
  const local = new Uint8Array(w * h);
  for (const p of blob.pixels) {
    const x = (p % width) - blob.x0;
    const y = Math.floor(p / width) - blob.y0;
    local[y * w + x] = 1;
  }
  const grid = new Float32Array(GRID_W * GRID_H);
  for (let gy = 0; gy < GRID_H; gy++) {
    const ya = (gy * h) / GRID_H;
    const yb = ((gy + 1) * h) / GRID_H;
    for (let gx = 0; gx < GRID_W; gx++) {
      const xa = (gx * w) / GRID_W;
      const xb = ((gx + 1) * w) / GRID_W;
      let covered = 0;
      let area = 0;
      for (let y = Math.floor(ya); y < Math.ceil(yb); y++) {
        const oy = Math.min(yb, y + 1) - Math.max(ya, y);
        if (oy <= 0) continue;
        for (let x = Math.floor(xa); x < Math.ceil(xb); x++) {
          const ox = Math.min(xb, x + 1) - Math.max(xa, x);
          if (ox <= 0) continue;
          area += ox * oy;
          if (local[y * w + x]) covered += ox * oy;
        }
      }
      grid[gy * GRID_W + gx] = area ? covered / area : 0;
    }
  }
  return grid;
}

export function digitCandidates(img: Rgba, mask: Uint8Array = yellowMask(img)): DigitBlob[] {
  const blobs = components(mask, img.width, img.height);
  const out: DigitBlob[] = [];
  for (const blob of blobs) {
    const w = blob.x1 - blob.x0 + 1;
    const h = blob.y1 - blob.y0 + 1;
    if (h < 7 || h > 48) continue;
    if (w < 2 || w > h * 1.1) continue;
    if (blob.pixels.length < h * 1.5) continue;
    if (darkRingRatio(img, blob) < 0.45) continue;
    out.push({
      ...blob,
      w,
      h,
      cx: (blob.x0 + blob.x1) / 2,
      cy: (blob.y0 + blob.y1) / 2,
      aspect: w / h,
      feature: normalizeBlob(blob, img.width),
    });
  }
  return out;
}

/** 쌍점 점은 작아서 압축·확대에 색이 더 바랜다 — 숫자보다 느슨한 노랑 */
function isColonFill(r: number, g: number, b: number): boolean {
  return r > 100 && g > 85 && (r + g) / 2 - b > 30;
}

/**
 * 두 숫자 사이에 쌍점(':')이 있는지 — '분:초' 표시.
 * 같은 수 안의 숫자 사이는 검은 테두리뿐이라 노란 픽셀이 없다. 쌍점은 위·아래 두 점이라
 * 틈(양쪽 글자에 맞닿은 한 줄은 뺀다) 안의 노란 행이 위 절반에 한 덩어리, 아래 절반에 한 덩어리로 나뉜다.
 */
export function colonBetween(img: Rgba, left: PixelBlob, right: PixelBlob): boolean {
  const xa = left.x1 + 2;
  const xb = right.x0 - 2;
  if (xb < xa) return false;
  const top = Math.min(left.y0, right.y0);
  const bottom = Math.max(left.y1, right.y1);
  const h = bottom - top + 1;
  // 글자 위·아래 끝 줄은 번짐·아이콘 그림이 섞일 수 있어 뺀다
  const margin = Math.max(1, Math.round(h * 0.12));
  const runs: { a: number; b: number; n: number }[] = [];
  for (let y = top + margin; y <= bottom - margin; y++) {
    let n = 0;
    for (let x = xa; x <= xb; x++) {
      const i = (y * img.width + x) * 4;
      if (isColonFill(img.data[i] as number, img.data[i + 1] as number, img.data[i + 2] as number)) n++;
    }
    const last = runs[runs.length - 1];
    if (n > 0 && last && last.b === y - 1) {
      last.b = y;
      last.n += n;
    } else if (n > 0) runs.push({ a: y, b: y, n });
  }
  // 한 픽셀짜리 번짐은 점이 아니다
  const dots = runs.filter((r) => r.n >= 2);
  if (dots.length !== 2) return false;
  const [upper, lower] = dots as [{ a: number; b: number; n: number }, { a: number; b: number; n: number }];
  const hu = upper.b - upper.a + 1;
  const hl = lower.b - lower.a + 1;
  const mid = (top + bottom) / 2;
  // 점 두 개는 크기가 비슷하고 작으며, 가운데를 사이에 두고 위·아래에 있다
  return (
    hu <= h * 0.35 &&
    hl <= h * 0.35 &&
    Math.max(hu, hl) <= Math.min(hu, hl) * 2 &&
    (upper.a + upper.b) / 2 < mid &&
    (lower.a + lower.b) / 2 > mid
  );
}

/** 옆으로 붙은 숫자들을 한 수로 묶는다. bridge 가 참이면(쌍점 등) 조금 더 떨어진 숫자도 묶는다 */
export function groupNumbers(digits: DigitBlob[], bridge?: (left: DigitBlob, right: DigitBlob) => boolean): DigitBlob[][] {
  const sorted = [...digits].sort((a, b) => a.cx - b.cx);
  const groups: DigitBlob[][] = [];
  for (const digit of sorted) {
    const group = groups.find((g) => {
      const last = g[g.length - 1] as DigitBlob;
      const ratio = digit.h / last.h;
      const gap = digit.x0 - last.x1;
      return (
        ratio > 0.75 &&
        ratio < 1.33 &&
        Math.abs(digit.cy - last.cy) <= last.h * 0.35 &&
        (gap <= last.h * 0.6 || (bridge !== undefined && gap <= last.h * 0.95 && bridge(last, digit))) &&
        digit.x0 >= last.x0
      );
    });
    if (group) group.push(digit);
    else groups.push([digit]);
  }
  return groups;
}

export function digitScore(feature: Float32Array, aspect: number, template: DigitTemplate): number {
  let diff = 0;
  for (let i = 0; i < feature.length; i++) diff += Math.abs((feature[i] as number) - (template.grid[i] as number));
  return Math.max(0, 1 - diff / feature.length - Math.abs(aspect - template.aspect) * 0.6);
}

export function classifyDigit(blob: DigitBlob, templates: readonly DigitTemplate[]): { digit: number; score: number } {
  let best = { digit: -1, score: -1 };
  for (const template of templates) {
    const score = digitScore(blob.feature, blob.aspect, template);
    if (score > best.score) best = { digit: template.digit, score };
  }
  return best;
}

export function readNumbers(img: Rgba, templates: readonly DigitTemplate[], minScore = 0.55): ReadNumber[] {
  const mask = yellowMask(img);
  const colon = (left: PixelBlob, right: PixelBlob) => colonBetween(img, left, right);
  const out: ReadNumber[] = [];
  for (const group of groupNumbers(digitCandidates(img, mask), colon)) {
    if (group.length > 4) continue;
    const classified = group.map((blob) => classifyDigit(blob, templates));
    const score = Math.min(...classified.map((c) => c.score));
    if (score < minScore) continue;
    const digits = classified.map((c) => c.digit);
    // '분:초'(예: 1:59) — 쌍점 앞은 한두 자리 분, 뒤는 정확히 두 자리 초여야 한다
    let split = group.findIndex((blob, i) => i > 0 && colon(group[i - 1] as DigitBlob, blob));
    let value = Number(digits.join(""));
    if (split > 0) {
      const seconds = digits.slice(split);
      const ss = seconds.length === 2 ? (seconds[0] as number) * 10 + (seconds[1] as number) : 60;
      if (split <= 2 && ss < 60) {
        value = Number(digits.slice(0, split).join("")) * 60 + ss;
      } else {
        // 분:초 모양이 아니면 쌍점을 잘못 본 것 — 보통 간격으로만 묶인 수는 그대로, 멀리 떨어진 묶음은 버린다
        const bridged = group.some((blob, i) => i > 0 && blob.x0 - (group[i - 1] as DigitBlob).x1 > (group[i - 1] as DigitBlob).h * 0.6);
        if (bridged) continue;
        split = -1;
      }
    }
    const x0 = Math.min(...group.map((g) => g.x0));
    const x1 = Math.max(...group.map((g) => g.x1));
    const y0 = Math.min(...group.map((g) => g.y0));
    const y1 = Math.max(...group.map((g) => g.y1));
    out.push({
      value,
      digits,
      x: x0,
      y: y0,
      w: x1 - x0 + 1,
      h: y1 - y0 + 1,
      cx: (x0 + x1) / 2,
      cy: (y0 + y1) / 2,
      score,
      ...(split > 0 ? { colon: true } : {}),
    });
  }
  return out;
}
